    [10_567, 4_247, 2_375, 14_967, 28_384, 4_557, 13_827, 22_798];
type Polynomial = Vec<u64>;
/// Public operation budget for the first-release exact BFV evaluator bridge.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct BfvEvaluationBudget {
    /// Maximum ciphertext-ciphertext multiplicative depth.
    pub max_multiplicative_depth: u16,
    /// Maximum public bootstrap refresh rounds.
    pub max_bootstrap_refresh_rounds: u16,
}
impl BfvEvaluationBudget {
    /// Return the budget used by the first-release exact BFV evaluator bridge.
    #[must_use]
    pub const fn exact_evaluator_v1() -> Self {
        Self {
            max_multiplicative_depth: BFV_EXACT_EVALUATOR_MAX_MULTIPLICATIVE_DEPTH,
            max_bootstrap_refresh_rounds: BFV_BOOTSTRAP_KEY_MAX_REFRESH_ROUNDS,
        }
    }
    /// Validate a planned BFV evaluation against this budget.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the plan exceeds the published evaluator budget.
    pub fn validate_plan(self, plan: BfvEvaluationPlan) -> Result<(), BfvError> {
        invalid_guards! {
            plan.input_ciphertexts == 0
            => ("BFV evaluation plan requires at least one input ciphertext"),
            plan.ciphertext_multiplication_depth > self.max_multiplicative_depth
            => ("BFV evaluation multiplicative depth {} exceeds budget {}",
                plan.ciphertext_multiplication_depth,
                self.max_multiplicative_depth),
            plan.bootstrap_refresh_rounds > self.max_bootstrap_refresh_rounds
            => ("BFV bootstrap refresh rounds {} exceed budget {}",
                plan.bootstrap_refresh_rounds,
                self.max_bootstrap_refresh_rounds),
            plan.ciphertext_multiplication_depth > 0 && plan.input_ciphertexts < 2
            => ("BFV multiplicative depth requires at least two input ciphertexts"),
            plan.bootstrap_refresh_rounds > 0 && plan.input_ciphertexts != 1
            => ("BFV bootstrap refresh requires exactly one input ciphertext"),
        }
        Ok(())
    }
}
/// Planned BFV operation shape admitted before ciphertext evaluation.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct BfvEvaluationPlan {
    /// Number of ciphertext input envelopes.
    pub input_ciphertexts: u16,
    /// Balanced ciphertext-ciphertext multiplicative depth.
    pub ciphertext_multiplication_depth: u16,
    /// Public bootstrap refresh rounds consumed by the operation.
    pub bootstrap_refresh_rounds: u16,
}
impl BfvEvaluationPlan {
    /// Build a plan for ciphertext addition over at least two inputs.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the input count is below the addition arity or exceeds the
    /// supported plan range.
    pub fn add(input_count: usize) -> Result<Self, BfvError> {
        invalid_if!(
            input_count < 2,
            "BFV addition requires at least two input ciphertexts"
        );
        Ok(Self {
            input_ciphertexts: checked_plan_input_count(input_count)?,
            ciphertext_multiplication_depth: 0,
            bootstrap_refresh_rounds: 0,
        })
    }
    /// Build a plan for a balanced ciphertext multiplication tree.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the input count is zero or exceeds the supported plan range.
    pub fn balanced_multiply(input_count: usize) -> Result<Self, BfvError> {
        Ok(Self {
            input_ciphertexts: checked_plan_input_count(input_count)?,
            ciphertext_multiplication_depth: bfv_balanced_multiplication_depth(input_count)?,
            bootstrap_refresh_rounds: 0,
        })
    }
    /// Build a plan for one ciphertext rotation.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the operation does not have exactly one input.
    pub fn rotate_left(input_count: usize) -> Result<Self, BfvError> {
        invalid_if!(
            input_count != 1,
            "BFV rotation requires exactly one input ciphertext"
        );
        Ok(Self {
            input_ciphertexts: 1,
            ciphertext_multiplication_depth: 0,
            bootstrap_refresh_rounds: 0,
        })
    }
    /// Build a plan for public bootstrap refresh rounds over exactly one input.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the operation does not have exactly one input or no refresh rounds
    /// are requested.
    pub fn bootstrap_refresh(input_count: usize, rounds: u16) -> Result<Self, BfvError> {
        invalid_guards! {
            rounds == 0 => ("BFV bootstrap refresh requires at least one round"),
            input_count != 1 => ("BFV bootstrap refresh requires exactly one input ciphertext"),
        }
        Ok(Self {
            input_ciphertexts: 1,
            ciphertext_multiplication_depth: 0,
            bootstrap_refresh_rounds: rounds,
        })
    }
}
fn checked_plan_input_count(input_count: usize) -> Result<u16, BfvError> {
    u16::try_from(input_count)
        .map_err(|_| invalid!("BFV evaluation input count exceeds u16 bounds"))
}
/// Return the multiplicative depth of a deterministic balanced multiply tree.
///
/// # Errors
/// Returns [`BfvError`] when `input_count` is zero or the depth calculation exceeds deterministic
/// bounds.
pub fn bfv_balanced_multiplication_depth(input_count: usize) -> Result<u16, BfvError> {
    invalid_if!(
        input_count == 0,
        "BFV balanced multiplication requires at least one input"
    );
    let mut covered = 1_usize;
    let mut depth = 0_u16;
    while covered < input_count {
        covered = covered.checked_mul(2).ok_or_else(|| {
            invalid!("BFV balanced multiplication input count exceeds deterministic bounds")
        })?;
        depth = depth
            .checked_add(1)
            .ok_or_else(|| invalid!("BFV balanced multiplication depth exceeds u16 bounds"))?;
    }
    Ok(depth)
}
/// Polynomial multiplication backend selected for BFV ring products.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BfvConvolutionBackend {
    /// Textbook schoolbook negacyclic multiplication.
    ScalarSchoolbook,
    /// Exact CRT-NTT negacyclic multiplication.
    CrtNtt,
}
/// BFV parameter set.
#[cfg_attr(feature = "json", derive(JsonSerialize, JsonDeserialize))]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Encode, Decode, IntoSchema, norito::NoritoSchema)]
#[norito_schema(name = "iroha_crypto::fhe_bfv::BfvParameters")]
pub struct BfvParameters {
    /// Ring degree `n` for `Z_q[x] / (x^n + 1)`. Must be a power of two.
    pub polynomial_degree: u16,
    /// Ciphertext modulus `q`.
    pub ciphertext_modulus: u64,
    /// Plaintext modulus `t`.
    pub plaintext_modulus: u64,
    /// Base-2 logarithm of the relinearization decomposition base.
    pub decomposition_base_log: u8,
}
impl BfvParameters {
    /// Validate the parameter set.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the parameter set is internally inconsistent.
    pub fn validate(&self) -> Result<(), BfvError> {
        let n = usize::from(self.polynomial_degree);
        invalid_guards! {
            n < 2 || !n.is_power_of_two()
            => ("polynomial_degree must be a power of two and at least 2"),
            self.plaintext_modulus < 2 => ("plaintext_modulus must be at least 2"),
            self.ciphertext_modulus <= self.plaintext_modulus
            => ("ciphertext_modulus must be greater than plaintext_modulus"),
            !self
            .ciphertext_modulus
            .is_multiple_of(self.plaintext_modulus)
            => ("ciphertext_modulus must be divisible by plaintext_modulus"),
        }
        let error_headroom = self
            .plaintext_modulus
            .checked_mul(u64::from(BFV_ERROR_MULTIPLE_BOUND) * 2)
            .ok_or_else(|| {
                invalid!("plaintext-multiple error profile exceeds ciphertext modulus bounds")
            })?;
        invalid_guards! {
            self.ciphertext_modulus <= error_headroom => (
                "ciphertext_modulus must exceed 2 * plaintext_modulus * BFV error bound {BFV_ERROR_MULTIPLE_BOUND}"
            ),
            self.decomposition_base_log == 0 || self.decomposition_base_log > 16
            => ("decomposition_base_log must be within 1..=16"),
        }
        let max_raw_coefficient = u128::from(self.polynomial_degree)
            .checked_mul(u128::from(self.ciphertext_modulus))
            .and_then(|value| value.checked_mul(u128::from(self.ciphertext_modulus)))
            .ok_or_else(|| {
                BfvError::InvalidParameters(
                    "parameter set exceeds the deterministic BFV exact-arithmetic raw coefficient bounds"
                        .to_owned(),
                )
            })?;
        let max_scaled_coefficient = max_raw_coefficient
            .checked_mul(u128::from(self.plaintext_modulus))
            .ok_or_else(|| {
                BfvError::InvalidParameters(
                    "parameter set exceeds the deterministic BFV exact-arithmetic scaled coefficient bounds"
                        .to_owned(),
                )
            })?;
        invalid_if!(
            max_scaled_coefficient > i128::MAX as u128,
            "parameter set exceeds the deterministic BFV exact-arithmetic overflow bounds"
        );
        Ok(())
    }
    /// Report the polynomial-convolution backend used for BFV ring products.
    #[must_use]
    pub fn convolution_backend(&self) -> BfvConvolutionBackend {
        #[cfg(not(feature = "bfv-accel"))]
        let _ = self;
        #[cfg(feature = "bfv-accel")]
        {
            let Some(convolution_len) = self.degree().checked_mul(2) else {
                return BfvConvolutionBackend::ScalarSchoolbook;
            };
            if convolution_len == 0 {
                return BfvConvolutionBackend::ScalarSchoolbook;
            }
            if fhe_ntt::crt_ntt_supports_convolution_len(convolution_len) {
                return BfvConvolutionBackend::CrtNtt;
            }
        }
        BfvConvolutionBackend::ScalarSchoolbook
    }
    fn degree(&self) -> usize {
        usize::from(self.polynomial_degree)
    }
    fn decomposition_base(&self) -> u64 {
        1_u64 << self.decomposition_base_log
    }
    fn decomposition_digits(&self) -> Result<usize, BfvError> {
        self.validate()?;
        let mut digits = 0_usize;
        let mut covered = 1_u128;
        let base = u128::from(self.decomposition_base());
        let modulus = u128::from(self.ciphertext_modulus);
        while covered < modulus {
            covered = covered.checked_mul(base).ok_or_else(|| {
                invalid!("BFV decomposition digit coverage exceeds deterministic limits")
            })?;
            digits = digits.checked_add(1).ok_or_else(|| {
                invalid!("BFV decomposition digit count exceeds deterministic limits")
            })?;
        }
        Ok(digits.max(1))
    }
}
/// BFV RNS coefficient-modulus chain.
#[cfg_attr(feature = "json", derive(JsonSerialize, JsonDeserialize))]
#[derive(Clone, Debug, PartialEq, Eq, Encode, Decode, IntoSchema, norito::NoritoSchema)]
