    BfvParameters {
        polynomial_degree: 64,
        ciphertext_modulus: RAM_LFE_BFV_CIPHERTEXT_MODULUS,
        plaintext_modulus: RAM_LFE_BFV_PLAINTEXT_MODULUS,
        decomposition_base_log: 12,
    }
