fn validate_bfv_admission_public_key_proof_input_material_context_v1(
    label: &str,
    material_params: &BfvParameters,
    material_public_key: &BfvPublicKey,
    expected_params: &BfvParameters,
    expected_public_key: &BfvPublicKey,
) -> Result<(), BfvError> {
    invalid_guards! {
        material_params != expected_params => ("{label} parameter mismatch"),
        material_public_key != expected_public_key => ("{label} public key mismatch"),
    }
    Ok(())
}
#[allow(clippy::too_many_arguments)]
fn validate_bfv_admission_ciphertext_proof_input_material_context_v1(
    label: &str,
    mode: BfvRefreshTranscriptMode,
    material_params: &BfvParameters,
    material_public_key: &BfvPublicKey,
    material_ciphertext: &BfvCiphertext,
    material_declared_bound: u128,
    expected_params: &BfvParameters,
    expected_public_key: &BfvPublicKey,
    expected_ciphertext: &BfvCiphertext,
    expected_declared_bound: u128,
) -> Result<(), BfvError> {
    validate_bfv_admission_public_key_proof_input_material_context_v1(
        label,
        material_params,
        material_public_key,
        expected_params,
        expected_public_key,
    )?;
    invalid_if!(
        material_ciphertext != expected_ciphertext,
        "{label} ciphertext mismatch"
    );
    match mode {
        BfvRefreshTranscriptMode::Exact => validate_exact_residual_bound_within_centered_capacity(
            expected_params,
            expected_declared_bound,
            "exact-residual BFV ciphertext proof input caller-declared bound",
        )?,
        BfvRefreshTranscriptMode::BoundedNoise => {
            validate_bounded_noise_bound_within_decoding_capacity(
                expected_params,
                expected_declared_bound,
                "bounded-noise BFV ciphertext proof input caller-declared bound",
            )?
        }
    }
    invalid_if!(
        material_declared_bound != expected_declared_bound,
        "{label} declared bound mismatch"
    );
    Ok(())
}
fn decode_bfv_canonical_material_bytes_v1<T>(
    label: &str,
    encoded_kind: &str,
    bytes: &[u8],
    validate: impl FnOnce(&T) -> Result<(), BfvError>,
) -> Result<T, BfvError>
where
    T: for<'__frame> norito::NoritoDeserialize<'__frame> + norito::NoritoSerialize,
{
    invalid_guards! {
        bytes.is_empty() => ("{label} must not be empty"),
        bytes.iter().all(|&byte| byte == 0) => ("{label} must not be all-zero"),
    }
    let material = norito::decode_canonical::<T>(bytes).map_err(|err| {
        invalid!("{label} must use canonical v1 bytes containing {encoded_kind}: {err}")
    })?;
    validate(&material)?;
    Ok(material)
}
fn bfv_canonical_material_digest_v1<T: norito::NoritoSerialize>(
    label: &str,
    domain: &[u8],
    material: &T,
) -> Result<Hash, BfvError> {
    let bytes = norito::encode_canonical(material)
        .map_err(|err| invalid!("{label} encoding failed: {err}"))?;
    Ok(Hash::new_from_chunks(&[domain, bytes.as_slice()]))
}
fn validate_public_key_not_all_zero(public_key: &BfvPublicKey) -> Result<(), BfvError> {
    invalid_guards! {
        !public_key.b.is_empty() && public_key.b.iter().all(|&coefficient| coefficient == 0)
        => ("BFV public key b component must not be all zero"),
        !public_key.a.is_empty() && public_key.a.iter().all(|&coefficient| coefficient == 0)
        => ("BFV public key a component must not be all zero"),
    }
    Ok(())
}
/// Public affine circuit over scalar ciphertext inputs.
#[cfg_attr(feature = "json", derive(JsonSerialize, JsonDeserialize))]
#[derive(Clone, Debug, PartialEq, Eq, Encode, Decode, IntoSchema, norito::NoritoSchema)]
#[norito_schema(name = "iroha_crypto::fhe_bfv::BfvAffineCircuit")]
pub struct BfvAffineCircuit {
    /// Output rows; each row stores one plaintext weight per input ciphertext.
    pub weights: Vec<Vec<u64>>,
    /// Plaintext bias added to each output row.
    pub bias: Vec<u64>,
}
impl BfvAffineCircuit {
    /// Validate the circuit shape and plaintext coefficients.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the circuit shape is invalid.
    pub fn validate(&self, params: &BfvParameters, input_count: usize) -> Result<(), BfvError> {
        params.validate()?;
        if self.weights.is_empty() {
            return Err(BfvError::InvalidCircuit(
                "affine circuit must have at least one output row".to_owned(),
            ));
        }
        if self.weights.len() != self.bias.len() {
            return Err(BfvError::InvalidCircuit(
                "weights and bias must have the same outer length".to_owned(),
            ));
        }
        for (row_index, row) in self.weights.iter().enumerate() {
            if row.len() != input_count {
                return Err(BfvError::InvalidCircuit(format!(
                    "weights[{row_index}] expected {input_count} inputs, found {}",
                    row.len()
                )));
            }
            for &weight in row {
                if weight >= params.plaintext_modulus {
                    return Err(BfvError::InvalidCircuit(format!(
                        "weight {weight} exceeds plaintext modulus {}",
                        params.plaintext_modulus
                    )));
                }
            }
        }
        for &bias in &self.bias {
            if bias >= params.plaintext_modulus {
                return Err(BfvError::InvalidCircuit(format!(
                    "bias {bias} exceeds plaintext modulus {}",
                    params.plaintext_modulus
                )));
            }
        }
        Ok(())
    }
}
/// Errors raised by the deterministic BFV baseline.
#[derive(Clone, Debug, Error, PartialEq, Eq)]
pub enum BfvError {
    /// The sole exact profile is known insecure and cannot be qualified by adding evidence.
    #[error("BFV production qualification unavailable: {0:?}")]
    ProductionQualificationUnavailable(BfvProductionSupportBlockerV1),
    /// Eight-party decryption has no sound public verifier for the secret-share and decryption-share relations.
    #[error("BFV eight-party decryption share relation proof verifier is unavailable")]
    EightPartyShareRelationProofUnavailable,
    /// The parameter set is invalid.
    #[error("invalid BFV parameters: {0}")]
    InvalidParameters(String),
    /// The ciphertext or key shape does not match the parameter set.
    #[error("shape mismatch: {0}")]
    ShapeMismatch(String),
    /// Plaintext coefficients exceed the plaintext modulus.
    #[error("plaintext coefficient {coefficient} exceeds plaintext modulus {plaintext_modulus}")]
    PlaintextOutOfRange {
        /// Offending plaintext coefficient.
        coefficient: u64,
        /// Active plaintext modulus.
        plaintext_modulus: u64,
    },
    /// The affine circuit is invalid.
    #[error("invalid affine circuit: {0}")]
    InvalidCircuit(String),
    /// The identifier input does not fit the configured BFV envelope.
    #[error("identifier input exceeds the maximum supported length of {max_input_bytes} bytes")]
    InputTooLong {
        /// Maximum supported identifier byte length.
        max_input_bytes: u16,
    },
    /// The identifier envelope is malformed after decryption.
    #[error("invalid BFV identifier envelope: {0}")]
    InvalidIdentifierEncoding(String),
}
/// Deterministic BFV key generation from a seed.
///
/// # Errors
/// Returns [`BfvError`] when parameters are invalid or the deterministic seed is empty or
/// oversized.
pub(crate) fn keygen_from_seed(
    params: &BfvParameters,
    seed: &[u8],
) -> Result<(BfvSecretKey, BfvPublicKey, BfvRelinearizationKey), BfvError> {
    validate_deterministic_seed("BFV keygen seed", seed)?;
    validate_bfv_seeded_encryption_residual_capacity(params)?;
    let mut rng = derive_rng(KEYGEN_DOMAIN, seed);
    let secret_key = BfvSecretKey {
        s: sample_nonzero_secret_poly(params, &mut rng),
    };
    let (b, a) = loop {
        let a = sample_nonzero_uniform_poly(params, &mut rng);
        let e = Zeroizing::new(sample_nonzero_error_poly(params, &mut rng));
        let as_product = Zeroizing::new(poly_mul_mod(params, &a, &secret_key.s));
        let negated_product = Zeroizing::new(poly_neg_mod(params, &as_product));
        let b = poly_sub_mod(params, &negated_product, &e);
        if b.iter().any(|&coefficient| coefficient != 0) {
            break (b, a);
        }
    };
    let secret_sq = Zeroizing::new(poly_mul_mod(params, &secret_key.s, &secret_key.s));
    let relin_entries = key_switch_entries_from_rng(params, &secret_key.s, &secret_sq, &mut rng)?;
    let public_key = BfvPublicKey { b, a };
    let relinearization_key = BfvRelinearizationKey {
        entries: relin_entries,
    };
    validate_public_key_secret_consistency(params, &secret_key, &public_key)?;
    validate_key_switch_entry_residuals(
        params,
        &secret_key.s,
        &secret_sq,
        &relinearization_key.entries,
        "generated relinearization key",
    )?;
    Ok((secret_key, public_key, relinearization_key))
}
/// Verify that a BFV public key is consistent with a secret key.
///
/// This is a key-owner diagnostic for key material construction. It checks that `b + a*s` decrypts
/// as a plaintext-modulus-multiple error term within the current deterministic exact evaluator
/// bound. It is not a public proof that a published key was honestly generated.
///
/// # Errors
/// Returns [`BfvError`] when the key material is malformed or inert, the public key does not match
/// `secret_key`, or the public-key residual exceeds the current error profile.
pub fn validate_public_key_secret_consistency(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    public_key: &BfvPublicKey,
) -> Result<(), BfvError> {
    validate_public_key(params, public_key)?;
    validate_public_key_not_all_zero(public_key)?;
    validate_secret_key(params, secret_key)?;
    let product = Zeroizing::new(poly_mul_mod(params, &public_key.a, &secret_key.s));
    let residual = Zeroizing::new(poly_add_mod(params, &public_key.b, &product));
    validate_plaintext_multiple_residual_bound(params, &residual, &zero_poly(params), "public key")
}
/// Deterministic bounded-noise BFV public-key generation from a seed.
///
/// This generates the same secret/public key shapes as [`keygen_from_seed`], but samples public-key
/// error coefficients from a centered small-noise distribution rather than plaintext-modulus
/// multiples. It is the keygen entry for the rounded BFV-RNS replacement path; evaluation-key
/// material is still produced by the exact-lift bridge until the full bounded-noise key-switching
/// path lands.
///
/// # Errors
/// Returns [`BfvError`] when parameters are invalid, the rounded-decoding capacity is too narrow
/// for seeded encryption noise, or the deterministic seed is empty or oversized.
#[cfg(any(test, feature = "bfv-test-fixtures"))]
pub(crate) fn keygen_bounded_noise_from_seed(
    params: &BfvParameters,
    seed: &[u8],
) -> Result<(BfvSecretKey, BfvPublicKey), BfvError> {
    let (secret_key, public_key, _) =
        keygen_bounded_noise_with_relinearization_from_seed(params, seed)?;
    Ok((secret_key, public_key))
}
/// Deterministic bounded-noise BFV key generation with relinearization material.
///
/// The relinearization entries encrypt raw `base^i * s^2` key-switch material with small centered
/// error. They are intended for [`multiply_ciphertexts_bounded_noise`], not the exact-lift
/// evaluator.
///
/// # Errors
/// Returns [`BfvError`] when parameters are invalid, the rounded-decoding capacity is too narrow
/// for seeded encryption noise, or the deterministic seed is empty or oversized.
#[cfg(any(test, feature = "bfv-test-fixtures"))]
pub(crate) fn keygen_bounded_noise_with_relinearization_from_seed(
    params: &BfvParameters,
    seed: &[u8],
) -> Result<(BfvSecretKey, BfvPublicKey, BfvRelinearizationKey), BfvError> {
    validate_deterministic_seed("bounded-noise BFV keygen seed", seed)?;
    validate_bfv_bounded_noise_encryption_capacity(params)?;
    let mut rng = derive_rng(BOUNDED_NOISE_KEYGEN_DOMAIN, seed);
    let secret_key = BfvSecretKey {
        s: sample_nonzero_secret_poly(params, &mut rng),
    };
    let (b, a) = loop {
        let a = sample_nonzero_uniform_poly(params, &mut rng);
        let e = Zeroizing::new(sample_nonzero_bounded_noise_poly(params, &mut rng));
        let as_product = Zeroizing::new(poly_mul_mod(params, &a, &secret_key.s));
        let negated_product = Zeroizing::new(poly_neg_mod(params, &as_product));
        let b = poly_sub_mod(params, &negated_product, &e);
        if b.iter().any(|&coefficient| coefficient != 0) {
            break (b, a);
        }
    };
    let public_key = BfvPublicKey { b, a };
    let secret_sq = Zeroizing::new(poly_mul_mod(params, &secret_key.s, &secret_key.s));
    let relinearization_key = BfvRelinearizationKey {
        entries: key_switch_entries_bounded_noise_from_rng(
            params,
            &secret_key.s,
            &secret_sq,
            &mut rng,
        )?,
    };
    validate_bounded_noise_public_key_secret_consistency(params, &secret_key, &public_key)?;
    validate_bounded_noise_relinearization_key_secret_consistency(
        params,
        &secret_key,
        &relinearization_key,
    )?;
    Ok((secret_key, public_key, relinearization_key))
}
/// Verify that a rounded BFV public key is consistent with a secret key.
///
/// This key-owner diagnostic checks that `b + a*s` is bounded centered noise, not a
/// plaintext-modulus-multiple residual. It is not a public proof that a published key was honestly
/// generated.
///
/// # Errors
/// Returns [`BfvError`] when key material is malformed or inert, does not match `secret_key`, or
/// exceeds the bounded-noise keygen error profile.
pub fn validate_bounded_noise_public_key_secret_consistency(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    public_key: &BfvPublicKey,
) -> Result<(), BfvError> {
    validate_public_key(params, public_key)?;
    validate_public_key_not_all_zero(public_key)?;
    validate_secret_key(params, secret_key)?;
    let product = Zeroizing::new(poly_mul_mod(params, &public_key.a, &secret_key.s));
    let residual = Zeroizing::new(poly_add_mod(params, &public_key.b, &product));
    validate_centered_noise_bound(
        params,
        &residual,
        u128::from(BFV_BOUNDED_NOISE_COEFFICIENT_BOUND),
        "bounded-noise public key",
    )
}
/// Verify that a bounded-noise relinearization key matches a secret key.
///
/// # Errors
