/// Encrypt a plaintext polynomial from a seed.
///
/// The plaintext is encoded coefficient-wise under the plaintext modulus. The caller may pass fewer
/// than `polynomial_degree` coefficients; the remainder are treated as zero.
///
/// # Errors
/// Returns [`BfvError`] when parameters, plaintext, key shapes, public-key material, or the
/// deterministic seed are invalid.
pub(crate) fn encrypt_from_seed(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    plaintext: &[u64],
    seed: &[u8],
) -> Result<BfvCiphertext, BfvError> {
    validate_plaintext(params, plaintext)?;
    validate_deterministic_seed("BFV encryption seed", seed)?;
    validate_bfv_seeded_encryption_residual_capacity(params)?;
    validate_public_key(params, public_key)?;
    validate_public_key_not_all_zero(public_key)?;
    let encoded_plaintext = Zeroizing::new(encode_plaintext(params, plaintext));
    let mut rng = derive_rng(BFV_ENCRYPT_SEED_DERIVATION_DOMAIN, seed);
    let u = Zeroizing::new(sample_nonzero_small_poly(params, &mut rng));
    let e1 = Zeroizing::new(sample_nonzero_error_poly(params, &mut rng));
    let e2 = Zeroizing::new(sample_nonzero_error_poly(params, &mut rng));
    let product_b = Zeroizing::new(poly_mul_mod(params, &public_key.b, &u));
    let noisy_b = Zeroizing::new(poly_add_mod(params, &product_b, &e1));
    let c0 = poly_add_mod(params, &noisy_b, &encoded_plaintext);
    let product_a = Zeroizing::new(poly_mul_mod(params, &public_key.a, &u));
    let c1 = poly_add_mod(params, &product_a, &e2);
    Ok(BfvCiphertext { c0, c1 })
}
/// Encrypt a plaintext polynomial with rounded BFV plaintext scaling.
///
/// The plaintext is encoded as `(q / t) * m` in `R_q`, and fresh error coefficients are sampled
/// from a small centered distribution. This is the encryption entry for the pending bounded-noise
/// BFV-RNS path.
///
/// # Errors
/// Returns [`BfvError`] when parameters, plaintext, key shapes, public-key material, rounded-noise
/// capacity, or deterministic seed material are invalid.
pub(crate) fn encrypt_bounded_noise_from_seed(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    plaintext: &[u64],
    seed: &[u8],
) -> Result<BfvCiphertext, BfvError> {
    validate_plaintext(params, plaintext)?;
    validate_deterministic_seed("bounded-noise BFV encryption seed", seed)?;
    validate_bfv_bounded_noise_encryption_capacity(params)?;
    validate_public_key(params, public_key)?;
    validate_public_key_not_all_zero(public_key)?;
    let encoded_plaintext = Zeroizing::new(encode_rounded_plaintext(params, plaintext)?);
    let mut rng = derive_rng(BFV_BOUNDED_NOISE_ENCRYPT_SEED_DERIVATION_DOMAIN, seed);
    let u = Zeroizing::new(sample_nonzero_small_poly(params, &mut rng));
    let e1 = Zeroizing::new(sample_nonzero_bounded_noise_poly(params, &mut rng));
    let e2 = Zeroizing::new(sample_nonzero_bounded_noise_poly(params, &mut rng));
    let product_b = Zeroizing::new(poly_mul_mod(params, &public_key.b, &u));
    let noisy_b = Zeroizing::new(poly_add_mod(params, &product_b, &e1));
    let c0 = poly_add_mod(params, &noisy_b, &encoded_plaintext);
    let product_a = Zeroizing::new(poly_mul_mod(params, &public_key.a, &u));
    let c1 = poly_add_mod(params, &product_a, &e2);
    Ok(BfvCiphertext { c0, c1 })
}
/// Derive deterministic key-switching material for a BFV Galois automorphism.
///
/// The key switches ciphertexts encrypted under `sigma_k(s)` back to the original secret key `s`,
/// where `sigma_k` maps `x -> x^k` in `Z_q[x] / (x^n + 1)`. This is the deterministic baseline
/// primitive needed before packed slot rotations can be wired through public Galois keys.
///
/// # Errors
/// Returns [`BfvError`] when parameters, secret-key shape, or automorphism power are invalid, or
/// when the deterministic seed is empty or oversized.
#[cfg(any(test, feature = "bfv-test-fixtures"))]
pub(crate) fn galois_key_from_seed(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    automorphism_power: u32,
    seed: &[u8],
) -> Result<BfvGaloisKey, BfvError> {
    params.validate()?;
    validate_galois_automorphism_power(params, automorphism_power)?;
    validate_deterministic_seed("BFV Galois key seed", seed)?;
    validate_secret_key(params, secret_key)?;
    let target_secret = apply_galois_automorphism_poly(params, &secret_key.s, automorphism_power)?;
    let power_bytes = automorphism_power.to_le_bytes();
    let material = Zeroizing::new(<[u8; Hash::LENGTH]>::from(Hash::new_from_chunks(&[
        GALOIS_KEYGEN_DOMAIN,
        power_bytes.as_slice(),
        seed,
    ])));
    let mut rng = ChaCha20Rng::from_seed(*material);
    let entries = key_switch_entries_from_rng(params, &secret_key.s, &target_secret, &mut rng)?;
    let key = BfvGaloisKey {
        automorphism_power,
        entries,
    };
    validate_galois_key(params, &key)?;
    validate_key_switch_entry_residuals(
        params,
        &secret_key.s,
        &target_secret,
        &key.entries,
        "generated Galois key",
    )?;
    Ok(key)
}
