    let automorphed_c1 =
        apply_galois_automorphism_poly(params, &ciphertext.c1, galois_key.automorphism_power)?;
    key_switch_from_transformed_secret(
        params,
        &galois_key.entries,
        &automorphed_c0,
        &automorphed_c1,
    )
