fn packed_left_rotation_galois_schedule(
    params: &BfvParameters,
    rotation_steps: u32,
) -> Result<Vec<(u32, Vec<u64>)>, BfvError> {
    let normalized_steps = normalize_packed_rotation_steps(params, rotation_steps)?;
    let degree = params.degree();
    let mut covered = vec![false; degree];
    let mut schedule = Vec::new();
    for automorphism_power in canonical_galois_automorphism_powers(params)? {
        let permutation = packed_galois_slot_permutation(params, automorphism_power)?;
        let mut mask_slots = vec![0_u64; degree];
        let mut has_contribution = false;
        for (output_slot, input_slot) in permutation.into_iter().enumerate() {
            let target_slot = (output_slot + normalized_steps) % degree;
            if input_slot == target_slot {
                mask_slots[output_slot] = 1;
                covered[output_slot] = true;
                has_contribution = true;
            }
        }
        if has_contribution {
            schedule.push((automorphism_power, mask_slots));
        }
    }
    invalid_if!(
        covered.iter().any(|covered| !covered),
        "packed RotateLeft Galois schedule does not cover every output slot"
    );
    Ok(schedule)
}
fn normalize_packed_rotation_steps(
    params: &BfvParameters,
    rotation_steps: u32,
) -> Result<usize, BfvError> {
    packed_plaintext_root(params)?;
    invalid_if!(
        rotation_steps == 0,
        "packed RotateLeft requires non-zero rotation_steps"
    );
    let degree = params.degree();
    let degree =
        u64::try_from(degree).map_err(|_| invalid!("BFV packed-slot count exceeds u64"))?;
    let normalized_steps = u64::from(rotation_steps) % degree;
    invalid_if!(
        normalized_steps == 0,
        "packed RotateLeft by a full slot cycle is not represented by a Galois key"
    );
    usize::try_from(normalized_steps)
        .map_err(|_| invalid!("packed RotateLeft step normalization exceeds platform usize"))
}
fn canonical_galois_automorphism_powers(params: &BfvParameters) -> Result<Vec<u32>, BfvError> {
    packed_plaintext_root(params)?;
    fhe_automorphism::unit_powers(params.degree()).map_err(|error| match error {
        AutomorphismError::PowerExceedsU32 => {
            invalid!("BFV packed-slot Galois power exceeds u32")
        }
        _ => invalid!("BFV packed-slot cyclotomic order exceeds deterministic bounds"),
    })
}
/// Derive a deterministic one-round public bootstrap refresh key from a BFV public key.
///
/// The resulting key contains an encryption of zero. Adding it to any ciphertext under the same
/// parameters preserves the plaintext while changing the ciphertext bytes. This is the
/// deterministic in-repo refresh primitive used by Soracloud refresh-only Bootstrap jobs; it keeps
/// evaluators secret-key free. It is intentionally scoped to `RefreshOnlyV1`; production
/// full-bootstrap jobs must use governed artifact-aware APIs and, for public release paths,
/// release-audit context.
///
/// # Errors
/// Returns [`BfvError`] when parameter, public-key, or public transcript seed validation fails.
#[cfg(any(test, feature = "bfv-test-fixtures"))]
pub(crate) fn bootstrap_key_from_seed(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    key_id: impl Into<String>,
    seed: &[u8],
) -> Result<BfvBootstrapKey, BfvError> {
    bootstrap_key_with_max_refresh_rounds_from_seed(
        params,
        public_key,
        key_id,
        BFV_BOOTSTRAP_KEY_DEFAULT_MAX_REFRESH_ROUNDS,
        seed,
    )
}
/// Derive a deterministic bounded public bootstrap refresh key from a BFV public key.
///
/// The returned key contains one domain-separated encrypted-zero refresh ciphertext per authorized
/// round. `zero_refresh` must match `round_refreshes[0]` for the canonical V1 descriptor shape;
/// evaluators must consume `round_refreshes` by index for multi-round refreshes.
///
/// # Errors
/// Returns [`BfvError`] when parameter, public-key, key id, refresh-round, or public transcript
/// seed bounds are invalid.
pub(crate) fn bootstrap_key_with_max_refresh_rounds_from_seed(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    key_id: impl Into<String>,
    max_refresh_rounds: u16,
    seed: &[u8],
) -> Result<BfvBootstrapKey, BfvError> {
    let key_id = key_id.into();
    validate_bootstrap_key_metadata(&key_id, max_refresh_rounds)?;
    validate_refresh_transcript_seed("bootstrap refresh transcript seed", seed)?;
    validate_bfv_seeded_bootstrap_refresh_round_capacity(
        params,
        max_refresh_rounds,
        "BFV bootstrap key",
    )?;
    validate_public_key(params, public_key)?;
    validate_public_key_not_all_zero(public_key)?;
    let round_refreshes = (0..max_refresh_rounds)
        .map(|round_index| {
            let round_seed = bootstrap_refresh_round_seed(
                BFV_BOOTSTRAP_REFRESH_ROUND_SEED_DERIVATION_DOMAIN,
                &key_id,
                max_refresh_rounds,
                seed,
                round_index,
            );
            encrypt_from_seed(params, public_key, &[0], &round_seed)
        })
        .collect::<Result<Vec<_>, _>>()?;
    let Some(zero_refresh) = round_refreshes.first().cloned() else {
        return Err(invalid!(
            "bootstrap refresh rounds must be greater than zero"
        ));
    };
    let bootstrap_key = BfvBootstrapKey {
        mode: BfvBootstrapKeyMode::RefreshOnlyV1,
        key_id,
        max_refresh_rounds,
        public_key_digest: Some(bfv_public_key_digest(params, public_key)?),
        zero_refresh,
        round_refreshes,
        full_bootstrap_material: None,
    };
    validate_bootstrap_key(params, &bootstrap_key)?;
    Ok(bootstrap_key)
}
/// Derive a deterministic one-round bounded-noise bootstrap refresh key.
///
/// The refresh ciphertext is a rounded BFV encryption of zero generated with the bounded-noise
/// public-key path. This is still an encrypted-zero refresh, not full BFV bootstrapping, but it
/// moves bootstrap refresh material onto the same bounded-noise semantics as the rounded BFV-RNS
/// migration path.
///
/// # Errors
/// Returns [`BfvError`] when parameter, public-key, or public transcript seed validation fails.
#[cfg(any(test, feature = "bfv-test-fixtures"))]
pub(crate) fn bootstrap_key_bounded_noise_from_seed(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    key_id: impl Into<String>,
    seed: &[u8],
) -> Result<BfvBootstrapKey, BfvError> {
    bootstrap_key_bounded_noise_with_max_refresh_rounds_from_seed(
        params,
        public_key,
        key_id,
        BFV_BOOTSTRAP_KEY_DEFAULT_MAX_REFRESH_ROUNDS,
        seed,
    )
}
/// Derive a deterministic bounded-noise public bootstrap refresh key.
