/// Validate a raw full-bootstrap sample extracted from one BFV ciphertext coefficient.
///
/// # Errors
/// Returns [`BfvError`] when the sample coefficient index, constant term, or secret-coefficient
/// vector is outside the BFV parameter set.
pub(crate) fn validate_bfv_full_bootstrap_raw_extracted_sample_v1(
    params: &BfvParameters,
    sample: &BfvFullBootstrapRawExtractedSampleV1,
) -> Result<(), BfvError> {
    params.validate()?;
    let degree_u16 = u16::try_from(params.degree())
        .map_err(|_| invalid!("BFV full-bootstrap raw sample degree exceeds u16 metadata"))?;
    invalid_if!(
        sample.source_coefficient_index >= degree_u16,
        "BFV full-bootstrap raw sample source_coefficient_index {} must be less than polynomial_degree {}",
        sample.source_coefficient_index,
        params.polynomial_degree
    );
    if sample.constant_term >= params.ciphertext_modulus {
        return Err(BfvError::ShapeMismatch(format!(
            "BFV full-bootstrap raw sample constant_term is outside ciphertext modulus {}",
            params.ciphertext_modulus
        )));
    }
    validate_poly(
        params,
        &sample.secret_coefficients,
        "BFV full-bootstrap raw sample secret_coefficients",
    )?;
    invalid_if!(
        sample.constant_term == 0
            && sample
                .secret_coefficients
                .iter()
                .all(|&coefficient| coefficient == 0),
        "BFV full-bootstrap raw extracted sample must not be all zero"
    );
    Ok(())
}
/// Repack a raw extracted sample as a coefficient-zero BFV ciphertext.
///
/// The returned ciphertext decrypts at coefficient zero to the same scaled value as `sample`. Other
/// coefficients are still public linear artifacts of the raw sample coefficients and are not a
/// governed final full-bootstrap output. This helper is therefore an executable diagnostic bridge
/// before the real sample key-switch/repacking stage.
///
/// # Errors
/// Returns [`BfvError`] when the raw sample is malformed.
pub(crate) fn repack_bfv_full_bootstrap_raw_sample_as_coefficient_zero_ciphertext_v1(
    params: &BfvParameters,
    sample: &BfvFullBootstrapRawExtractedSampleV1,
) -> Result<BfvCiphertext, BfvError> {
    validate_bfv_full_bootstrap_raw_extracted_sample_v1(params, sample)?;
    let degree = params.degree();
    let mut c0 = vec![0_u64; degree];
    c0[0] = sample.constant_term;
    let mut c1 = vec![0_u64; degree];
    c1[0] = sample.secret_coefficients[0];
    for secret_index in 1..degree {
        c1[degree - secret_index] = sub_mod_u64(
            0,
            sample.secret_coefficients[secret_index],
            params.ciphertext_modulus,
        );
    }
    let ciphertext = BfvCiphertext { c0, c1 };
    validate_ciphertext(params, &ciphertext)?;
    Ok(ciphertext)
}
/// Repack a bounded-noise raw extracted sample as a coefficient-zero ciphertext.
///
/// This is the rounded BFV counterpart to
/// [`repack_bfv_full_bootstrap_raw_sample_as_coefficient_zero_ciphertext_v1`]. It preserves the
/// selected coefficient for diagnostics only; it is not the final full-bootstrap output ciphertext.
///
/// # Errors
/// Returns [`BfvError`] when rounded BFV capacity is too narrow or the raw sample is malformed.
pub(crate) fn repack_bfv_full_bootstrap_raw_sample_as_bounded_noise_coefficient_zero_ciphertext_v1(
    params: &BfvParameters,
    sample: &BfvFullBootstrapRawExtractedSampleV1,
) -> Result<BfvCiphertext, BfvError> {
    validate_bfv_full_bootstrap_raw_extracted_sample_v1(params, sample)?;
    validate_bfv_bounded_noise_encryption_capacity(params)?;
    repack_bfv_full_bootstrap_raw_sample_as_coefficient_zero_ciphertext_v1(params, sample)
}
