fn validate_bfv_full_bootstrap_proof_public_input_schema_proof_key_commitment_domains_v1(
    schema: &BfvFullBootstrapProofPublicInputSchemaV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_canonical_bytes_label(
        "BFV full-bootstrap proof public-input schema proof-key material commitment domain",
        &schema.proof_key_material_commitment_domain,
        BFV_FULL_BOOTSTRAP_PROOF_KEY_MATERIAL_COMMITMENT_DOMAIN,
    )?;
    validate_bfv_full_bootstrap_canonical_bytes_label(
        "BFV full-bootstrap proof public-input schema proof-key pair commitment domain",
        &schema.proof_key_pair_commitment_domain,
        BFV_FULL_BOOTSTRAP_PROOF_KEY_PAIR_COMMITMENT_DOMAIN,
    )?;
    invalid_if!(
        !schema.separates_proof_key_material_and_pair_commitments,
        "BFV full-bootstrap proof public-input schema must separate proof-key material and pair commitment domains"
    );
    invalid_if!(
        schema.proof_key_material_commitment_domain == schema.proof_key_pair_commitment_domain,
        "BFV full-bootstrap proof public-input schema proof-key material and pair commitment domains must be distinct"
    );
    Ok(())
}
fn validate_bfv_full_bootstrap_proof_public_input_schema_release_prover_domain_separation_v1(
    schema: &BfvFullBootstrapProofPublicInputSchemaV1,
) -> Result<(), BfvError> {
    invalid_if!(
        !schema.separates_release_prover_material_domains,
        "BFV full-bootstrap proof public-input schema must separate release-prover material digest domains"
    );
    let domains = [
        (
            "proof input material",
            schema.proof_input_material_digest_domain.as_slice(),
        ),
        (
            "prover input material",
            schema.prover_input_material_digest_domain.as_slice(),
        ),
        (
            "AIR evaluation material",
            schema.air_evaluation_material_digest_domain.as_slice(),
        ),
        (
            "public opening material",
            schema.public_opening_material_digest_domain.as_slice(),
        ),
        (
            "arithmetic trace material",
            schema.arithmetic_trace_material_digest_domain.as_slice(),
        ),
        (
            "arithmetic AIR constraint-system",
            schema
                .arithmetic_air_constraint_system_digest_domain
                .as_slice(),
        ),
    ];
    for (left_index, (left_label, left_domain)) in domains.iter().enumerate() {
        for (right_label, right_domain) in domains.iter().skip(left_index + 1) {
            invalid_if!(
                left_domain == right_domain,
                "BFV full-bootstrap proof public-input schema release-prover material digest domains for {left_label} and {right_label} must be distinct"
            );
        }
    }
    Ok(())
}
fn validate_bfv_full_bootstrap_proof_public_input_schema_release_prover_binding_flags_v1(
    schema: &BfvFullBootstrapProofPublicInputSchemaV1,
) -> Result<(), BfvError> {
    for (label, is_bound) in [
        (
            "release prover arithmetic AIR constraint-system digest",
            schema.binds_release_prover_arithmetic_air_constraint_system_digest,
        ),
        (
            "release prover arithmetic AIR artifact digest",
            schema.binds_release_prover_arithmetic_air_constraint_system_artifact_digest,
        ),
        (
            "release prover arithmetic AIR evaluation material digest",
            schema.binds_release_prover_arithmetic_air_evaluation_material_digest,
        ),
        (
            "arithmetic AIR evaluation trace material digest",
            schema.binds_arithmetic_air_evaluation_trace_material_digest,
        ),
        (
            "zero arithmetic AIR composition values",
            schema.requires_zero_arithmetic_air_composition_values,
        ),
        (
            "arithmetic trace material digest",
            schema.binds_arithmetic_trace_material_digest,
        ),
        (
            "transcript public opening material",
            schema.validates_transcript_public_opening_material,
        ),
        (
            "verifier-owned trace material digest",
            schema.requires_verifier_owned_trace_material_digest,
        ),
        (
            "trace/proof-input consistency",
            schema.binds_trace_proof_input_consistency,
        ),
        (
            "generated prover/verifier proof-key pair",
            schema.binds_generated_proof_key_pair,
        ),
        (
            "release prover verifier key",
            schema.binds_release_prover_verifier_key,
        ),
        (
            "artifact-bound release prover input validation",
            schema.validates_artifact_bound_prover_input,
        ),
        (
            "stale Galois-key set replay rejection",
            schema.rejects_stale_galois_key_set_replay,
        ),
        (
            "stale proof-key artifact replay rejection",
            schema.rejects_stale_proof_key_artifacts,
        ),
    ] {
        invalid_if!(
            !is_bound,
            "BFV full-bootstrap proof public-input schema must bind {label}"
        );
    }
    Ok(())
}
fn validate_bfv_full_bootstrap_proof_public_input_schema_witness_bindings_v1(
    schema: &BfvFullBootstrapProofPublicInputSchemaV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_canonical_bytes_label(
        "BFV full-bootstrap proof public-input schema witness digest domain",
        &schema.witness_digest_domain,
        BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_DOMAIN,
    )?;
    invalid_guards! {
        schema.witness_digest_material_version
        != BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_MATERIAL_VERSION_V1 => (
            "BFV full-bootstrap proof public-input schema witness material version {} does not match canonical version {}",
            schema.witness_digest_material_version,
            BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_MATERIAL_VERSION_V1),
        schema.witness_digest_material_field_count
        != BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_MATERIAL_FIELD_COUNT_V1 => (
            "BFV full-bootstrap proof public-input schema witness material field count {} does not match canonical count {}",
            schema.witness_digest_material_field_count,
            BFV_FULL_BOOTSTRAP_EXECUTION_WITNESS_DIGEST_MATERIAL_FIELD_COUNT_V1),
        schema.witness_trace_field_count
        != BFV_FULL_BOOTSTRAP_EXECUTION_PREFIX_TRACE_FIELD_COUNT_V1 => (
            "BFV full-bootstrap proof public-input schema witness trace field count {} does not match canonical count {}",
            schema.witness_trace_field_count,
            BFV_FULL_BOOTSTRAP_EXECUTION_PREFIX_TRACE_FIELD_COUNT_V1),
        schema.witness_trace_bounds_field_count
        != BFV_FULL_BOOTSTRAP_EXECUTION_PREFIX_TRACE_BOUNDS_FIELD_COUNT_V1 => (
            "BFV full-bootstrap proof public-input schema witness trace bounds field count {} does not match canonical count {}",
            schema.witness_trace_bounds_field_count,
            BFV_FULL_BOOTSTRAP_EXECUTION_PREFIX_TRACE_BOUNDS_FIELD_COUNT_V1),
    }
    for (label, is_bound) in [
        (
            "execution witness trace",
            schema.binds_execution_witness_trace,
        ),
        (
            "execution witness trace bounds",
            schema.binds_execution_witness_trace_bounds,
        ),
    ] {
        invalid_if!(
            !is_bound,
            "BFV full-bootstrap proof public-input schema must bind {label}"
        );
    }
    Ok(())
}
fn validate_bfv_full_bootstrap_proof_public_input_schema_capabilities_v1(
    schema: &BfvFullBootstrapProofPublicInputSchemaV1,
) -> Result<(), BfvError> {
    invalid_if!(
        !schema.supports_exact_residual_multiple,
        "BFV full-bootstrap proof public-input schema must support exact residual-multiple claims"
    );
    invalid_if!(
        !schema.supports_bounded_noise,
        "BFV full-bootstrap proof public-input schema must support bounded-noise claims"
    );
    Ok(())
}
/// Encode a typed proof public-input schema artifact.
///
/// The returned bytes are a governed full-bootstrap artifact envelope whose inner payload is
/// [`BfvFullBootstrapProofPublicInputSchemaV1`].
///
/// # Errors
/// Returns [`BfvError`] when schema validation or canonical encoding fails.
pub fn encode_bfv_full_bootstrap_proof_public_input_schema_artifact_v1(
    params: &BfvParameters,
    max_bootstrap_depth: u16,
    schema: &BfvFullBootstrapProofPublicInputSchemaV1,
) -> Result<Vec<u8>, BfvError> {
    validate_bfv_full_bootstrap_proof_public_input_schema_v1(schema)?;
    let payload = norito::encode_canonical(schema).map_err(|err| {
        invalid!("BFV full-bootstrap proof public-input schema encoding failed: {err}")
    })?;
    encode_bfv_full_bootstrap_circuit_artifact_payload_v1(
        params,
        max_bootstrap_depth,
        BfvFullBootstrapCircuitArtifactRoleV1::ProofPublicInputSchema,
        &payload,
    )
}
/// Decode and validate a governed proof public-input schema artifact.
///
/// # Errors
/// Returns [`BfvError`] when the artifact envelope does not match the governed material or the
/// typed public-input schema payload is malformed.
pub fn decode_bfv_full_bootstrap_proof_public_input_schema_artifact_v1(
    params: &BfvParameters,
    material: &BfvFullBootstrapCircuitMaterialV1,
    bytes: &[u8],
) -> Result<BfvFullBootstrapProofPublicInputSchemaV1, BfvError> {
    let role = BfvFullBootstrapCircuitArtifactRoleV1::ProofPublicInputSchema;
    let label = full_bootstrap_artifact_label_for_role(role);
    let expected_digest = full_bootstrap_material_digest_for_role(material, role);
    let artifact = decode_full_bootstrap_artifact_payload(
        params,
        material,
        label,
        role,
        bytes,
        expected_digest,
    )?;
    let schema =
        norito::decode_canonical::<BfvFullBootstrapProofPublicInputSchemaV1>(&artifact.payload)
            .map_err(|err| {
                invalid!(
                    "{label} payload must use canonical v1 bytes containing a Norito-encoded BFV full-bootstrap proof public-input schema: {err}"
                )
            })?;
    validate_bfv_full_bootstrap_proof_public_input_schema_v1(&schema)?;
    Ok(schema)
}
/// Encode typed arithmetic AIR constraint-system material as a governed artifact.
