/// Decode and validate a governed arithmetic AIR constraint-system artifact.
///
/// # Errors
/// Returns [`BfvError`] when the artifact envelope does not match governed material or the typed
/// AIR material payload is malformed.
pub fn decode_bfv_full_bootstrap_arithmetic_air_constraint_system_artifact_v1(
    params: &BfvParameters,
    material: &BfvFullBootstrapCircuitMaterialV1,
    bytes: &[u8],
) -> Result<BfvFullBootstrapArithmeticAirConstraintSystemMaterialV1, BfvError> {
    let role = BfvFullBootstrapCircuitArtifactRoleV1::ArithmeticAirConstraintSystem;
    let label = full_bootstrap_artifact_label_for_role(role);
    let expected_digest = full_bootstrap_material_digest_for_role(material, role);
    let artifact = decode_full_bootstrap_artifact_payload(
        params,
        material,
        label,
        role,
        bytes,
        expected_digest,
    )?;
    let air_material = norito::decode_canonical::<
        BfvFullBootstrapArithmeticAirConstraintSystemMaterialV1,
    >(&artifact.payload)
    .map_err(|err| {
        invalid!(
            "{label} payload must use canonical v1 bytes containing a Norito-encoded BFV full-bootstrap arithmetic AIR constraint-system material: {err}"
        )
    })?;
    validate_bfv_full_bootstrap_arithmetic_air_constraint_system_material_v1(&air_material)?;
    let expected_content_digest =
        bfv_full_bootstrap_arithmetic_air_constraint_system_digest_from_material_v1(&air_material)?;
    validate_bfv_full_bootstrap_arithmetic_air_constraint_system_digest_v1(
        "BFV full-bootstrap arithmetic AIR constraint-system artifact payload digest",
        &expected_content_digest,
    )?;
    Ok(air_material)
}
/// Encode canonical STARK/FRI verifier-key payload bytes for BFV full-bootstrap proofs.
///
/// The returned bytes use the same Norito field layout as the native STARK/FRI verifier payload
/// consumed by Core, but the helper lives in `iroha_crypto` so SDK and data-model tests can build
/// release-profile artifacts without relying on Core internals.
///
/// # Errors
/// Returns [`BfvError`] when the circuit id is not canonical or encoding fails.
pub fn encode_bfv_full_bootstrap_native_stark_fri_verifier_key_payload_v1(
    native_payload_circuit_id: &str,
) -> Result<Vec<u8>, BfvError> {
    validate_bfv_full_bootstrap_native_payload_circuit_id(
        "BFV full-bootstrap native verifier-key payload circuit id",
        native_payload_circuit_id,
    )?;
    let generated_circuit_body =
        bfv_full_bootstrap_native_generated_circuit_body_v1(native_payload_circuit_id)?;
    let generated_circuit_body_digest =
        bfv_native_stark_generated_circuit_body_digest_v1(&generated_circuit_body)?;
    let centered_scale_round_source_chain_digest =
        canonical_bfv_full_bootstrap_centered_scale_round_source_chain_digest_v1()?;
    let payload = BfvFullBootstrapNativeStarkFriVerifyingKeyPayloadV1 {
        version: BFV_FULL_BOOTSTRAP_NATIVE_PROOF_KEY_MATERIAL_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_NATIVE_VERIFIER_PAYLOAD_FIELD_COUNT_V1,
        circuit_id: native_payload_circuit_id.to_owned(),
        backend: BFV_FULL_BOOTSTRAP_PROOF_BACKEND_V1.to_owned(),
        key_format: BFV_FULL_BOOTSTRAP_PROOF_KEY_FORMAT_V1.to_owned(),
        proof_system: BFV_FULL_BOOTSTRAP_NATIVE_STARK_FRI_PROOF_SYSTEM_V1.to_owned(),
        field: BFV_FULL_BOOTSTRAP_NATIVE_STARK_FIELD_V1.to_owned(),
        n_log2: BFV_FULL_BOOTSTRAP_NATIVE_STARK_FRI_N_LOG2_V1,
        blowup_log2: BFV_FULL_BOOTSTRAP_NATIVE_STARK_FRI_BLOWUP_LOG2_V1,
        fold_arity: BFV_FULL_BOOTSTRAP_NATIVE_STARK_FRI_FOLD_ARITY_V1,
        queries: BFV_FULL_BOOTSTRAP_NATIVE_STARK_FRI_QUERIES_V1,
        merkle_arity: BFV_FULL_BOOTSTRAP_NATIVE_STARK_FRI_MERKLE_ARITY_V1,
        arithmetic_trace_profile_digest:
            canonical_bfv_full_bootstrap_arithmetic_trace_profile_digest_v1(),
        arithmetic_air_constraint_system_digest:
            canonical_bfv_full_bootstrap_arithmetic_air_constraint_system_digest_v1(),
        centered_scale_round_source_chain_digest,
        generated_circuit_body_digest,
        generated_circuit_body,
    };
    norito::encode_canonical(&payload).map_err(|err| {
        invalid!("BFV full-bootstrap native verifier-key payload encoding failed: {err}")
    })
}
/// Encode canonical transparent-prover native material for BFV full-bootstrap proofs.
