/// Validate a BFV full-bootstrap release audit manifest.
///
/// # Errors
/// Returns [`BfvError`] when the manifest layout is stale, the scope/verdict is not
/// release-authorizing, reviewer metadata is malformed, or required commitments are empty or
/// reused.
#[allow(clippy::too_many_lines)]
pub fn validate_bfv_full_bootstrap_release_audit_manifest_v1(
    manifest: &BfvFullBootstrapReleaseAuditManifestV1,
) -> Result<(), BfvError> {
    invalid_if!(
        manifest.version != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_MANIFEST_VERSION_V1,
        "BFV full-bootstrap release audit manifest version {} does not match canonical version {}",
        manifest.version,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_MANIFEST_VERSION_V1
    );
    invalid_if!(
        manifest.field_count != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_MANIFEST_FIELD_COUNT_V1,
        "BFV full-bootstrap release audit manifest field count {} does not match canonical count {}",
        manifest.field_count,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_MANIFEST_FIELD_COUNT_V1
    );
    validate_bfv_full_bootstrap_canonical_circuit_id(
        "BFV full-bootstrap release audit manifest circuit id",
        &manifest.circuit_id,
    )?;
    validate_bfv_full_bootstrap_canonical_text_label(
        "BFV full-bootstrap release audit manifest scope",
        &manifest.audit_scope,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_SCOPE_V1,
    )?;
    invalid_guards! {
        manifest.verdict != BfvFullBootstrapReleaseAuditVerdictV1::ApprovedForRelease
        => ("BFV full-bootstrap release audit manifest verdict must be approved for release"),
        manifest.package_version != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PACKAGE_VERSION_V1 => (
            "BFV full-bootstrap release audit manifest package version {} does not match canonical version {}",
            manifest.package_version,
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PACKAGE_VERSION_V1),
        manifest.package_field_count != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PACKAGE_FIELD_COUNT_V1 => (
            "BFV full-bootstrap release audit manifest package field count {} does not match canonical count {}",
            manifest.package_field_count,
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PACKAGE_FIELD_COUNT_V1),
    }
    let signed_commitments = [
        ("record digest", &manifest.record_digest),
        (
            "release evidence digest",
            &manifest.release_audit_evidence_digest,
        ),
        (
            "centered scale-round source-chain digest",
            &manifest.centered_scale_round_source_chain_digest,
        ),
        ("artifact bundle digest", &manifest.artifact_bundle_digest),
        (
            "evaluator artifact set digest",
            &manifest.evaluator_artifact_set_digest,
        ),
        (
            "proof-key pair commitment",
            &manifest.proof_key_pair_commitment,
        ),
        ("prover-key digest", &manifest.prover_key_digest),
        ("verifier-key digest", &manifest.verifier_key_digest),
        (
            "prover native payload digest",
            &manifest.prover_native_payload_digest,
        ),
        (
            "verifier native payload digest",
            &manifest.verifier_native_payload_digest,
        ),
        (
            "native circuit fingerprint",
            &manifest.native_circuit_fingerprint,
        ),
        (
            "generated circuit body digest",
            &manifest.generated_circuit_body_digest,
        ),
        ("audit report digest", &manifest.audit_report_digest),
        (
            "evidence archive digest",
            &manifest.audit_evidence_archive_digest,
        ),
    ];
    validate_no_full_bootstrap_placeholder_release_audit_signed_commitments(
        "manifest",
        &signed_commitments,
    )?;
    validate_distinct_bfv_full_bootstrap_release_audit_signed_commitments(
        "manifest",
        &signed_commitments,
    )?;
    validate_bfv_full_bootstrap_release_audit_signed_generated_body_embedded_digest_aliases_v1(
        "manifest",
        &manifest.circuit_id,
        &[
            (
                "prover native payload digest",
                &manifest.prover_native_payload_digest,
            ),
            (
                "verifier native payload digest",
                &manifest.verifier_native_payload_digest,
            ),
            (
                "generated circuit body digest",
                &manifest.generated_circuit_body_digest,
            ),
        ],
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit manifest record digest",
        &manifest.record_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit manifest evidence digest",
        &manifest.release_audit_evidence_digest,
    )?;
    validate_bfv_full_bootstrap_centered_scale_round_source_chain_digest_v1(
        "BFV full-bootstrap release audit manifest centered scale-round source-chain digest",
        &manifest.centered_scale_round_source_chain_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit manifest artifact bundle digest",
        &manifest.artifact_bundle_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit manifest evaluator artifact set digest",
        &manifest.evaluator_artifact_set_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit manifest proof-key pair commitment",
        &manifest.proof_key_pair_commitment,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit manifest prover-key digest",
        &manifest.prover_key_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit manifest verifier-key digest",
        &manifest.verifier_key_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_native_payload_digest_v1(
        "BFV full-bootstrap release audit manifest prover native payload digest",
        &manifest.circuit_id,
        BfvFullBootstrapCircuitArtifactRoleV1::ProverKey,
        &manifest.prover_native_payload_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_native_payload_digest_v1(
        "BFV full-bootstrap release audit manifest verifier native payload digest",
        &manifest.circuit_id,
        BfvFullBootstrapCircuitArtifactRoleV1::VerifierKey,
        &manifest.verifier_native_payload_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_native_circuit_fingerprint_v1(
        "BFV full-bootstrap release audit manifest native circuit fingerprint",
        &manifest.circuit_id,
        &manifest.native_circuit_fingerprint,
    )?;
    validate_bfv_full_bootstrap_release_audit_generated_circuit_body_digest_v1(
        "BFV full-bootstrap release audit manifest generated circuit body digest",
        &manifest.circuit_id,
        &manifest.generated_circuit_body_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_external_artifact_digest_pair_v1(
        "manifest",
        &manifest.audit_report_digest,
        &manifest.audit_evidence_archive_digest,
    )?;
    invalid_if!(
        manifest.audit_report_digest == manifest.release_audit_evidence_digest
            || manifest.audit_evidence_archive_digest == manifest.release_audit_evidence_digest,
        "BFV full-bootstrap release audit manifest external audit digests must be distinct from the release evidence digest"
    );
    validate_bfv_full_bootstrap_release_audit_reviewer_id(&manifest.reviewer_id)?;
    validate_bfv_full_bootstrap_release_audit_reviewer_public_key(
        "BFV full-bootstrap release audit manifest reviewer public key",
        &manifest.reviewer_public_key,
    )?;
    Ok(())
}
/// Validate a release audit manifest against a trusted reviewer key.
///
/// # Errors
/// Returns [`BfvError`] when the caller's trusted reviewer inputs are malformed, the manifest is
/// malformed, or its reviewer id/key do not match the caller's trusted reviewer inputs.
pub fn validate_bfv_full_bootstrap_release_audit_manifest_trusted_reviewer_v1(
    manifest: &BfvFullBootstrapReleaseAuditManifestV1,
    reviewer_id: &str,
    reviewer_public_key: &PublicKey,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_release_audit_trusted_reviewer_inputs_v1(
        reviewer_id,
        reviewer_public_key,
    )?;
    validate_bfv_full_bootstrap_release_audit_manifest_v1(manifest)?;
    invalid_if!(
        manifest.reviewer_id.as_str() != reviewer_id,
        "BFV full-bootstrap release audit manifest reviewer id does not match trusted reviewer"
    );
    invalid_if!(
        &manifest.reviewer_public_key != reviewer_public_key,
        "BFV full-bootstrap release audit manifest reviewer public key does not match trusted reviewer"
    );
    Ok(())
}
/// Validate a release audit manifest against its signed audit record.
///
/// # Errors
/// Returns [`BfvError`] when the manifest is malformed, the record digest is stale, or any manifest
/// commitment differs from the signed record payload.
pub fn validate_bfv_full_bootstrap_release_audit_manifest_for_record_v1(
    manifest: &BfvFullBootstrapReleaseAuditManifestV1,
    record: &BfvFullBootstrapReleaseAuditRecordV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_release_audit_manifest_v1(manifest)?;
    validate_bfv_full_bootstrap_release_audit_record_v1(record)?;
    let expected_record_digest = bfv_full_bootstrap_release_audit_record_digest_v1(record)?;
    invalid_if!(
        manifest.record_digest != expected_record_digest,
        "BFV full-bootstrap release audit manifest record digest mismatch"
    );
    let payload = &record.signoff.payload;
    invalid_guards! {
        manifest.release_audit_evidence_digest != payload.release_audit_evidence_digest
        => ("BFV full-bootstrap release audit manifest evidence digest mismatch"),
        manifest.centered_scale_round_source_chain_digest
        != payload.centered_scale_round_source_chain_digest => (
            "BFV full-bootstrap release audit manifest centered scale-round source-chain digest mismatch"
        ),
        manifest.artifact_bundle_digest != payload.artifact_bundle_digest
        => ("BFV full-bootstrap release audit manifest artifact bundle digest mismatch"),
        manifest.evaluator_artifact_set_digest != payload.evaluator_artifact_set_digest
        => ("BFV full-bootstrap release audit manifest evaluator artifact set digest mismatch"),
        manifest.proof_key_pair_commitment != payload.proof_key_pair_commitment
        => ("BFV full-bootstrap release audit manifest proof-key pair commitment mismatch"),
        manifest.prover_key_digest != payload.prover_key_digest
        => ("BFV full-bootstrap release audit manifest prover-key digest mismatch"),
        manifest.verifier_key_digest != payload.verifier_key_digest
        => ("BFV full-bootstrap release audit manifest verifier-key digest mismatch"),
        manifest.prover_native_payload_digest != payload.prover_native_payload_digest
        => ("BFV full-bootstrap release audit manifest prover native payload digest mismatch"),
        manifest.verifier_native_payload_digest != payload.verifier_native_payload_digest
        => ("BFV full-bootstrap release audit manifest verifier native payload digest mismatch"),
        manifest.native_circuit_fingerprint != payload.native_circuit_fingerprint
        => ("BFV full-bootstrap release audit manifest native circuit fingerprint mismatch"),
    }
    let expected_generated_circuit_body_digest = bfv_native_stark_digest_binding_hash_v1(
        record.evidence.prover_key.generated_circuit_body_digest,
    );
    invalid_guards! {
        manifest.generated_circuit_body_digest != expected_generated_circuit_body_digest
        => ("BFV full-bootstrap release audit manifest generated circuit body digest mismatch"),
        manifest.audit_report_digest != payload.audit_report_digest
        => ("BFV full-bootstrap release audit manifest report digest mismatch"),
        manifest.audit_evidence_archive_digest != payload.audit_evidence_archive_digest
        => ("BFV full-bootstrap release audit manifest evidence archive digest mismatch"),
        manifest.reviewer_id.as_str() != payload.reviewer_id.as_str()
        => ("BFV full-bootstrap release audit manifest reviewer id mismatch"),
        manifest.reviewer_public_key != payload.reviewer_public_key
        => ("BFV full-bootstrap release audit manifest reviewer public key mismatch"),
    }
    Ok(())
}
/// Return the digest of a BFV full-bootstrap release audit manifest.
///
/// # Errors
/// Returns [`BfvError`] when manifest validation or canonical encoding fails.
pub fn bfv_full_bootstrap_release_audit_manifest_digest_v1(
    manifest: &BfvFullBootstrapReleaseAuditManifestV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_release_audit_manifest_v1(manifest)?;
    let bytes = norito::encode_canonical(manifest).map_err(|err| {
        invalid!("BFV full-bootstrap release audit manifest encoding failed: {err}")
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_MANIFEST_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}
