    let bytes = norito::encode_canonical(package).map_err(|err| {
        invalid!("BFV full-bootstrap release audit package encoding failed: {err}")
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PACKAGE_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
