/// Return the deterministic arithmetic witness digest for a full-bootstrap claim.
///
/// The digest is the domain-separated hash of the typed governed witness material. The
/// `execution_witness_digest` field already present in `claim` is intentionally ignored while
/// deriving the expected digest.
///
/// # Errors
/// Returns [`BfvError`] when governed witness material cannot be derived or canonical witness
/// encoding fails.
pub fn bfv_full_bootstrap_execution_witness_digest_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    claim: &BfvFullBootstrapExecutionProofClaimV1,
) -> Result<Hash, BfvError> {
    let digest_material = bfv_full_bootstrap_execution_witness_digest_material_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        claim,
    )?;
    bfv_full_bootstrap_execution_witness_digest_from_material_for_artifacts_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        &digest_material,
    )
}
/// Reconstruct the public execution proof claim from validated witness material.
///
/// # Errors
/// Returns [`BfvError`] when witness material validation or witness hashing fails.
pub fn bfv_full_bootstrap_execution_proof_claim_from_witness_material_v1(
    material: &BfvFullBootstrapExecutionWitnessDigestMaterialV1,
) -> Result<BfvFullBootstrapExecutionProofClaimV1, BfvError> {
    let execution_witness_digest =
        bfv_full_bootstrap_execution_witness_digest_from_material_v1(material)?;
    Ok(BfvFullBootstrapExecutionProofClaimV1 {
        slot_index: material.slot_index,
        input_ciphertext: material.input_ciphertext.clone(),
        output_ciphertext: material.output_ciphertext.clone(),
        bound_mode: material.bound_mode,
        input_bound: material.input_bound,
        output_bound: material.output_bound,
        galois_key_set_digest: material.galois_key_set_digest,
        execution_witness_digest,
    })
}
/// Derive the canonical execution proof statement hash from typed witness material.
///
/// This is the external prover companion to
/// [`bfv_full_bootstrap_execution_proof_statement_digest_with_witness_v1`]. It does not require the
/// original artifact bytes because the witness material has already bound and validated the
/// governed material and artifact-bundle digests used by the statement.
///
/// # Errors
/// Returns [`BfvError`] when the public key or witness material is malformed, or when canonical
/// statement encoding fails.
pub fn bfv_full_bootstrap_execution_proof_statement_digest_from_witness_material_v1(
    public_key: &BfvPublicKey,
    witness_material: &BfvFullBootstrapExecutionWitnessDigestMaterialV1,
) -> Result<Hash, BfvError> {
    let (statement_hash, _) =
        bfv_full_bootstrap_execution_proof_statement_and_witness_digest_from_witness_material_v1(
            public_key,
            witness_material,
        )?;
    Ok(statement_hash)
}
fn bfv_full_bootstrap_execution_proof_statement_and_witness_digest_from_witness_material_v1(
    public_key: &BfvPublicKey,
    witness_material: &BfvFullBootstrapExecutionWitnessDigestMaterialV1,
) -> Result<(Hash, Hash), BfvError> {
    validate_public_key(&witness_material.params, public_key)?;
    validate_bootstrap_key_public_key_digest(
        &witness_material.params,
        public_key,
        &witness_material.bootstrap_key,
    )?;
    let claim =
        bfv_full_bootstrap_execution_proof_claim_from_witness_material_v1(witness_material)?;
    let execution_witness_digest = claim.execution_witness_digest;
    let statement = BfvFullBootstrapExecutionProofStatementMaterial {
        version: BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_MATERIAL_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_MATERIAL_FIELD_COUNT_V1,
        params: witness_material.params,
        public_key: public_key.clone(),
        bootstrap_key: witness_material.bootstrap_key.clone(),
        full_bootstrap_material_digest: witness_material.full_bootstrap_material_digest,
        artifact_bundle_digest: witness_material.artifact_bundle_digest,
        claim,
    };
    let bytes = norito::encode_canonical(&statement).map_err(|err| {
        invalid!("full-bootstrap execution proof statement encoding failed: {err}")
    })?;
    let statement_hash = Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_DOMAIN,
        bytes.as_slice(),
    ]);
    Ok((statement_hash, execution_witness_digest))
}
/// Build typed proof input material for a dedicated BFV full-bootstrap prover.
///
/// # Errors
/// Returns [`BfvError`] when the public key, witness material, or derived statement hash fails
/// validation.
pub fn bfv_full_bootstrap_execution_proof_input_material_v1(
    public_key: &BfvPublicKey,
    witness_material: &BfvFullBootstrapExecutionWitnessDigestMaterialV1,
) -> Result<BfvFullBootstrapExecutionProofInputMaterialV1, BfvError> {
    let statement_hash =
        bfv_full_bootstrap_execution_proof_statement_digest_from_witness_material_v1(
            public_key,
            witness_material,
        )?;
    let material = BfvFullBootstrapExecutionProofInputMaterialV1 {
        version: BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_FIELD_COUNT_V1,
        public_key: public_key.clone(),
        witness_material: witness_material.clone(),
        statement_hash,
    };
    validate_bfv_full_bootstrap_execution_proof_input_material_v1(&material)?;
    Ok(material)
}
/// Validate typed proof input material for a dedicated BFV full-bootstrap prover.
///
/// # Errors
/// Returns [`BfvError`] when layout metadata is stale, the embedded witness material is invalid, or
/// the statement hash is not the canonical hash derived from the public key and witness material.
pub fn validate_bfv_full_bootstrap_execution_proof_input_material_v1(
    material: &BfvFullBootstrapExecutionProofInputMaterialV1,
) -> Result<(), BfvError> {
    invalid_guards! {
        material.version != BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_VERSION_V1 => (
            "BFV full-bootstrap execution proof input material version {} does not match canonical version {}",
            material.version,
            BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_VERSION_V1),
        material.field_count != BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_FIELD_COUNT_V1
        => (
            "BFV full-bootstrap execution proof input material field count {} does not match canonical count {}",
            material.field_count,
            BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_FIELD_COUNT_V1),
    }
    validate_bfv_full_bootstrap_execution_proof_input_digest_aliases_v1(material)?;
    let (expected_statement_hash, execution_witness_digest) =
        bfv_full_bootstrap_execution_proof_statement_and_witness_digest_from_witness_material_v1(
            &material.public_key,
            &material.witness_material,
        )?;
    validate_bfv_full_bootstrap_digest_material_hashes(
        "BFV full-bootstrap execution proof input material",
        &[
            ("execution witness digest", &execution_witness_digest),
            ("statement hash", &material.statement_hash),
        ],
    )?;
    validate_bfv_full_bootstrap_execution_proof_input_governed_material_digest_aliases_v1(
        material,
    )?;
    invalid_if!(
        material.statement_hash != expected_statement_hash,
        "BFV full-bootstrap execution proof input material statement hash mismatch"
    );
    Ok(())
}
fn validate_bfv_full_bootstrap_execution_proof_input_digest_aliases_v1(
    material: &BfvFullBootstrapExecutionProofInputMaterialV1,
) -> Result<(), BfvError> {
    let public_key_digest =
        bfv_public_key_digest(&material.witness_material.params, &material.public_key)?;
    validate_bfv_full_bootstrap_digest_material_hashes(
        "BFV full-bootstrap execution proof input material",
        &[
            ("public-key digest", &public_key_digest),
            (
                "witness full-bootstrap material digest",
                &material.witness_material.full_bootstrap_material_digest,
            ),
            (
                "witness artifact bundle digest",
                &material.witness_material.artifact_bundle_digest,
            ),
            (
                "witness Galois key set digest",
                &material.witness_material.galois_key_set_digest,
            ),
            ("statement hash", &material.statement_hash),
        ],
    )?;
    validate_bfv_full_bootstrap_execution_proof_input_ciphertext_digest_aliases_v1(material)
}
fn validate_bfv_full_bootstrap_execution_proof_input_ciphertext_digest_aliases_v1(
    material: &BfvFullBootstrapExecutionProofInputMaterialV1,
) -> Result<(), BfvError> {
    let input_ciphertext_digest = bfv_ciphertext_digest(
        &material.witness_material.params,
        &material.witness_material.input_ciphertext,
    )?;
    let output_ciphertext_digest = bfv_ciphertext_digest(
        &material.witness_material.params,
        &material.witness_material.output_ciphertext,
    )?;
    for (ciphertext_label, ciphertext_digest) in [
        ("input ciphertext digest", &input_ciphertext_digest),
        ("output ciphertext digest", &output_ciphertext_digest),
    ] {
        validate_bfv_full_bootstrap_digest_material_hashes(
            "BFV full-bootstrap execution proof input material",
            &[
                (ciphertext_label, ciphertext_digest),
                ("statement hash", &material.statement_hash),
            ],
        )?;
    }
    Ok(())
}
fn validate_bfv_full_bootstrap_execution_proof_input_governed_material_digest_aliases_v1(
    material: &BfvFullBootstrapExecutionProofInputMaterialV1,
) -> Result<(), BfvError> {
    let governed_material =
        full_bootstrap_material_from_key(&material.witness_material.bootstrap_key)?;
    validate_bfv_full_bootstrap_digest_material_hashes(
        "BFV full-bootstrap execution proof input material",
        &[
            (
                "proof public-input schema digest",
                &governed_material.proof_public_input_schema_digest,
            ),
            (
                "proof-key pair commitment",
                &governed_material.proof_key_pair_commitment,
            ),
            ("prover-key digest", &governed_material.prover_key_digest),
            (
                "prover-key material commitment",
                &governed_material.prover_key_material_commitment,
            ),
            (
                "verifier-key digest",
                &governed_material.verifier_key_digest,
            ),
            (
                "verifier-key material commitment",
                &governed_material.verifier_key_material_commitment,
            ),
            ("statement hash", &material.statement_hash),
        ],
    )
}
/// Validate execution proof input material against concrete governed artifacts.
///
/// This artifact-aware companion recomputes the embedded witness material from the supplied
/// `FullBootstrapV1` key, artifact bundle, and Galois keys before accepting the proof-input
/// package. Use it when externally held proof input material is available together with the
/// concrete release artifacts.
///
/// # Errors
/// Returns [`BfvError`] when the proof input material is malformed, embeds a witness that does not
