#[allow(clippy::too_many_lines)]
fn bfv_full_bootstrap_arithmetic_trace_rows_v1(
    proof_input_material: &BfvFullBootstrapExecutionProofInputMaterialV1,
) -> Result<Vec<Vec<u64>>, BfvError> {
    validate_bfv_full_bootstrap_execution_proof_input_material_v1(proof_input_material)?;
    let witness = &proof_input_material.witness_material;
    let params = &witness.params;
    let active_rows = params.degree();
    let padded_rows =
        usize::from(canonical_bfv_full_bootstrap_arithmetic_trace_padded_row_count_v1());
    invalid_if!(
        active_rows > padded_rows,
        "BFV full-bootstrap arithmetic trace active rows {active_rows} exceed padded STARK rows {padded_rows}"
    );
    let statement_limbs =
        bfv_full_bootstrap_hash_goldilocks_limbs_v1(proof_input_material.statement_hash);
    let mode = bfv_full_bootstrap_bound_mode_goldilocks_field_v1(witness.bound_mode);
    let slot_index = bfv_full_bootstrap_goldilocks_field_from_u128_v1(
        "BFV full-bootstrap arithmetic trace slot index",
        u128::from(witness.slot_index),
    )?;
    let input_bound = bfv_full_bootstrap_goldilocks_field_from_u128_v1(
        "BFV full-bootstrap arithmetic trace input bound",
        witness.input_bound,
    )?;
    let output_bound = bfv_full_bootstrap_goldilocks_field_from_u128_v1(
        "BFV full-bootstrap arithmetic trace output bound",
        witness.output_bound,
    )?;
    let bounds = [
        bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace coefficient-to-slot bound",
            witness.trace_bounds.coefficient_to_slot,
        )?,
        bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace blind-rotation bound",
            witness.trace_bounds.blind_rotation,
        )?,
        bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace raw extracted sample bound",
            witness.trace_bounds.raw_extracted_sample,
        )?,
        bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace coefficient-zero repack bound",
            witness.trace_bounds.coefficient_zero_repack,
        )?,
        bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace sample-switch bound",
            witness.trace_bounds.sample_switch,
        )?,
        bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace slot-to-coefficient bound",
            witness.trace_bounds.slot_to_coefficient,
        )?,
    ];
    let mut rows = Vec::with_capacity(padded_rows);
    for row_index in 0..padded_rows {
        let row_index_field = bfv_full_bootstrap_goldilocks_field_from_u128_v1(
            "BFV full-bootstrap arithmetic trace row index",
            u128::try_from(row_index)
                .map_err(|_| invalid!("BFV full-bootstrap arithmetic trace row index overflow"))?,
        )?;
        let mut row = Vec::with_capacity(usize::from(
            BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1,
        ));
        if row_index < active_rows {
            let coefficient_index = row_index;
            row.push(BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_KIND_ACTIVE_V1);
            row.push(row_index_field);
            row.push(bfv_full_bootstrap_goldilocks_field_from_u128_v1(
                "BFV full-bootstrap arithmetic trace coefficient index",
                u128::try_from(coefficient_index).map_err(|_| {
                    invalid!("BFV full-bootstrap arithmetic trace coefficient index overflow")
                })?,
            )?);
            row.push(slot_index);
            row.push(mode);
            row.extend_from_slice(&statement_limbs);
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "input ciphertext",
                &witness.input_ciphertext,
                coefficient_index,
            )?;
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "coefficient-to-slot output",
                &witness.trace.coefficient_to_slot_output,
                coefficient_index,
            )?;
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "blind-rotation output",
                &witness.trace.blind_rotation_output,
                coefficient_index,
            )?;
            row.push(bfv_full_bootstrap_goldilocks_field_from_u128_v1(
                "BFV full-bootstrap arithmetic trace raw sample source index",
                u128::from(witness.trace.raw_extracted_sample.source_coefficient_index),
            )?);
            row.push(bfv_full_bootstrap_goldilocks_field_from_u128_v1(
                "BFV full-bootstrap arithmetic trace raw sample constant",
                u128::from(witness.trace.raw_extracted_sample.constant_term),
            )?);
            row.push(bfv_full_bootstrap_goldilocks_field_from_u128_v1(
                "BFV full-bootstrap arithmetic trace raw sample secret coefficient",
                u128::from(
                    witness.trace.raw_extracted_sample.secret_coefficients[coefficient_index],
                ),
            )?);
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "coefficient-zero repack output",
                &witness.trace.coefficient_zero_repack_output,
                coefficient_index,
            )?;
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "diagnostic slot-to-coefficient output",
                &witness.trace.diagnostic_slot_to_coefficient_output,
                coefficient_index,
            )?;
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "sample-switch output",
                &witness.trace.sample_switch_output,
                coefficient_index,
            )?;
            push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
                &mut row,
                "slot-to-coefficient output",
                &witness.trace.slot_to_coefficient_output,
                coefficient_index,
            )?;
            row.push(input_bound);
            row.push(output_bound);
            row.extend_from_slice(&bounds);
        } else {
            row.push(BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_KIND_PADDING_V1);
            row.push(row_index_field);
            row.push(0);
            row.push(slot_index);
            row.push(mode);
            row.extend_from_slice(&statement_limbs);
            row.resize(
                usize::from(BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1),
                0,
            );
        }
        invalid_if!(
            row.len() != usize::from(BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1),
            "BFV full-bootstrap arithmetic trace row {row_index} has width {} instead of {}",
            row.len(),
            BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_ROW_WIDTH_V1
        );
        rows.push(row);
    }
    Ok(rows)
}
fn push_bfv_full_bootstrap_ciphertext_trace_coefficients_v1(
    row: &mut Vec<u64>,
    label: &str,
    ciphertext: &BfvCiphertext,
    coefficient_index: usize,
) -> Result<(), BfvError> {
    row.push(bfv_full_bootstrap_goldilocks_field_from_u128_v1(
        &format!("BFV full-bootstrap arithmetic trace {label} c0 coefficient"),
        u128::from(ciphertext.c0[coefficient_index]),
    )?);
    row.push(bfv_full_bootstrap_goldilocks_field_from_u128_v1(
        &format!("BFV full-bootstrap arithmetic trace {label} c1 coefficient"),
        u128::from(ciphertext.c1[coefficient_index]),
    )?);
    Ok(())
}
fn bfv_full_bootstrap_bound_mode_goldilocks_field_v1(
    mode: BfvFullBootstrapExecutionProofBoundModeV1,
) -> u64 {
    match mode {
        BfvFullBootstrapExecutionProofBoundModeV1::ExactResidualMultiple => 0,
        BfvFullBootstrapExecutionProofBoundModeV1::BoundedNoise => 1,
    }
}
fn bfv_full_bootstrap_hash_goldilocks_limbs_v1(hash: Hash) -> [u64; 8] {
    let bytes: [u8; Hash::LENGTH] = hash.into();
    let mut limbs = [0_u64; 8];
    // Each 32-bit word fits Goldilocks without reduction. Reducing four u64
    // words modulo the field aliases distinct 32-byte statement hashes.
    for (index, chunk) in bytes.chunks_exact(4).enumerate() {
        let mut word = [0_u8; 4];
        word.copy_from_slice(chunk);
        limbs[index] = u64::from(u32::from_le_bytes(word));
    }
    limbs
}
/// Return the statement-bound native BFV full-bootstrap STARK/AIR domain tag.
#[must_use]
pub fn bfv_full_bootstrap_native_stark_air_domain_tag_v1(statement_hash: Hash) -> String {
    let statement_hash_bytes: [u8; Hash::LENGTH] = statement_hash.into();
    let domain_tag_digest = bfv_goldilocks_digest384_v1(
        BfvGoldilocksDigest384DomainV1 {
            role: b"air-transcript",
            phase: b"domain-tag",
            level: 0,
            index: 0,
            counter: 0,
        },
        &[
            BFV_FULL_BOOTSTRAP_NATIVE_STARK_AIR_DOMAIN_TAG_DOMAIN,
            &statement_hash_bytes,
        ],
    )
    .expect("fixed BFV native-STARK AIR domain-tag fields fit the digest frame");
    hex::encode(domain_tag_digest.as_ref())
}
fn bfv_full_bootstrap_goldilocks_field_from_u128_v1(
    label: &str,
    value: u128,
) -> Result<u64, BfvError> {
    invalid_if!(
        value >= u128::from(BFV_FULL_BOOTSTRAP_NATIVE_STARK_GOLDILOCKS_MODULUS_V1),
        "{label} value {value} cannot be injectively encoded in the native Goldilocks field"
    );
    u64::try_from(value)
        .map_err(|_| invalid!("{label} value {value} exceeds native u64 field element range"))
}
fn validate_bfv_full_bootstrap_goldilocks_field_element_v1(
    label: &str,
    value: u64,
) -> Result<(), BfvError> {
    invalid_if!(
        value >= BFV_FULL_BOOTSTRAP_NATIVE_STARK_GOLDILOCKS_MODULUS_V1,
        "{label} is not a canonical native Goldilocks field element"
    );
    Ok(())
}
/// Build a full-bootstrap execution proof claim with its deterministic witness digest.
///
/// # Errors
/// Returns [`BfvError`] when the governed execution witness cannot be derived or when the supplied
/// output ciphertext/bound do not match that witness.
#[allow(clippy::too_many_arguments)]
pub fn bfv_full_bootstrap_execution_proof_claim_with_witness_digest_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    slot_index: u32,
    input_ciphertext: BfvCiphertext,
    output_ciphertext: BfvCiphertext,
    bound_mode: BfvFullBootstrapExecutionProofBoundModeV1,
    input_bound: u128,
    output_bound: u128,
) -> Result<BfvFullBootstrapExecutionProofClaimV1, BfvError> {
    let galois_key_set_digest = bfv_full_bootstrap_galois_key_set_digest_v1(params, galois_keys)?;
    let claim = BfvFullBootstrapExecutionProofClaimV1 {
        slot_index,
        input_ciphertext,
        output_ciphertext,
        bound_mode,
        input_bound,
        output_bound,
        galois_key_set_digest,
        execution_witness_digest: Hash::new(
            b"transient BFV full-bootstrap execution witness digest before finalization v1",
        ),
    };
    let execution_witness_digest = bfv_full_bootstrap_execution_witness_digest_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        &claim,
    )?;
    Ok(BfvFullBootstrapExecutionProofClaimV1 {
        execution_witness_digest,
        ..claim
    })
}
/// Return the statement digest after verifying the claim's execution witness digest.
///
/// # Errors
/// Returns [`BfvError`] when the witness digest does not match the governed arithmetic trace or
/// when the canonical statement digest cannot be derived.
pub fn bfv_full_bootstrap_execution_proof_statement_digest_with_witness_v1(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    claim: &BfvFullBootstrapExecutionProofClaimV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_execution_claim_digest_fields_v1(claim)?;
    let expected_witness_digest = bfv_full_bootstrap_execution_witness_digest_v1(
        params,
        bootstrap_key,
        artifacts,
        galois_keys,
        claim,
    )?;
    invalid_if!(
        claim.execution_witness_digest != expected_witness_digest,
        "BFV full-bootstrap execution proof witness digest mismatch"
    );
    bfv_full_bootstrap_execution_proof_statement_digest_v1(
        params,
        public_key,
        bootstrap_key,
        artifacts,
        claim,
    )
}
/// Return the public statement digest for one claimed full-bootstrap execution.
///
/// This statement is the proof-facing binding for a concrete input/output bootstrap claim. It
/// validates the public key, full-bootstrap key/material/artifact preflight, input and output
/// ciphertext shapes, and the exact or bounded-noise metadata before hashing the canonical
/// statement. Use [`bfv_full_bootstrap_execution_proof_statement_digest_with_witness_v1`] when the
/// caller has governed Galois keys and needs to recompute the arithmetic trace before accepting the
/// claim.
///
/// # Errors
/// Returns [`BfvError`] when public metadata is malformed, full-bootstrap material/artifacts do not
/// validate, exact/bounded metadata exceeds capacity, or canonical statement encoding fails.
pub fn bfv_full_bootstrap_execution_proof_statement_digest_v1(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    claim: &BfvFullBootstrapExecutionProofClaimV1,
) -> Result<Hash, BfvError> {
    validate_public_key(params, public_key)?;
    validate_bootstrap_key_public_key_digest(params, public_key, bootstrap_key)?;
    validate_bfv_full_bootstrap_execution_claim_digest_fields_v1(claim)?;
    invalid_if!(
        usize::try_from(claim.slot_index).map_or(true, |slot_index| slot_index >= params.degree()),
        "BFV full-bootstrap execution proof slot index exceeds parameter slot capacity"
    );
    validate_bfv_full_bootstrap_execution_artifacts_preflight_v1(
        params,
        bootstrap_key,
        &claim.input_ciphertext,
        artifacts,
    )?;
    validate_ciphertext_not_all_zero(
        "BFV full-bootstrap execution proof input ciphertext",
        &claim.input_ciphertext,
    )?;
    validate_ciphertext(params, &claim.output_ciphertext)?;
    validate_ciphertext_not_all_zero(
        "BFV full-bootstrap execution proof output ciphertext",
        &claim.output_ciphertext,
    )?;
    validate_bfv_full_bootstrap_execution_claim_ciphertext_digest_aliases_v1(params, claim)?;
    match claim.bound_mode {
        BfvFullBootstrapExecutionProofBoundModeV1::ExactResidualMultiple => {
            validate_exact_residual_bound_within_centered_capacity(
                params,
                claim.input_bound,
                "BFV full-bootstrap execution proof input residual bound",
            )?;
            validate_exact_residual_bound_within_centered_capacity(
                params,
                claim.output_bound,
                "BFV full-bootstrap execution proof output residual bound",
            )?;
        }
        BfvFullBootstrapExecutionProofBoundModeV1::BoundedNoise => {
            validate_bfv_bounded_noise_encryption_capacity(params)?;
            validate_bounded_noise_bound_within_decoding_capacity(
                params,
                claim.input_bound,
                "BFV full-bootstrap execution proof input bounded-noise bound",
            )?;
            validate_bounded_noise_bound_within_decoding_capacity(
                params,
                claim.output_bound,
                "BFV full-bootstrap execution proof output bounded-noise bound",
            )?;
        }
    }
    let material = bootstrap_key
        .full_bootstrap_material
        .as_ref()
        .ok_or_else(|| {
            invalid!("full BFV bootstrap key mode requires bootstrapping circuit material")
        })?;
    let full_bootstrap_material_digest =
        bfv_full_bootstrap_circuit_material_digest(params, material)?;
    let artifact_bundle_digest =
        bfv_full_bootstrap_circuit_artifact_bundle_digest(params, material, artifacts)?;
    let evaluator_artifact_set_digest =
        bfv_full_bootstrap_evaluator_artifact_set_digest_from_material_v1(params, material)?;
    validate_bfv_full_bootstrap_execution_claim_statement_digest_aliases_v1(
        params,
        public_key,
        &full_bootstrap_material_digest,
        &artifact_bundle_digest,
        &evaluator_artifact_set_digest,
        claim,
    )?;
    let statement = BfvFullBootstrapExecutionProofStatementMaterial {
        version: BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_MATERIAL_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_MATERIAL_FIELD_COUNT_V1,
        params: *params,
        public_key: public_key.clone(),
        bootstrap_key: bootstrap_key.clone(),
        full_bootstrap_material_digest,
        artifact_bundle_digest,
        claim: claim.clone(),
    };
    let bytes = norito::encode_canonical(&statement).map_err(|err| {
        invalid!("full-bootstrap execution proof statement encoding failed: {err}")
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_STATEMENT_DOMAIN,
        bytes.as_slice(),
    ]))
}
/// Apply a typed full-bootstrap packed-slot linear transform through registered exact RNS paths.
///
/// This evaluates the diagonal transform schema used by coefficient-to-slot and slot-to-coefficient
/// artifacts. Each diagonal uses an existing packed Galois rotation, a plaintext mask product, and
/// registered exact RNS accumulation, so the result is deterministic across hardware.
///
/// # Errors
/// Returns [`BfvError`] when the transform, ciphertext, required Galois keys, or registered RNS
/// profile are invalid.
pub(crate) fn apply_bfv_full_bootstrap_linear_transform_registered_rns_exact_v1(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    transform: &BfvFullBootstrapLinearTransformV1,
) -> Result<BfvCiphertext, BfvError> {
    let _rns_chain = registered_bfv_rns_modulus_chain(params)?;
    validate_bfv_full_bootstrap_linear_transform_v1(params, transform)?;
    validate_ciphertext(params, ciphertext)?;
    let mut output: Option<BfvCiphertext> = None;
    for diagonal in &transform.diagonals {
        let rotated = if diagonal.rotation_steps == 0 {
            ciphertext.clone()
        } else {
            rotate_packed_ciphertext_slots_left_with_galois_keys_registered_rns_exact(
                params,
                galois_keys,
                ciphertext,
                diagonal.rotation_steps,
            )?
        };
        let masked = multiply_plaintext_polynomial_registered_rns_exact(
            params,
            &rotated,
            &diagonal.plaintext,
        )?;
        output = Some(match output {
            Some(accumulator) => {
                add_ciphertexts_registered_rns_exact(params, &accumulator, &masked)?
            }
            None => masked,
        });
    }
    output.ok_or_else(|| {
        invalid!("BFV full-bootstrap linear transform produced an empty accumulator")
    })
}
/// Apply a typed full-bootstrap packed-slot linear transform through bounded-noise RNS paths.
///
/// # Errors
/// Returns [`BfvError`] when bounded-noise capacity, transform material, ciphertext, required
/// Galois keys, or registered RNS profile validation fails.
pub(crate) fn apply_bfv_full_bootstrap_linear_transform_bounded_noise_registered_rns_basis_extension_exact_v1(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    transform: &BfvFullBootstrapLinearTransformV1,
) -> Result<BfvCiphertext, BfvError> {
    let _rns_chain = registered_bfv_rns_modulus_chain(params)?;
    validate_bfv_bounded_noise_encryption_capacity(params)?;
    validate_bfv_full_bootstrap_linear_transform_v1(params, transform)?;
    validate_ciphertext(params, ciphertext)?;
    let mut output: Option<BfvCiphertext> = None;
    for diagonal in &transform.diagonals {
        let rotated = if diagonal.rotation_steps == 0 {
            ciphertext.clone()
        } else {
            rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise_registered_rns_basis_extension_exact(
                params,
                galois_keys,
                ciphertext,
                diagonal.rotation_steps,
            )?
        };
        let masked = multiply_plaintext_polynomial_bounded_noise_registered_rns_exact(
            params,
            &rotated,
            &diagonal.plaintext,
        )?;
        output = Some(match output {
            Some(accumulator) => {
                add_ciphertexts_bounded_noise_registered_rns_exact(params, &accumulator, &masked)?
            }
            None => masked,
        });
    }
    output.ok_or_else(|| {
        invalid!("BFV full-bootstrap bounded-noise linear transform produced an empty accumulator")
    })
}
/// Return the exact residual-multiple bound for a typed full-bootstrap linear transform.
///
/// The helper mirrors [`apply_bfv_full_bootstrap_linear_transform_registered_rns_exact_v1`]: each
/// diagonal optionally rotates the input, multiplies by the governed plaintext mask, and
/// contributes to a public addition accumulator.
///
/// # Errors
/// Returns [`BfvError`] when transform material is malformed, the input bound exceeds centered
/// residual capacity, required Galois keys are missing or malformed, or any intermediate/output
/// bound exceeds centered residual capacity.
pub(crate) fn bfv_full_bootstrap_linear_transform_output_residual_multiple_bound_v1(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    transform: &BfvFullBootstrapLinearTransformV1,
    input_bound: u128,
) -> Result<u128, BfvError> {
    validate_bfv_full_bootstrap_linear_transform_v1(params, transform)?;
    validate_exact_residual_bound_within_centered_capacity(
        params,
        input_bound,
        "BFV full-bootstrap linear transform input residual bound",
    )?;
    let mut contribution_bounds = Vec::with_capacity(transform.diagonals.len());
    for diagonal in &transform.diagonals {
        let rotated_bound = if diagonal.rotation_steps == 0 {
            input_bound
        } else {
            bfv_packed_rotate_left_output_residual_multiple_bound(
                params,
                galois_keys,
                input_bound,
                diagonal.rotation_steps,
            )?
        };
        let masked_bound = bfv_multiply_plaintext_polynomial_output_residual_multiple_bound(
            params,
            rotated_bound,
            &diagonal.plaintext,
        )?;
        contribution_bounds.push(masked_bound);
    }
    match contribution_bounds.as_slice() {
        [] => Err(invalid!(
            "BFV full-bootstrap linear transform bound produced an empty accumulator"
        )),
        [only] => Ok(*only),
        bounds => bfv_add_output_residual_multiple_bound(params, bounds),
    }
}
/// Return the bounded-noise bound for a typed full-bootstrap linear transform.
///
/// This is the rounded BFV counterpart to
/// [`bfv_full_bootstrap_linear_transform_output_residual_multiple_bound_v1`].
///
/// # Errors
/// Returns [`BfvError`] when rounded BFV capacity is too narrow, transform material is malformed,
/// the input bound exceeds rounded decoding capacity, required Galois keys are missing or
/// malformed, or any intermediate/output bound exceeds rounded decoding capacity.
pub(crate) fn bfv_full_bootstrap_linear_transform_bounded_noise_output_bound_v1(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    transform: &BfvFullBootstrapLinearTransformV1,
    input_noise_bound: u128,
) -> Result<u128, BfvError> {
    if let Err(err) = validate_bfv_bounded_noise_encryption_capacity(params) {
        validate_bfv_full_bootstrap_linear_transform_v1(params, transform)?;
        if transform
            .diagonals
            .iter()
            .any(|diagonal| diagonal.rotation_steps != 0)
        {
            validate_galois_key_set_metadata(
                params,
                galois_keys,
                "BFV full-bootstrap bounded-noise linear transform bound",
            )?;
        }
        return Err(err);
    }
    validate_bfv_full_bootstrap_linear_transform_v1(params, transform)?;
    validate_bounded_noise_bound_within_decoding_capacity(
        params,
        input_noise_bound,
        "BFV full-bootstrap bounded-noise linear transform input bound",
    )?;
    let mut contribution_bounds = Vec::with_capacity(transform.diagonals.len());
    for diagonal in &transform.diagonals {
        let rotated_bound = if diagonal.rotation_steps == 0 {
            input_noise_bound
        } else {
            bfv_packed_rotate_left_bounded_noise_output_bound(
                params,
                galois_keys,
                input_noise_bound,
                diagonal.rotation_steps,
            )?
        };
        let masked_bound = bfv_multiply_plaintext_polynomial_bounded_noise_output_bound(
            params,
            rotated_bound,
            &diagonal.plaintext,
        )?;
        contribution_bounds.push(masked_bound);
    }
    match contribution_bounds.as_slice() {
        [] => Err(invalid!(
            "BFV full-bootstrap bounded-noise linear transform bound produced an empty accumulator"
        )),
        [only] => Ok(*only),
        bounds => bfv_add_bounded_noise_output_bound(params, bounds),
    }
}
/// Apply a typed full-bootstrap blind rotation through registered exact RNS paths.
///
/// This consumes the governed selector schedule carried by [`BfvFullBootstrapBlindRotationKeyV1`].
/// Each step applies the declared Galois automorphism, masks the contribution with the typed
/// selector plaintext, and accumulates the result through the registered exact RNS corridor.
///
/// # Errors
/// Returns [`BfvError`] when blind-rotation material, ciphertext, required Galois keys, or
/// registered RNS profile validation fails.
pub(crate) fn apply_bfv_full_bootstrap_blind_rotation_registered_rns_exact_v1(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    key: &BfvFullBootstrapBlindRotationKeyV1,
) -> Result<BfvCiphertext, BfvError> {
    let rns_chain = registered_bfv_rns_modulus_chain(params)?;
    validate_bfv_full_bootstrap_blind_rotation_key_v1(params, key)?;
    validate_galois_key_set_metadata(params, galois_keys, "BFV full-bootstrap blind rotation")?;
    validate_ciphertext(params, ciphertext)?;
    validate_galois_key_set_entries(params, galois_keys)?;
    let mut output: Option<BfvCiphertext> = None;
    for step in &key.steps {
        let galois_key = galois_keys
            .iter()
            .find(|galois_key| galois_key.automorphism_power == step.automorphism_power)
            .ok_or_else(|| {
                invalid!(
                    "missing BFV Galois key for full-bootstrap blind-rotation automorphism power {}",
                    step.automorphism_power
                )
            })?;
        let transformed = apply_galois_automorphism_ciphertext_rns_exact(
            params, &rns_chain, galois_key, ciphertext,
        )?;
        let masked = multiply_plaintext_polynomial_rns_exact(
            params,
            &rns_chain,
            &transformed,
            &step.selector_plaintext,
        )?;
        output = Some(match output {
            Some(accumulator) => {
                add_ciphertexts_rns_exact(params, &rns_chain, &accumulator, &masked)?
            }
            None => masked,
        });
    }
    output.ok_or_else(|| {
        invalid!("BFV full-bootstrap blind rotation produced an empty Galois key schedule")
    })
}
/// Apply a typed full-bootstrap blind rotation through bounded-noise RNS paths.
///
/// The evaluator and key-switch decomposition chains are derived from the registered production BFV
/// profile before the governed selector schedule is evaluated. This is the bounded-noise
/// counterpart to [`apply_bfv_full_bootstrap_blind_rotation_registered_rns_exact_v1`].
///
/// # Errors
/// Returns [`BfvError`] when bounded-noise capacity, blind-rotation material, ciphertext, required
/// Galois keys, or registered RNS profile validation fails.
pub(crate) fn apply_bfv_full_bootstrap_blind_rotation_bounded_noise_registered_rns_basis_extension_exact_v1(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    key: &BfvFullBootstrapBlindRotationKeyV1,
) -> Result<BfvCiphertext, BfvError> {
    let evaluator_chain = registered_bfv_rns_modulus_chain(params)?;
    let decomposition_chain =
        registered_bfv_key_switch_decomposition_chain_for_evaluator(params, &evaluator_chain)?;
    validate_bfv_full_bootstrap_blind_rotation_key_v1(params, key)?;
    validate_galois_key_set_metadata(
        params,
        galois_keys,
        "BFV full-bootstrap bounded-noise blind rotation",
    )?;
    validate_bounded_noise_rns_basis_extension_corridor(
        params,
        &decomposition_chain,
        &evaluator_chain,
        "BFV full-bootstrap bounded-noise blind-rotation decomposition",
    )?;
    validate_ciphertext(params, ciphertext)?;
    validate_galois_key_set_entries(params, galois_keys)?;
    let mut output: Option<BfvCiphertext> = None;
    for step in &key.steps {
        let galois_key = galois_keys
            .iter()
            .find(|galois_key| galois_key.automorphism_power == step.automorphism_power)
            .ok_or_else(|| {
                invalid!(
                    "missing BFV Galois key for full-bootstrap bounded-noise blind-rotation automorphism power {}",
                    step.automorphism_power
                )
            })?;
        let transformed =
            apply_galois_automorphism_ciphertext_bounded_noise_rns_basis_extension_exact(
                params,
                &decomposition_chain,
                &evaluator_chain,
                galois_key,
                ciphertext,
            )?;
        let masked = multiply_plaintext_polynomial_bounded_noise_rns_exact(
            params,
            &evaluator_chain,
            &transformed,
            &step.selector_plaintext,
        )?;
        output = Some(match output {
            Some(accumulator) => {
                add_ciphertexts_rns_exact(params, &evaluator_chain, &accumulator, &masked)?
            }
            None => masked,
        });
    }
    output.ok_or_else(|| {
        invalid!(
            "BFV full-bootstrap bounded-noise blind rotation produced an empty Galois key schedule"
        )
    })
}
/// Return the exact residual-multiple bound for typed full-bootstrap blind rotation.
///
/// This mirrors [`apply_bfv_full_bootstrap_blind_rotation_registered_rns_exact_v1`]: each governed
/// schedule entry applies one Galois key switch, multiplies the switched ciphertext by the declared
/// selector plaintext, and the masked contributions are accumulated.
///
/// # Errors
/// Returns [`BfvError`] when the blind-rotation material is malformed, the input bound exceeds
/// centered residual capacity, required Galois keys are missing or malformed, or any
/// intermediate/output bound exceeds centered residual capacity.
pub(crate) fn bfv_full_bootstrap_blind_rotation_output_residual_multiple_bound_v1(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    key: &BfvFullBootstrapBlindRotationKeyV1,
    input_bound: u128,
) -> Result<u128, BfvError> {
    validate_bfv_full_bootstrap_blind_rotation_key_v1(params, key)?;
    validate_galois_key_set_metadata(
        params,
        galois_keys,
        "BFV full-bootstrap blind rotation bound",
    )?;
    validate_exact_residual_bound_within_centered_capacity(
        params,
        input_bound,
        "BFV full-bootstrap blind rotation input residual bound",
    )?;
    validate_galois_key_set_entries(params, galois_keys)?;
    let mut contribution_bounds = Vec::with_capacity(key.steps.len());
    for step in &key.steps {
        let galois_key = galois_keys
            .iter()
            .find(|galois_key| galois_key.automorphism_power == step.automorphism_power)
            .ok_or_else(|| {
                invalid!(
                    "missing BFV Galois key for full-bootstrap blind-rotation bound automorphism power {}",
                    step.automorphism_power
                )
            })?;
        let switched_bound =
            bfv_galois_key_switch_output_residual_multiple_bound(params, galois_key, input_bound)?;
        let masked_bound = bfv_multiply_plaintext_polynomial_output_residual_multiple_bound(
            params,
            switched_bound,
            &step.selector_plaintext,
        )?;
        contribution_bounds.push(masked_bound);
    }
    match contribution_bounds.as_slice() {
        [] => Err(invalid!(
            "BFV full-bootstrap blind rotation bound produced an empty Galois key schedule"
        )),
        [only] => Ok(*only),
        bounds => bfv_add_output_residual_multiple_bound(params, bounds),
    }
}
/// Return the bounded-noise bound for typed full-bootstrap blind rotation.
///
/// This is the rounded BFV counterpart to
/// [`bfv_full_bootstrap_blind_rotation_output_residual_multiple_bound_v1`], and
/// mirrors
/// [`apply_bfv_full_bootstrap_blind_rotation_bounded_noise_registered_rns_basis_extension_exact_v1`]
/// at the public bound-accounting layer.
///
/// # Errors
/// Returns [`BfvError`] when rounded BFV capacity is too narrow, the blind-rotation material is
/// malformed, the input bound exceeds rounded decoding capacity, required Galois keys are missing
/// or malformed, or any intermediate/output bound exceeds rounded decoding capacity.
pub(crate) fn bfv_full_bootstrap_blind_rotation_bounded_noise_output_bound_v1(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    key: &BfvFullBootstrapBlindRotationKeyV1,
    input_noise_bound: u128,
) -> Result<u128, BfvError> {
    if let Err(err) = validate_bfv_bounded_noise_encryption_capacity(params) {
        validate_bfv_full_bootstrap_blind_rotation_key_v1(params, key)?;
        validate_galois_key_set_metadata(
            params,
            galois_keys,
            "BFV full-bootstrap bounded-noise blind rotation bound",
        )?;
        return Err(err);
    }
    validate_bfv_full_bootstrap_blind_rotation_key_v1(params, key)?;
    validate_galois_key_set_metadata(
        params,
        galois_keys,
        "BFV full-bootstrap bounded-noise blind rotation bound",
    )?;
    validate_bounded_noise_bound_within_decoding_capacity(
        params,
        input_noise_bound,
        "BFV full-bootstrap bounded-noise blind rotation input bound",
    )?;
    validate_galois_key_set_entries(params, galois_keys)?;
    let mut contribution_bounds = Vec::with_capacity(key.steps.len());
    for step in &key.steps {
        let galois_key = galois_keys
            .iter()
            .find(|galois_key| galois_key.automorphism_power == step.automorphism_power)
            .ok_or_else(|| {
                invalid!(
                    "missing BFV Galois key for full-bootstrap bounded-noise blind-rotation bound automorphism power {}",
                    step.automorphism_power
                )
            })?;
        let switched_bound = bfv_galois_key_switch_bounded_noise_output_bound(
            params,
            galois_key,
            input_noise_bound,
        )?;
        let masked_bound = bfv_multiply_plaintext_polynomial_bounded_noise_output_bound(
            params,
            switched_bound,
            &step.selector_plaintext,
        )?;
        contribution_bounds.push(masked_bound);
    }
    match contribution_bounds.as_slice() {
        [] => Err(invalid!(
            "BFV full-bootstrap bounded-noise blind rotation bound produced an empty Galois key schedule"
        )),
        [only] => Ok(*only),
        bounds => bfv_add_bounded_noise_output_bound(params, bounds),
    }
}
/// Validate the proof-facing profile bound by full-bootstrap material.
///
/// This is the verifier admission companion to [`validate_bfv_full_bootstrap_circuit_material_v1`].
/// Callers provide the expected governed BFV proof public-input schema artifact digest and, once a
/// proof attachment is available, the verifier-key material commitment expected for the proof that
/// will govern this material. The crypto layer then enforces that the full-bootstrap material
/// commits to exactly those proof-facing values.
///
/// # Errors
/// Returns [`BfvError`] when the material is invalid, either expected digest is empty, or the
/// material proof profile does not match the expected schema or verifier-key material commitment.
pub fn validate_bfv_full_bootstrap_material_proof_profile_v1(
    params: &BfvParameters,
    material: &BfvFullBootstrapCircuitMaterialV1,
    expected_public_input_schema_digest: &Hash,
    expected_verifier_key_material_commitment: Option<&Hash>,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_circuit_material_v1(params, material)?;
    validate_nonzero_material_digest(
        "expected BFV full-bootstrap proof public-input schema digest",
        expected_public_input_schema_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "expected BFV full-bootstrap proof public-input schema digest",
        expected_public_input_schema_digest,
    )?;
    invalid_if!(
        material.proof_public_input_schema_digest != *expected_public_input_schema_digest,
        "BFV full-bootstrap proof public-input schema digest does not match expected verifier profile"
    );
    if let Some(expected_verifier_key_material_commitment) =
        expected_verifier_key_material_commitment
    {
        validate_nonzero_material_digest(
            "expected BFV full-bootstrap verifier-key material commitment",
            expected_verifier_key_material_commitment,
        )?;
        validate_no_full_bootstrap_placeholder_material_digest(
            "expected BFV full-bootstrap verifier-key material commitment",
            expected_verifier_key_material_commitment,
        )?;
        invalid_if!(
            material.verifier_key_material_commitment != *expected_verifier_key_material_commitment,
            "BFV full-bootstrap verifier-key material commitment does not match expected verifier profile"
        );
    }
    Ok(())
}
/// Refresh a ciphertext with round zero from a public bootstrap key.
///
/// # Errors
/// Returns [`BfvError`] when the input or refresh key does not match the parameter set.
pub fn bootstrap_ciphertext(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    ciphertext: &BfvCiphertext,
) -> Result<BfvCiphertext, BfvError> {
    bootstrap_ciphertext_round(params, bootstrap_key, ciphertext, 0)
}
/// Refresh a ciphertext with one indexed public bootstrap-key round.
///
/// # Errors
/// Returns [`BfvError`] when the input, refresh key, or round index does not match the parameter
/// set.
pub fn bootstrap_ciphertext_round(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    ciphertext: &BfvCiphertext,
    round_index: u16,
) -> Result<BfvCiphertext, BfvError> {
    params.validate()?;
    validate_bootstrap_key_refresh_round_index_request(
        bootstrap_key,
        round_index,
        "BFV bootstrap refresh",
    )?;
    validate_bfv_seeded_bootstrap_refresh_round_capacity(
        params,
        bootstrap_key.max_refresh_rounds,
        "BFV bootstrap key",
    )?;
    validate_bootstrap_key_for_refresh_application(params, bootstrap_key)?;
    add_ciphertexts(
        params,
        ciphertext,
        bootstrap_round_refresh(bootstrap_key, round_index)?,
    )
}
/// Refresh a ciphertext with consecutive public bootstrap-key rounds.
///
/// The requested round count is validated against the key before the first refresh is applied, so
/// callers cannot accidentally rely on a partial multi-round refresh when the request exceeds the
/// key capacity.
///
/// # Errors
/// Returns [`BfvError`] when the input, refresh key, or requested round count does not match the
/// parameter set.
pub fn bootstrap_ciphertext_rounds(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    ciphertext: &BfvCiphertext,
    refresh_rounds: u16,
) -> Result<BfvCiphertext, BfvError> {
    params.validate()?;
    validate_bootstrap_key_refresh_round_count_request(
        bootstrap_key,
        refresh_rounds,
        "BFV bootstrap refresh",
    )?;
    validate_bfv_seeded_bootstrap_refresh_round_capacity(
        params,
        bootstrap_key.max_refresh_rounds,
        "BFV bootstrap key",
    )?;
    validate_bootstrap_key_for_refresh_application(params, bootstrap_key)?;
    let mut refreshed = ciphertext.clone();
    for round_index in 0..refresh_rounds {
        refreshed = add_ciphertexts(
            params,
            &refreshed,
            bootstrap_round_refresh(bootstrap_key, round_index)?,
        )?;
    }
    Ok(refreshed)
}
