/// Refresh a rounded BFV ciphertext with consecutive bounded-noise bootstrap rounds through an
/// exact RNS corridor.
///
/// The requested round count is validated against the key before the first refresh is applied, so
/// callers cannot accidentally rely on a partial multi-round refresh when the request exceeds the
/// key capacity.
///
/// # Errors
/// Returns [`BfvError`] when the input, refresh key, requested round count, or RNS chain does not
/// match the parameter set.
pub fn bootstrap_ciphertext_bounded_noise_rns_exact_rounds(
    params: &BfvParameters,
    rns_chain: &BfvRnsModulusChain,
    bootstrap_key: &BfvBootstrapKey,
    ciphertext: &BfvCiphertext,
    refresh_rounds: u16,
) -> Result<BfvCiphertext, BfvError> {
    validate_bootstrap_key_refresh_round_count_request_before_rns_corridor(
        bootstrap_key,
        refresh_rounds,
        "BFV bounded-noise bootstrap refresh",
    )?;
    validate_bounded_noise_rns_addition_corridor(params, rns_chain)?;
    validate_bootstrap_key_refresh_round_count_request(
        bootstrap_key,
        refresh_rounds,
        "BFV bounded-noise bootstrap refresh",
    )?;
    validate_bfv_bounded_noise_bootstrap_refresh_round_capacity(
        params,
        bootstrap_key.max_refresh_rounds,
        "BFV bounded-noise RNS bootstrap key",
    )?;
    validate_bootstrap_key_for_refresh_application(params, bootstrap_key)?;
    let mut refreshed = ciphertext.clone();
    for round_index in 0..refresh_rounds {
        refreshed = add_ciphertexts_rns_exact(
            params,
            rns_chain,
            &refreshed,
            bootstrap_round_refresh(bootstrap_key, round_index)?,
        )?;
    }
    Ok(refreshed)
}
