/// Validate the public inputs needed before full BFV bootstrap execution.
///
/// This is the checked boundary shared by direct fail-closed entries and artifact-aware
/// full-bootstrap evaluators. It validates `FullBootstrapV1` mode, governed circuit-material
/// commitments, registered RNS/decomposition profile digests, refresh-material shapes still carried
/// by the versioned key, and the input ciphertext shape.
///
/// # Errors
/// Returns [`BfvError`] when the key is not a full-bootstrap key, material is missing or
/// mismatched, registered profile validation fails, or the input ciphertext does not match
/// `params`.
pub fn validate_bfv_full_bootstrap_execution_preflight_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    ciphertext: &BfvCiphertext,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_key_execution_preflight_v1(params, bootstrap_key)?;
    validate_ciphertext(params, ciphertext)?;
    validate_ciphertext_not_all_zero("BFV full-bootstrap execution input ciphertext", ciphertext)
}
/// Validate full-bootstrap execution inputs plus concrete circuit artifacts.
///
/// This is the stronger preflight for artifact-aware execution. It keeps the existing
/// ciphertext/material checks and additionally proves every artifact byte payload matches the
/// digest commitments in the `FullBootstrapV1` bootstrap key.
///
/// # Errors
/// Returns [`BfvError`] when execution preflight fails, full material is missing, or artifact
/// validation fails.
pub fn validate_bfv_full_bootstrap_execution_artifacts_preflight_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    ciphertext: &BfvCiphertext,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_execution_artifact_bundle_preflight_v1(
        params,
        bootstrap_key,
        artifacts,
    )?;
    validate_ciphertext(params, ciphertext)?;
    validate_ciphertext_not_all_zero(
        "BFV artifact-aware full-bootstrap execution input ciphertext",
        ciphertext,
    )
}
fn validate_bfv_full_bootstrap_execution_artifact_bundle_preflight_v1<'a>(
    params: &BfvParameters,
    bootstrap_key: &'a BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
) -> Result<&'a BfvFullBootstrapCircuitMaterialV1, BfvError> {
    validate_bfv_full_bootstrap_key_execution_preflight_v1(params, bootstrap_key)?;
    let material = full_bootstrap_material_from_key(bootstrap_key)?;
    validate_bfv_full_bootstrap_circuit_artifact_bundle_v1(params, material, artifacts)?;
    validate_bfv_full_bootstrap_execution_artifact_bundle_public_key_digest_aliases_v1(
        params,
        bootstrap_key,
        material,
        artifacts,
    )?;
    Ok(material)
}
fn validate_bfv_full_bootstrap_execution_artifact_bundle_public_key_digest_aliases_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    material: &BfvFullBootstrapCircuitMaterialV1,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
) -> Result<(), BfvError> {
    let public_key_digest = bootstrap_key
        .public_key_digest
        .as_ref()
        .ok_or_else(|| invalid!("FullBootstrapV1 BFV bootstrap key requires public-key digest"))?;
    let artifact_bundle_digest =
        bfv_full_bootstrap_circuit_artifact_bundle_digest_for_alias_preflight_v1(artifacts)?;
    let evaluator_artifact_set_digest =
        bfv_full_bootstrap_evaluator_artifact_set_digest_from_material_v1(params, material)?;
    validate_bfv_full_bootstrap_digest_material_hashes(
        "BFV artifact-aware full-bootstrap execution preflight",
        &[
            ("public-key digest", public_key_digest),
            ("artifact bundle digest", &artifact_bundle_digest),
            (
                "evaluator artifact set digest",
                &evaluator_artifact_set_digest,
            ),
        ],
    )
}
fn full_bootstrap_material_from_key(
    bootstrap_key: &BfvBootstrapKey,
) -> Result<&BfvFullBootstrapCircuitMaterialV1, BfvError> {
    bootstrap_key
        .full_bootstrap_material
        .as_ref()
        .ok_or_else(|| {
            invalid!("full BFV bootstrap key mode requires bootstrapping circuit material")
        })
}
fn decode_full_bootstrap_execution_prefix_artifacts_v1(
    params: &BfvParameters,
    material: &BfvFullBootstrapCircuitMaterialV1,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
) -> Result<
    (
        BfvFullBootstrapLinearTransformV1,
        BfvFullBootstrapLinearTransformV1,
        BfvFullBootstrapBlindRotationKeyV1,
        BfvFullBootstrapSampleExtractionSwitchKeyV1,
    ),
    BfvError,
> {
    let coefficient_to_slot = decode_bfv_full_bootstrap_linear_transform_artifact_v1(
        params,
        material,
        BfvFullBootstrapCircuitArtifactRoleV1::CoefficientToSlotKey,
        &artifacts.coefficient_to_slot_key,
    )?;
    let slot_to_coefficient = decode_bfv_full_bootstrap_linear_transform_artifact_v1(
        params,
        material,
        BfvFullBootstrapCircuitArtifactRoleV1::SlotToCoefficientKey,
        &artifacts.slot_to_coefficient_key,
    )?;
    let blind_rotation = decode_bfv_full_bootstrap_blind_rotation_artifact_v1(
        params,
        material,
        &artifacts.blind_rotation_key,
    )?;
    let sample_switch_key = decode_bfv_full_bootstrap_sample_extraction_switch_key_artifact_v1(
        params,
        material,
        &artifacts.sample_extraction_key,
    )?;
    Ok((
        coefficient_to_slot,
        slot_to_coefficient,
        blind_rotation,
        sample_switch_key,
    ))
}
fn validate_bfv_full_bootstrap_execution_galois_key_set_v1(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    coefficient_to_slot: &BfvFullBootstrapLinearTransformV1,
    blind_rotation: &BfvFullBootstrapBlindRotationKeyV1,
    slot_to_coefficient: &BfvFullBootstrapLinearTransformV1,
) -> Result<(), BfvError> {
    validate_galois_key_set_metadata(
        params,
        galois_keys,
        "BFV full-bootstrap execution Galois key set",
    )?;
    let mut required_powers = std::collections::BTreeSet::new();
    collect_full_bootstrap_linear_transform_galois_powers_v1(
        params,
        coefficient_to_slot,
        &mut required_powers,
    )?;
    for step in &blind_rotation.steps {
        required_powers.insert(step.automorphism_power);
    }
    collect_full_bootstrap_linear_transform_galois_powers_v1(
        params,
        slot_to_coefficient,
        &mut required_powers,
    )?;
    let supplied_powers = galois_keys
        .iter()
        .map(|key| key.automorphism_power)
        .collect::<std::collections::BTreeSet<_>>();
    if let Some(missing_power) = required_powers.difference(&supplied_powers).next() {
        return Err(invalid!(
            "missing BFV Galois key for full-bootstrap execution automorphism power {missing_power}"
        ));
    }
    if let Some(extra_power) = supplied_powers.difference(&required_powers).next() {
        return Err(invalid!(
            "unexpected BFV Galois key for full-bootstrap execution automorphism power {extra_power}"
        ));
    }
    validate_galois_key_set_entries(params, galois_keys)
}
fn collect_full_bootstrap_linear_transform_galois_powers_v1(
    params: &BfvParameters,
    transform: &BfvFullBootstrapLinearTransformV1,
    required_powers: &mut std::collections::BTreeSet<u32>,
) -> Result<(), BfvError> {
    for diagonal in &transform.diagonals {
        if diagonal.rotation_steps == 0 {
            continue;
        }
        for (automorphism_power, _) in
            packed_left_rotation_galois_schedule(params, diagonal.rotation_steps)?
        {
            required_powers.insert(automorphism_power);
        }
    }
    Ok(())
}
/// Execute the governed exact-RNS full-bootstrap prefix through raw sample extraction.
///
/// This validates the same concrete artifacts as
/// [`validate_bfv_full_bootstrap_execution_artifacts_preflight_v1`] and then consumes the
/// coefficient-to-slot, blind-rotation, and sample-extraction payloads, switching the raw sample
/// through governed key-switch material, and feeding the result through the governed
/// slot-to-coefficient transform.
///
/// # Errors
/// Returns [`BfvError`] when full-bootstrap key/material preflight fails, artifacts do not match
/// governed commitments, required Galois keys are missing or malformed, or any executable prefix
/// stage fails.
pub(crate) fn apply_bfv_full_bootstrap_execution_prefix_trace_registered_rns_exact_v1(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
) -> Result<BfvFullBootstrapExecutionPrefixTraceV1, BfvError> {
    let _rns_chain = registered_bfv_rns_modulus_chain(params)?;
    let material = validate_bfv_full_bootstrap_execution_artifact_bundle_preflight_v1(
        params,
        bootstrap_key,
        artifacts,
    )?;
    let (coefficient_to_slot, slot_to_coefficient, blind_rotation, sample_switch_key) =
        decode_full_bootstrap_execution_prefix_artifacts_v1(params, material, artifacts)?;
    validate_bfv_full_bootstrap_execution_galois_key_set_v1(
        params,
        galois_keys,
        &coefficient_to_slot,
        &blind_rotation,
        &slot_to_coefficient,
    )?;
    validate_ciphertext(params, ciphertext)?;
    validate_ciphertext_not_all_zero(
        "BFV exact full-bootstrap prefix input ciphertext",
        ciphertext,
    )?;
    let coefficient_to_slot_output =
        apply_bfv_full_bootstrap_linear_transform_registered_rns_exact_v1(
            params,
            galois_keys,
            ciphertext,
            &coefficient_to_slot,
        )?;
    let blind_rotation_output = apply_bfv_full_bootstrap_blind_rotation_registered_rns_exact_v1(
        params,
        galois_keys,
        &coefficient_to_slot_output,
        &blind_rotation,
    )?;
    let raw_extracted_sample = apply_bfv_full_bootstrap_sample_extraction_raw_lwe_v1(
        params,
        &blind_rotation_output,
        sample_switch_key.sample_extraction,
    )?;
    let coefficient_zero_repack_output =
        repack_bfv_full_bootstrap_raw_sample_as_coefficient_zero_ciphertext_v1(
            params,
            &raw_extracted_sample,
        )?;
    let diagnostic_slot_to_coefficient_output =
        apply_bfv_full_bootstrap_linear_transform_registered_rns_exact_v1(
            params,
            galois_keys,
            &coefficient_zero_repack_output,
            &slot_to_coefficient,
        )?;
    let sample_switch_output =
        apply_bfv_full_bootstrap_sample_extraction_switch_key_registered_rns_exact_v1(
            params,
            &sample_switch_key,
            &raw_extracted_sample,
        )?;
    let slot_to_coefficient_output =
        apply_bfv_full_bootstrap_linear_transform_registered_rns_exact_v1(
            params,
            galois_keys,
            &sample_switch_output,
            &slot_to_coefficient,
        )?;
    let trace = BfvFullBootstrapExecutionPrefixTraceV1 {
        coefficient_to_slot_output,
        blind_rotation_output,
        raw_extracted_sample,
        coefficient_zero_repack_output,
        diagnostic_slot_to_coefficient_output,
        sample_switch_output,
        slot_to_coefficient_output,
    };
    validate_bfv_full_bootstrap_execution_prefix_trace_v1(params, &trace)?;
    Ok(trace)
}
