/// Derive a deterministic public slot-rotation key from a BFV public key.
///
/// The resulting key contains an encryption of zero used to refresh every ciphertext moved by an
/// outer envelope slot rotation.
///
/// # Errors
/// Returns [`BfvError`] when the rotation step, parameter set, public-key shape, or public
/// transcript seed bounds are invalid.
pub(crate) fn rotation_key_from_seed(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    rotation_steps: u32,
    seed: &[u8],
) -> Result<BfvRotationKey, BfvError> {
    invalid_if!(
        rotation_steps == 0,
        "rotation key steps must be greater than zero"
    );
    validate_refresh_transcript_seed("rotation refresh transcript seed", seed)?;
    validate_bfv_seeded_encryption_residual_capacity(params)?;
    validate_public_key(params, public_key)?;
    let zero_refresh = encrypt_from_seed(params, public_key, &[0], seed)?;
    let rotation_key = BfvRotationKey {
        rotation_steps,
        zero_refresh,
    };
    validate_rotation_key(params, &rotation_key)?;
    Ok(rotation_key)
}
