///
/// This is a key-owner diagnostic for the current outer-slot refresh path. Public evaluators reject
/// inert all-zero refresh material before applying the key to a ciphertext-slot envelope.
///
/// # Errors
/// Returns [`BfvError`] when the key is malformed or its refresh ciphertext decrypts to a non-zero
/// plaintext under `secret_key`.
pub fn validate_rotation_key_zero_refresh(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    rotation_key: &BfvRotationKey,
) -> Result<(), BfvError> {
    validate_rotation_key_zero_refresh_with_label(
        params,
        secret_key,
        rotation_key,
        "rotation key zero_refresh",
    )
}
fn validate_rotation_key_zero_refresh_with_label(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    rotation_key: &BfvRotationKey,
    label: &str,
) -> Result<(), BfvError> {
    validate_rotation_key(params, rotation_key)?;
    validate_bfv_seeded_encryption_residual_capacity(params)?;
    validate_ciphertext_not_all_zero(label, &rotation_key.zero_refresh)?;
    validate_refresh_ciphertext_decrypts_to_zero(
        params,
        secret_key,
        &rotation_key.zero_refresh,
        label,
    )
}
/// Verify that a bounded-noise rotation-key refresh ciphertext decrypts to zero.
///
/// This checks the rounded BFV plaintext and fresh bounded-noise budget for the outer-slot rotation
/// refresh mask.
///
/// # Errors
/// Returns [`BfvError`] when the key is malformed, its refresh ciphertext decrypts to non-zero
/// plaintext, or it exceeds the bounded-noise budget.
pub fn validate_rotation_key_bounded_noise_zero_refresh(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    rotation_key: &BfvRotationKey,
) -> Result<(), BfvError> {
    validate_rotation_key_bounded_noise_zero_refresh_with_label(
        params,
        secret_key,
        rotation_key,
        "bounded-noise rotation key zero_refresh",
    )
}
fn validate_rotation_key_bounded_noise_zero_refresh_with_label(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    rotation_key: &BfvRotationKey,
    label: &str,
) -> Result<(), BfvError> {
    validate_rotation_key_metadata(params, rotation_key)?;
    validate_bfv_bounded_noise_encryption_capacity(params)?;
    validate_rotation_key_for_refresh_application(params, rotation_key)?;
    let refresh_bound = bfv_fresh_bounded_noise_ciphertext_bound(params)?;
    validate_bounded_noise_zero_refresh_ciphertext(
        params,
        secret_key,
        &rotation_key.zero_refresh,
        refresh_bound,
        label,
    )
}
fn validate_bounded_noise_zero_refresh_ciphertext(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    refresh: &BfvCiphertext,
    refresh_bound: u128,
    label: &str,
) -> Result<(), BfvError> {
    validate_ciphertext(params, refresh)?;
    validate_ciphertext_not_all_zero(label, refresh)?;
    let profile =
        validate_ciphertext_bounded_noise(params, secret_key, refresh, refresh_bound, label)?;
    invalid_if!(
        profile
            .plaintext
            .iter()
            .any(|&coefficient| coefficient != 0),
        "{label} must decrypt to zero plaintext"
    );
    Ok(())
}
/// Verify that a rotation refresh key matches its public deterministic transcript.
///
/// This check recomputes the encrypted-zero refresh mask from the advertised seed, public key, and
/// rotation step count. It provides a public transcript check for the current outer-slot refresh
/// path, while the owner-side [`validate_rotation_key_zero_refresh`] diagnostic remains the
/// secret-key check that the ciphertext decrypts to zero.
///
/// # Errors
/// Returns [`BfvError`] when the key or public key is malformed, or when the refresh ciphertext
/// differs from the deterministic transcript.
pub fn validate_rotation_key_zero_refresh_transcript(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    rotation_key: &BfvRotationKey,
    seed: &[u8],
) -> Result<(), BfvError> {
    validate_refresh_transcript_seed("rotation refresh transcript seed", seed)?;
    validate_rotation_key_metadata(params, rotation_key)?;
    validate_bfv_seeded_encryption_residual_capacity(params)?;
    validate_public_key(params, public_key)?;
    validate_rotation_key_entries(params, rotation_key)?;
    validate_ciphertext_not_all_zero("rotation key zero_refresh", &rotation_key.zero_refresh)?;
    let expected = rotation_key_from_seed(params, public_key, rotation_key.rotation_steps, seed)?;
    if expected.zero_refresh != rotation_key.zero_refresh {
        return Err(BfvError::ShapeMismatch(
            "rotation key zero_refresh does not match deterministic encrypted-zero transcript"
                .to_owned(),
        ));
    }
    Ok(())
}
/// Verify that a bounded-noise rotation refresh key matches its public transcript.
///
/// This recomputes the rounded BFV encrypted-zero refresh mask from the advertised seed, public
/// key, and rotation step count.
///
/// # Errors
/// Returns [`BfvError`] when the key or public key is malformed, or when the refresh ciphertext
/// differs from the deterministic bounded-noise transcript.
pub fn validate_rotation_key_bounded_noise_zero_refresh_transcript(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    rotation_key: &BfvRotationKey,
    seed: &[u8],
) -> Result<(), BfvError> {
    validate_refresh_transcript_seed("bounded-noise rotation refresh transcript seed", seed)?;
    validate_rotation_key_metadata(params, rotation_key)?;
    validate_bfv_bounded_noise_encryption_capacity(params)?;
    validate_public_key(params, public_key)?;
    validate_rotation_key_entries(params, rotation_key)?;
    validate_ciphertext_not_all_zero(
        "bounded-noise rotation key zero_refresh",
        &rotation_key.zero_refresh,
    )?;
    let expected = rotation_key_bounded_noise_from_seed(
        params,
        public_key,
        rotation_key.rotation_steps,
        seed,
    )?;
    if expected.zero_refresh != rotation_key.zero_refresh {
        return Err(BfvError::ShapeMismatch(
            "bounded-noise rotation key zero_refresh does not match deterministic encrypted-zero transcript"
                .to_owned(),
        ));
    }
    Ok(())
}
/// Rotate an identifier ciphertext-slot envelope left and refresh each moved slot.
///
/// This helper implements Soracloud `RotateLeft`: it rotates the outer vector of BFV scalar
/// ciphertext slots by the key's declared step count, then adds the key's encrypted-zero refresh
/// mask to every output slot. The plaintext slot order changes, ciphertext bytes change, and the
/// evaluator never needs a BFV secret key.
///
/// # Errors
/// Returns [`BfvError`] when the key or any ciphertext slot does not match the parameter set, or
/// when the normalized rotation would be empty/full-cycle.
pub fn rotate_ciphertext_slots_left(
    params: &BfvParameters,
    rotation_key: &BfvRotationKey,
    slots: &[BfvCiphertext],
) -> Result<Vec<BfvCiphertext>, BfvError> {
    params.validate()?;
    let normalized_steps = rotation_steps_mod_slot_count(rotation_key.rotation_steps, slots.len())?;
    validate_rotation_key_for_refresh_application(params, rotation_key)?;
    for slot in slots {
        validate_ciphertext(params, slot)?;
    }
    let mut rotated = slots.to_vec();
    rotated.rotate_left(normalized_steps);
    rotated
        .iter()
        .map(|slot| add_ciphertexts(params, slot, &rotation_key.zero_refresh))
        .collect()
}
/// Rotate an identifier ciphertext-slot envelope left and refresh each moved slot through an exact
