/// Return the extra exact residual-multiple bound for one key-switch operation.
///
/// Current deterministic key-switch entries carry plaintext-multiple error coefficients bounded by
/// `BFV_ERROR_MULTIPLE_BOUND`. Each decomposition digit coefficient is below the decomposition
/// base, so each output coefficient gets at most `n * (base - 1) * E` residual multiples per digit.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is invalid or the bound exceeds deterministic
/// integer limits.
pub fn bfv_key_switch_extra_residual_multiple_bound(
    params: &BfvParameters,
) -> Result<u128, BfvError> {
    params.validate()?;
    let degree = u128::from(params.polynomial_degree);
    let digits = u128::try_from(params.decomposition_digits()?).map_err(|_| {
        invalid!("BFV key-switch decomposition digit count exceeds deterministic limits")
    })?;
    let digit_bound = u128::from(params.decomposition_base().checked_sub(1).ok_or_else(|| {
        invalid!("BFV key-switch decomposition base is below deterministic digit bounds")
    })?);
    degree
        .checked_mul(digits)
        .and_then(|value| value.checked_mul(digit_bound))
        .and_then(|value| value.checked_mul(u128::from(BFV_ERROR_MULTIPLE_BOUND)))
        .ok_or_else(|| invalid!("BFV key-switch residual bound exceeds deterministic limits"))
}
/// Return the exact residual-multiple bound after one Galois key switch.
///
/// A Galois automorphism preserves the input residual magnitude; switching the transformed secret
/// component back to `s` adds the current key-switch residual bound. This is owner-side exact-lift
/// accounting for the deterministic key-switch bridge, not a public BFV-RNS noise proof.
///
/// # Errors
/// Returns [`BfvError`] when the input bound exceeds centered capacity, the key is invalid, or the
/// output bound overflows/exceeds centered capacity.
pub fn bfv_galois_key_switch_output_residual_multiple_bound(
    params: &BfvParameters,
    galois_key: &BfvGaloisKey,
    input_bound: u128,
) -> Result<u128, BfvError> {
    validate_exact_residual_bound_within_centered_capacity(
        params,
        input_bound,
        "BFV Galois key-switch input residual bound",
    )?;
    validate_galois_key(params, galois_key)?;
    let output_bound = input_bound
        .checked_add(bfv_key_switch_extra_residual_multiple_bound(params)?)
        .ok_or_else(|| {
            invalid!("BFV Galois key-switch output residual bound exceeds deterministic limits")
        })?;
    validate_exact_residual_bound_within_centered_capacity(
        params,
        output_bound,
        "BFV Galois key-switch output residual bound",
    )?;
    Ok(output_bound)
}
/// Return the exact residual-multiple bound for packed-slot `RotateLeft`.
///
/// The helper mirrors [`rotate_packed_ciphertext_slots_left_with_galois_keys`]: every scheduled
/// Galois key switch receives the same input bound, each switched ciphertext is masked by its
/// packed plaintext selector, and the masked contributions are added. This remains a conservative
/// exact-lift diagnostic for the current key-switch bridge.
///
/// # Errors
/// Returns [`BfvError`] when the input bound exceeds centered residual capacity, the rotation is
/// invalid, required Galois keys are missing or malformed, or any intermediate/output bound exceeds
/// centered residual capacity.
pub fn bfv_packed_rotate_left_output_residual_multiple_bound(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    input_bound: u128,
    rotation_steps: u32,
) -> Result<u128, BfvError> {
    params.validate()?;
    validate_exact_residual_bound_within_centered_capacity(
        params,
        input_bound,
        "BFV packed RotateLeft input residual bound",
    )?;
    let schedule = packed_left_rotation_galois_schedule(params, rotation_steps)?;
    validate_galois_key_set(params, galois_keys, "packed RotateLeft")?;
    let mut contribution_bounds = Vec::with_capacity(schedule.len());
    for (automorphism_power, mask_slots) in schedule {
        let galois_key = galois_keys
            .iter()
            .find(|key| key.automorphism_power == automorphism_power)
            .ok_or_else(|| {
                invalid!(
                    "missing BFV Galois key for packed RotateLeft automorphism power {automorphism_power}"
                )
            })?;
        let switched_bound =
            bfv_galois_key_switch_output_residual_multiple_bound(params, galois_key, input_bound)?;
        let mask_plaintext = encode_packed_plaintext_slots(params, &mask_slots)?;
        let masked_bound = bfv_multiply_plaintext_polynomial_output_residual_multiple_bound(
            params,
            switched_bound,
            &mask_plaintext,
        )?;
        contribution_bounds.push(masked_bound);
    }
    match contribution_bounds.as_slice() {
        [] => Err(invalid!(
            "packed RotateLeft produced an empty Galois key schedule"
        )),
        [only] => Ok(*only),
        bounds => bfv_add_output_residual_multiple_bound(params, bounds),
    }
}
/// Return the exact residual-multiple bound after public bootstrap refreshes.
///
/// In the first-release refresh path, each public bootstrap round adds one encrypted-zero mask to
/// the input ciphertext, so the exact residual bound is the input bound plus `rounds *` the seeded
/// encrypted-zero refresh bound. It is a diagnostic for the current refresh format, not the future
/// proof-carrying full bootstrap noise budget.
///
/// # Errors
/// Returns [`BfvError`] when parameters are invalid, zero rounds are requested, the input bound
/// exceeds centered capacity, or the refreshed output bound overflows/exceeds centered capacity.
pub fn bfv_bootstrap_refresh_output_residual_multiple_bound(
    params: &BfvParameters,
    input_bound: u128,
    refresh_rounds: u16,
) -> Result<u128, BfvError> {
    validate_exact_residual_bound_within_centered_capacity(
        params,
        input_bound,
        "BFV bootstrap input residual bound",
    )?;
    invalid_if!(
        refresh_rounds == 0,
        "BFV bootstrap refresh output residual bound requires at least one round"
    );
    let refresh_bound = bfv_encrypted_zero_refresh_residual_multiple_bound(params)?;
    let refresh_bound = refresh_bound
        .checked_mul(u128::from(refresh_rounds))
        .ok_or_else(|| {
            invalid!("BFV bootstrap refresh output residual bound exceeds deterministic limits")
        })?;
    let output_bound = input_bound.checked_add(refresh_bound).ok_or_else(|| {
        invalid!("BFV bootstrap refresh output residual bound exceeds deterministic limits")
    })?;
    validate_exact_residual_bound_within_centered_capacity(
        params,
        output_bound,
        "BFV bootstrap refresh output residual bound",
    )?;
    Ok(output_bound)
}
/// Return the exact residual-multiple bound after key-authorized bootstrap refreshes.
///
/// This variant first validates public bootstrap-key metadata, rejects reserved full-bootstrap
/// mode, and checks the requested round count, then validates the public residual-bound input
/// before inspecting full bootstrap-key shape, so malformed key material cannot mask cheap
/// admission failures.
///
/// # Errors
/// Returns [`BfvError`] when the input bound exceeds centered residual capacity, the requested
/// refresh count is zero or exceeds the key capacity, the bootstrap key is malformed, or the
/// residual-bound calculation fails.
pub fn bfv_bootstrap_key_refresh_output_residual_multiple_bound(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    input_bound: u128,
    refresh_rounds: u16,
) -> Result<u128, BfvError> {
    validate_bootstrap_key_refresh_round_count_request(
        bootstrap_key,
        refresh_rounds,
        "BFV bootstrap refresh",
    )?;
    validate_exact_residual_bound_within_centered_capacity(
        params,
        input_bound,
        "BFV bootstrap input residual bound",
    )?;
    validate_bootstrap_key_for_refresh_application(params, bootstrap_key)?;
    bfv_bootstrap_refresh_output_residual_multiple_bound(params, input_bound, refresh_rounds)
}
/// Return the centered noise bound after bounded-noise bootstrap refreshes.
///
/// Each diagnostic refresh round adds a rounded-profile encryption-of-zero mask.
/// The conservative output bound is the input bound plus `refresh_rounds` fresh
/// bounded-noise encryption bounds. This models encrypted-zero refresh only;
/// full bootstrapping requires separate noise analysis, and the rounded profile
/// remains unqualified for production.
///
/// # Errors
/// Returns [`BfvError`] when rounded BFV capacity is too narrow, zero rounds are requested, the
/// input bound exceeds rounded-decoding capacity, or the refreshed output bound overflows/exceeds
/// rounded-decoding capacity.
pub fn bfv_bootstrap_refresh_bounded_noise_output_bound(
    params: &BfvParameters,
    input_noise_bound: u128,
    refresh_rounds: u16,
) -> Result<u128, BfvError> {
    if let Err(err) = validate_bfv_bounded_noise_encryption_capacity(params) {
        params.validate()?;
        invalid_if!(
            refresh_rounds == 0,
            "BFV bounded-noise bootstrap refresh output bound requires at least one round"
        );
        return Err(err);
    }
    validate_bounded_noise_bound_within_decoding_capacity(
        params,
        input_noise_bound,
        "BFV bounded-noise bootstrap input bound",
    )?;
    invalid_if!(
        refresh_rounds == 0,
        "BFV bounded-noise bootstrap refresh output bound requires at least one round"
    );
    let refresh_bound = bfv_fresh_bounded_noise_ciphertext_bound(params)?
        .checked_mul(u128::from(refresh_rounds))
        .ok_or_else(|| {
            invalid!(
                "BFV bounded-noise bootstrap refresh output bound exceeds deterministic limits"
            )
        })?;
    let output_bound = input_noise_bound
        .checked_add(refresh_bound)
        .ok_or_else(|| {
            invalid!(
                "BFV bounded-noise bootstrap refresh output bound exceeds deterministic limits"
            )
        })?;
    validate_bounded_noise_bound_within_decoding_capacity(
        params,
        output_bound,
        "BFV bounded-noise bootstrap refresh output bound",
    )?;
    Ok(output_bound)
}
/// Return the centered noise bound after key-authorized bounded-noise bootstrap refreshes.
///
/// This variant first validates public bootstrap-key metadata, rejects reserved full-bootstrap
/// mode, and checks the requested round count, then verifies that the parameter set has enough
/// rounded BFV headroom and that the caller-supplied input bound is representable before validating
/// full bootstrap-key shape.
///
/// # Errors
/// Returns [`BfvError`] when rounded BFV capacity is too narrow, the input bound exceeds
/// rounded-decoding capacity, the requested refresh count is zero or exceeds the key capacity, the
/// bootstrap key is malformed, or the bounded-noise calculation fails.
pub fn bfv_bootstrap_key_refresh_bounded_noise_output_bound(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    input_noise_bound: u128,
    refresh_rounds: u16,
) -> Result<u128, BfvError> {
    validate_bootstrap_key_refresh_round_count_request(
        bootstrap_key,
        refresh_rounds,
        "BFV bounded-noise bootstrap refresh",
    )?;
    validate_bfv_bounded_noise_encryption_capacity(params)?;
    validate_bounded_noise_bound_within_decoding_capacity(
        params,
        input_noise_bound,
        "BFV bounded-noise bootstrap input bound",
    )?;
    validate_bootstrap_key_for_refresh_application(params, bootstrap_key)?;
    bfv_bootstrap_refresh_bounded_noise_output_bound(params, input_noise_bound, refresh_rounds)
}
/// Return the exact plaintext-multiple residual bound for seeded zero refreshes.
///
/// The current first-release refresh masks are BFV encryptions of zero. After decryption, each
/// coefficient is bounded by the public-key residual times the small encryption polynomial plus two
/// fresh small error products: `pk_error * u + e1 + e2 * s`. With ternary `u`/`s` and error
/// multiples bounded by `BFV_ERROR_MULTIPLE_BOUND`, each negacyclic product contributes at most
/// `n * E` plaintext-modulus multiples and the direct error contributes `E`, for `(2n + 1) * E`.
///
/// This is an exact diagnostic bound for the deterministic refresh-key format; it is not the future
/// bounded-RLWE noise budget.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is invalid or the bound exceeds deterministic
/// integer limits.
pub fn bfv_encrypted_zero_refresh_residual_multiple_bound(
    params: &BfvParameters,
) -> Result<u128, BfvError> {
    params.validate()?;
    let degree = u128::from(params.polynomial_degree);
    let error_bound = u128::from(BFV_ERROR_MULTIPLE_BOUND);
    degree
        .checked_mul(2)
        .and_then(|value| value.checked_add(1))
        .and_then(|value| value.checked_mul(error_bound))
        .ok_or_else(|| {
            invalid!("BFV encrypted-zero refresh residual bound exceeds deterministic limits")
        })
}
/// Validate that seeded BFV encryption has enough centered residual headroom.
///
/// The deterministic first-release encryption/refresh format is only admitted when the parameter
/// set can represent the worst-case encrypted-zero residual without crossing the centered `q/t`
/// decoding boundary. This is still an exact-lift diagnostic for the current seeded format, not the
/// final bounded-RLWE noise budget.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is invalid or its centered residual capacity is
/// below [`bfv_encrypted_zero_refresh_residual_multiple_bound`].
pub fn validate_bfv_seeded_encryption_residual_capacity(
    params: &BfvParameters,
) -> Result<(), BfvError> {
    let residual_bound = bfv_encrypted_zero_refresh_residual_multiple_bound(params)?;
    let capacity = centered_residual_multiple_capacity(params);
    invalid_if!(
        capacity < residual_bound,
        "ciphertext_modulus/plaintext_modulus centered capacity {capacity} is below seeded BFV encryption residual bound {residual_bound}"
    );
    Ok(())
}
fn validate_bfv_seeded_bootstrap_refresh_round_capacity(
    params: &BfvParameters,
    refresh_rounds: u16,
    label: &str,
) -> Result<(), BfvError> {
    validate_bfv_seeded_encryption_residual_capacity(params)?;
    invalid_if!(
        refresh_rounds == 0,
        "{label} refresh-round capacity must be greater than zero"
    );
    let refresh_bound = bfv_encrypted_zero_refresh_residual_multiple_bound(params)?;
    let refresh_budget = refresh_bound
        .checked_mul(u128::from(refresh_rounds))
        .ok_or_else(|| {
            invalid!("{label} refresh-round residual budget exceeds deterministic limits")
        })?;
    let capacity = centered_residual_multiple_capacity(params);
    invalid_if!(
        refresh_budget > capacity,
        "{label} refresh-round residual budget {refresh_budget} exceeds centered residual capacity {capacity}"
    );
    Ok(())
}
/// Return the conservative centered noise bound for fresh rounded BFV encryption.
///
/// For public-key residual `e_pk`, ternary encryption mask `u`, fresh error `e1`, fresh error `e2`,
/// and ternary secret `s`, a coefficient of `e_pk * u + e1 + e2 * s` is bounded by `(2n + 1)E`.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is invalid or the bound exceeds deterministic
/// integer limits.
pub fn bfv_fresh_bounded_noise_ciphertext_bound(params: &BfvParameters) -> Result<u128, BfvError> {
    params.validate()?;
    let degree = u128::from(params.polynomial_degree);
    let error_bound = u128::from(BFV_BOUNDED_NOISE_COEFFICIENT_BOUND);
    degree
        .checked_mul(2)
        .and_then(|value| value.checked_add(1))
        .and_then(|value| value.checked_mul(error_bound))
        .ok_or_else(|| invalid!("BFV fresh rounded-noise bound exceeds deterministic limits"))
}
/// Validate that rounded BFV encryption has enough decoding headroom.
///
/// # Errors
/// Returns [`BfvError`] when parameters are invalid or the rounded plaintext scale cannot hold the
/// conservative fresh encryption noise bound.
pub fn validate_bfv_bounded_noise_encryption_capacity(
    params: &BfvParameters,
) -> Result<(), BfvError> {
    let noise_bound = bfv_fresh_bounded_noise_ciphertext_bound(params)?;
    let capacity = rounded_plaintext_decoding_capacity(params)?;
    invalid_if!(
        capacity < noise_bound,
        "rounded BFV decoding capacity {capacity} is below fresh encryption noise bound {noise_bound}"
    );
    Ok(())
}
fn validate_bfv_bounded_noise_bootstrap_refresh_round_capacity(
    params: &BfvParameters,
    refresh_rounds: u16,
    label: &str,
) -> Result<(), BfvError> {
    validate_bfv_bounded_noise_encryption_capacity(params)?;
    invalid_if!(
        refresh_rounds == 0,
        "{label} refresh-round capacity must be greater than zero"
    );
    let refresh_bound = bfv_fresh_bounded_noise_ciphertext_bound(params)?;
    let refresh_budget = refresh_bound
        .checked_mul(u128::from(refresh_rounds))
        .ok_or_else(|| {
            invalid!("{label} refresh-round noise budget exceeds deterministic limits")
        })?;
    let capacity = rounded_plaintext_decoding_capacity(params)?;
    invalid_if!(
        refresh_budget > capacity,
        "{label} refresh-round noise budget {refresh_budget} exceeds centered decoding capacity {capacity}"
    );
    Ok(())
}
