fn validate_bfv_full_bootstrap_generated_proof_key_pair_v1(
    prover_key: &BfvFullBootstrapProofKeyV1,
    verifier_key: &BfvFullBootstrapProofKeyV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_proof_key_pair_profile_match_v1(prover_key, verifier_key)?;
    let prover_material =
        decode_bfv_full_bootstrap_proof_key_material_envelope_from_key_v1(prover_key)?;
    let verifier_material =
        decode_bfv_full_bootstrap_proof_key_material_envelope_from_key_v1(verifier_key)?;
    invalid_if!(
        prover_material.native_key_material == verifier_material.native_key_material,
        "BFV full-bootstrap prover-key material must be distinct from verifier-key material"
    );
    validate_bfv_full_bootstrap_native_proof_key_pair_circuit_binding_from_envelopes_v1(
        &prover_material,
        &verifier_material,
    )?;
    invalid_if!(
        prover_key.proof_key_pair_commitment != verifier_key.proof_key_pair_commitment,
        "BFV full-bootstrap proof-key pair commitment differs between prover and verifier keys"
    );
    let expected_commitment =
        bfv_full_bootstrap_proof_key_pair_commitment_v1(prover_key, verifier_key)?;
    invalid_if!(
        prover_key.proof_key_pair_commitment != expected_commitment,
        "BFV full-bootstrap proof-key pair commitment does not match prover/verifier key material"
    );
    validate_bfv_full_bootstrap_proof_key_material_commitment_binding_v1(
        BfvFullBootstrapCircuitArtifactRoleV1::ProverKey,
        prover_key,
    )?;
    validate_bfv_full_bootstrap_proof_key_material_commitment_binding_v1(
        BfvFullBootstrapCircuitArtifactRoleV1::VerifierKey,
        verifier_key,
    )?;
    Ok(())
}
fn validate_bfv_full_bootstrap_native_proof_key_pair_circuit_binding_v1(
    prover_key: &BfvFullBootstrapProofKeyV1,
    verifier_key: &BfvFullBootstrapProofKeyV1,
) -> Result<(), BfvError> {
    let prover_material =
        decode_bfv_full_bootstrap_proof_key_material_envelope_from_key_v1(prover_key)?;
    let verifier_material =
        decode_bfv_full_bootstrap_proof_key_material_envelope_from_key_v1(verifier_key)?;
    validate_bfv_full_bootstrap_native_proof_key_pair_circuit_binding_from_envelopes_v1(
        &prover_material,
        &verifier_material,
    )
}
fn validate_bfv_full_bootstrap_native_proof_key_pair_circuit_binding_from_envelopes_v1(
    prover_material: &BfvFullBootstrapProofKeyMaterialEnvelopeV1,
    verifier_material: &BfvFullBootstrapProofKeyMaterialEnvelopeV1,
) -> Result<(), BfvError> {
    let prover_native = decode_bfv_full_bootstrap_native_proof_key_material_v1(
        &prover_material.native_key_material,
    )?;
    let verifier_native = decode_bfv_full_bootstrap_native_proof_key_material_v1(
        &verifier_material.native_key_material,
    )?;
    invalid_guards! {
        prover_native.native_payload_circuit_id != verifier_native.native_payload_circuit_id
        => ("BFV full-bootstrap native proof-key pair circuit id does not match"),
        prover_native.native_circuit_fingerprint != verifier_native.native_circuit_fingerprint
        => ("BFV full-bootstrap native proof-key pair circuit fingerprint does not match"),
    }
    Ok(())
}
fn validate_bfv_full_bootstrap_proof_key_registered_profile_v1(
    params: &BfvParameters,
    max_bootstrap_depth: u16,
    key: &BfvFullBootstrapProofKeyV1,
) -> Result<(), BfvError> {
    invalid_guards! {
        key.parameter_digest != registered_bfv_parameter_digest(params)?
        => ("BFV full-bootstrap proof key parameter digest does not match registered BFV parameters"
        ),
        key.rns_modulus_chain_digest != registered_bfv_rns_modulus_chain_digest(params)? => (
            "BFV full-bootstrap proof key RNS modulus-chain digest does not match registered BFV parameters"
        ),
        key.key_switch_decomposition_chain_digest
        != registered_bfv_key_switch_decomposition_chain_digest(params)? => (
            "BFV full-bootstrap proof key key-switch decomposition-chain digest does not match registered BFV parameters"
        ),
        key.centered_scale_round_source_chain_digest
        != registered_bfv_centered_scale_round_source_chain_digest(params)? => (
            "BFV full-bootstrap proof key centered scale-round source-chain digest does not match registered BFV parameters"
        ),
        key.max_bootstrap_depth != max_bootstrap_depth
        => ("BFV full-bootstrap proof key max bootstrap depth does not match artifact envelope"),
    }
    Ok(())
}
fn validate_bfv_full_bootstrap_proof_key_artifact_profile_v1(
    artifact: &BfvFullBootstrapCircuitArtifactPayloadV1,
    max_bootstrap_depth: u16,
    key: &BfvFullBootstrapProofKeyV1,
) -> Result<(), BfvError> {
    invalid_guards! {
        key.parameter_digest != artifact.parameter_digest
        => ("BFV full-bootstrap proof key parameter digest does not match artifact envelope"),
        key.rns_modulus_chain_digest != artifact.rns_modulus_chain_digest
        => ("BFV full-bootstrap proof key RNS modulus-chain digest does not match artifact envelope"
        ),
        key.key_switch_decomposition_chain_digest != artifact.key_switch_decomposition_chain_digest
        => (
            "BFV full-bootstrap proof key key-switch decomposition-chain digest does not match artifact envelope"
        ),
        key.centered_scale_round_source_chain_digest
        != artifact.centered_scale_round_source_chain_digest => (
            "BFV full-bootstrap proof key centered scale-round source-chain digest does not match artifact envelope"
        ),
        key.max_bootstrap_depth != artifact.max_bootstrap_depth
        || key.max_bootstrap_depth != max_bootstrap_depth
        => ("BFV full-bootstrap proof key max bootstrap depth does not match artifact envelope"),
    }
    Ok(())
}
fn full_bootstrap_artifact_label_for_role(
    role: BfvFullBootstrapCircuitArtifactRoleV1,
) -> &'static str {
    match role {
        BfvFullBootstrapCircuitArtifactRoleV1::CoefficientToSlotKey => {
            "BFV full-bootstrap coefficient-to-slot key artifact"
        }
        BfvFullBootstrapCircuitArtifactRoleV1::SlotToCoefficientKey => {
            "BFV full-bootstrap slot-to-coefficient key artifact"
        }
        BfvFullBootstrapCircuitArtifactRoleV1::BlindRotationKey => {
            "BFV full-bootstrap blind-rotation key artifact"
        }
        BfvFullBootstrapCircuitArtifactRoleV1::SampleExtractionKey => {
            "BFV full-bootstrap sample-extraction key artifact"
        }
        BfvFullBootstrapCircuitArtifactRoleV1::Accumulator => {
            "BFV full-bootstrap accumulator artifact"
        }
        BfvFullBootstrapCircuitArtifactRoleV1::ProofPublicInputSchema => {
            "BFV full-bootstrap proof public-input schema artifact"
        }
        BfvFullBootstrapCircuitArtifactRoleV1::ArithmeticAirConstraintSystem => {
            "BFV full-bootstrap arithmetic AIR constraint-system artifact"
        }
        BfvFullBootstrapCircuitArtifactRoleV1::ProverKey => {
            "BFV full-bootstrap prover-key artifact"
        }
        BfvFullBootstrapCircuitArtifactRoleV1::VerifierKey => {
            "BFV full-bootstrap verifier-key artifact"
        }
    }
}
fn full_bootstrap_material_digest_for_role(
    material: &BfvFullBootstrapCircuitMaterialV1,
    role: BfvFullBootstrapCircuitArtifactRoleV1,
) -> &Hash {
    match role {
        BfvFullBootstrapCircuitArtifactRoleV1::CoefficientToSlotKey => {
            &material.coefficient_to_slot_key_digest
        }
        BfvFullBootstrapCircuitArtifactRoleV1::SlotToCoefficientKey => {
            &material.slot_to_coefficient_key_digest
        }
        BfvFullBootstrapCircuitArtifactRoleV1::BlindRotationKey => {
            &material.blind_rotation_key_digest
        }
        BfvFullBootstrapCircuitArtifactRoleV1::SampleExtractionKey => {
            &material.sample_extraction_key_digest
        }
        BfvFullBootstrapCircuitArtifactRoleV1::Accumulator => &material.accumulator_digest,
        BfvFullBootstrapCircuitArtifactRoleV1::ProofPublicInputSchema => {
            &material.proof_public_input_schema_digest
        }
        BfvFullBootstrapCircuitArtifactRoleV1::ArithmeticAirConstraintSystem => {
            &material.arithmetic_air_constraint_system_artifact_digest
        }
        BfvFullBootstrapCircuitArtifactRoleV1::ProverKey => &material.prover_key_digest,
        BfvFullBootstrapCircuitArtifactRoleV1::VerifierKey => &material.verifier_key_digest,
    }
}
fn decode_full_bootstrap_artifact_payload(
    params: &BfvParameters,
    material: &BfvFullBootstrapCircuitMaterialV1,
    label: &str,
    expected_role: BfvFullBootstrapCircuitArtifactRoleV1,
    bytes: &[u8],
    expected_digest: &Hash,
) -> Result<BfvFullBootstrapCircuitArtifactPayloadV1, BfvError> {
    validate_full_bootstrap_artifact_envelope_bytes_shape_v1(
        label,
        expected_role.max_bytes(),
        bytes,
    )?;
    let actual_digest = Hash::new(bytes);
    if actual_digest != *expected_digest {
        if let Ok(artifact) =
            norito::decode_canonical::<BfvFullBootstrapCircuitArtifactPayloadV1>(bytes)
        {
            validate_bfv_full_bootstrap_artifact_profile_digest_preflight_v1(label, &artifact)?;
        } else {
            validate_bfv_full_bootstrap_bytes_not_placeholder_text_or_binary_decorated(
                label, bytes,
            )?;
        }
        return Err(invalid!(
            "{label} digest does not match governed full-bootstrap material"
        ));
    }
    let artifact = norito::decode_canonical::<BfvFullBootstrapCircuitArtifactPayloadV1>(bytes)
        .map_err(|err| {
            invalid!(
                "{label} must use canonical v1 bytes containing a Norito-encoded BFV full-bootstrap artifact payload: {err}"
            )
        })?;
    validate_full_bootstrap_artifact_payload_profile(
        params,
        material,
        label,
        expected_role,
        &artifact,
    )?;
    validate_full_bootstrap_artifact_envelope_canonical_bytes_v1(label, bytes, &artifact)?;
    Ok(artifact)
}
fn validate_full_bootstrap_artifact_envelope_bytes_shape_v1(
    label: &str,
    max_bytes: usize,
    bytes: &[u8],
) -> Result<(), BfvError> {
    invalid_guards! {
        bytes.is_empty() => ("{label} must not be empty"),
        bytes.len() > max_bytes => ("{label} length {} exceeds maximum {}",
            bytes.len(),
            max_bytes),
        bytes.iter().all(|&byte| byte == 0) => ("{label} must not be all-zero"),
    }
    Ok(())
}
fn validate_full_bootstrap_artifact_inner_payload_shape_v1(
    label: &str,
    payload: &[u8],
) -> Result<(), BfvError> {
    invalid_guards! {
        payload.is_empty() => ("{label} payload must not be empty"),
        payload.iter().all(|&byte| byte == 0) => ("{label} payload must not be all-zero"),
    }
    let payload_label = format!("{label} payload");
    validate_bfv_full_bootstrap_bytes_not_placeholder_text(&payload_label, payload)?;
    validate_bfv_full_bootstrap_binary_decorated_placeholder_text(&payload_label, payload)?;
    Ok(())
}
fn validate_bfv_full_bootstrap_bytes_not_placeholder_text(
    label: &str,
    bytes: &[u8],
) -> Result<(), BfvError> {
    if !bytes
        .iter()
        .all(|byte| byte.is_ascii_graphic() || byte.is_ascii_whitespace())
    {
        return Ok(());
    }
    invalid_if!(
        bytes.iter().all(u8::is_ascii_whitespace),
        "{label} must not be blank text"
    );
    validate_bfv_full_bootstrap_bytes_do_not_contain_placeholder_marker(label, bytes)
}
fn validate_bfv_full_bootstrap_bytes_do_not_contain_placeholder_marker(
    label: &str,
    bytes: &[u8],
) -> Result<(), BfvError> {
    let mut normalized = Vec::with_capacity(bytes.len());
    normalized.extend(bytes.iter().map(u8::to_ascii_lowercase));
    invalid_if!(
        bfv_full_bootstrap_ascii_text_contains_placeholder_marker(&normalized),
        "{label} must not contain placeholder text"
    );
    Ok(())
}
fn validate_bfv_full_bootstrap_binary_decorated_placeholder_text(
    label: &str,
    bytes: &[u8],
) -> Result<(), BfvError> {
    let is_text_byte = |byte: &u8| byte.is_ascii_graphic() || byte.is_ascii_whitespace();
    if bytes.iter().all(is_text_byte) {
        invalid_if!(
            bytes.iter().all(u8::is_ascii_whitespace),
            "{label} must not be blank text"
        );
        return Ok(());
    }
    let mut saw_text_fragment = false;
    let mut saw_nonblank_text_fragment = false;
    for decorated_text in bytes.split(|byte| !is_text_byte(byte)) {
        if decorated_text.is_empty() {
            continue;
        }
        saw_text_fragment = true;
        if decorated_text.iter().all(u8::is_ascii_whitespace) {
            continue;
        }
        saw_nonblank_text_fragment = true;
        validate_bfv_full_bootstrap_bytes_do_not_contain_placeholder_marker(label, decorated_text)?;
    }
    invalid_if!(
        saw_text_fragment && !saw_nonblank_text_fragment,
        "{label} must not be blank text"
    );
    validate_bfv_full_bootstrap_binary_fragmented_placeholder_text(label, bytes)?;
    Ok(())
}
fn validate_bfv_full_bootstrap_binary_fragmented_placeholder_text(
    label: &str,
    bytes: &[u8],
) -> Result<(), BfvError> {
    let mut collapsed_text = Vec::with_capacity(bytes.len());
    collapsed_text.extend(
        bytes
            .iter()
            .filter(|byte| byte.is_ascii_alphanumeric())
            .map(u8::to_ascii_lowercase),
    );
    invalid_if!(
        !collapsed_text.is_empty()
            && bfv_full_bootstrap_collapsed_placeholder_markers()
                .iter()
                .any(|marker| ascii_windows_contains(&collapsed_text, marker)),
        "{label} must not contain placeholder text"
    );
    Ok(())
}
fn validate_bfv_full_bootstrap_bytes_not_placeholder_text_or_binary_decorated(
    label: &str,
    bytes: &[u8],
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_bytes_not_placeholder_text(label, bytes)?;
    validate_bfv_full_bootstrap_binary_decorated_placeholder_text(label, bytes)
}
fn bfv_full_bootstrap_ascii_text_contains_placeholder_marker(normalized: &[u8]) -> bool {
    if BFV_FULL_BOOTSTRAP_ARTIFACT_TEXT_PLACEHOLDER_MARKERS
        .iter()
        .any(|marker| ascii_windows_contains(normalized, marker))
    {
        return true;
    }
    let collapsed_text = ascii_alnum_collapsed(normalized);
    if collapsed_text.is_empty() {
        return false;
    }
    bfv_full_bootstrap_collapsed_placeholder_markers()
        .iter()
        .any(|marker| ascii_windows_contains(&collapsed_text, marker))
}
fn bfv_full_bootstrap_collapsed_placeholder_markers() -> &'static [Vec<u8>] {
    BFV_FULL_BOOTSTRAP_COLLAPSED_PLACEHOLDER_MARKERS
        .get_or_init(|| {
            BFV_FULL_BOOTSTRAP_ARTIFACT_TEXT_PLACEHOLDER_MARKERS
                .iter()
                .filter_map(|marker| {
                    let collapsed_marker = ascii_alnum_collapsed(marker);
                    (collapsed_marker.len()
                        >= BFV_FULL_BOOTSTRAP_COLLAPSED_PLACEHOLDER_MARKER_MIN_BYTES)
                        .then_some(collapsed_marker)
                })
                .collect()
        })
        .as_slice()
}
fn ascii_alnum_collapsed(bytes: &[u8]) -> Vec<u8> {
    bytes
        .iter()
        .copied()
        .filter(u8::is_ascii_alphanumeric)
        .collect()
}
fn ascii_windows_contains(haystack: &[u8], needle: &[u8]) -> bool {
    if needle.is_empty() || needle.len() > haystack.len() {
        return false;
    }
    if needle.len() == 1 {
        return haystack.contains(&needle[0]);
    }
    let first = needle[0];
    let mut offset = 0;
    while let Some(relative_index) = haystack[offset..].iter().position(|byte| *byte == first) {
        let index = offset + relative_index;
        let end = index + needle.len();
        if end > haystack.len() {
            return false;
        }
        if &haystack[index..end] == needle {
            return true;
        }
        offset = index + 1;
    }
    false
}
fn validate_full_bootstrap_artifact_payload_profile(
    params: &BfvParameters,
    material: &BfvFullBootstrapCircuitMaterialV1,
    label: &str,
    expected_role: BfvFullBootstrapCircuitArtifactRoleV1,
    artifact: &BfvFullBootstrapCircuitArtifactPayloadV1,
) -> Result<(), BfvError> {
    validate_full_bootstrap_artifact_inner_payload_shape_v1(label, &artifact.payload)?;
    invalid_if!(
        artifact.role != expected_role,
        "{label} role {:?} does not match expected role {:?}",
        artifact.role,
        expected_role
    );
    validate_bfv_full_bootstrap_canonical_circuit_id(
        &format!("{label} circuit id"),
        &artifact.circuit_id,
    )?;
    invalid_if!(
        artifact.circuit_id != material.circuit_id,
        "{label} circuit id does not match governed full-bootstrap material"
    );
    validate_bfv_full_bootstrap_artifact_profile_digest_preflight_v1(label, artifact)?;
    invalid_guards! {
        artifact.parameter_digest != material.parameter_digest
        => ("{label} parameter digest does not match governed full-bootstrap material"),
        artifact.parameter_digest != registered_bfv_parameter_digest(params)?
        => ("{label} parameter digest does not match registered BFV parameters"),
        artifact.rns_modulus_chain_digest != material.rns_modulus_chain_digest
        => ("{label} RNS modulus-chain digest does not match governed full-bootstrap material"),
        artifact.rns_modulus_chain_digest != registered_bfv_rns_modulus_chain_digest(params)?
        => ("{label} RNS modulus-chain digest does not match registered BFV parameters"),
        artifact.key_switch_decomposition_chain_digest
        != material.key_switch_decomposition_chain_digest => (
            "{label} key-switch decomposition-chain digest does not match governed full-bootstrap material"
        ),
        artifact.key_switch_decomposition_chain_digest
        != registered_bfv_key_switch_decomposition_chain_digest(params)?
        => ("{label} key-switch decomposition-chain digest does not match registered BFV parameters"
        ),
        artifact.centered_scale_round_source_chain_digest
        != material.centered_scale_round_source_chain_digest => (
            "{label} centered scale-round source-chain digest does not match governed full-bootstrap material"
        ),
    }
    invalid_if!(
        artifact.centered_scale_round_source_chain_digest
            != registered_bfv_centered_scale_round_source_chain_digest(params)?,
        "{label} centered scale-round source-chain digest does not match registered BFV parameters"
    );
    invalid_if!(
        artifact.max_bootstrap_depth != material.max_bootstrap_depth,
        "{label} max bootstrap depth does not match governed full-bootstrap material"
    );
    Ok(())
}
fn validate_bfv_full_bootstrap_artifact_profile_digest_preflight_v1(
    label: &str,
    artifact: &BfvFullBootstrapCircuitArtifactPayloadV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_digest_material_hashes(
        &format!("{label} artifact envelope"),
        &[
            ("parameter digest", &artifact.parameter_digest),
            (
                "RNS modulus-chain digest",
                &artifact.rns_modulus_chain_digest,
            ),
            (
                "key-switch decomposition-chain digest",
                &artifact.key_switch_decomposition_chain_digest,
            ),
            (
                "centered scale-round source-chain digest",
                &artifact.centered_scale_round_source_chain_digest,
            ),
        ],
    )
}
fn validate_bootstrap_key_entries(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
) -> Result<(), BfvError> {
    if bootstrap_key.mode == BfvBootstrapKeyMode::FullBootstrapV1 {
        return validate_full_bootstrap_key_refresh_material_absent(bootstrap_key);
    }
    validate_ciphertext(params, &bootstrap_key.zero_refresh)?;
    for (index, refresh) in bootstrap_key.round_refreshes.iter().enumerate() {
        validate_ciphertext(params, refresh)?;
        if index == 0 && refresh != &bootstrap_key.zero_refresh {
            return Err(BfvError::ShapeMismatch(
                "bootstrap key zero_refresh must match round_refreshes[0]".to_owned(),
            ));
        }
        if bootstrap_key.round_refreshes[..index]
            .iter()
            .any(|prior| prior == refresh)
        {
            return Err(BfvError::ShapeMismatch(format!(
                "bootstrap key contains duplicate round refresh ciphertext at index {index}"
            )));
        }
    }
    Ok(())
}
fn validate_bootstrap_key_refresh_material_not_inert(
    bootstrap_key: &BfvBootstrapKey,
) -> Result<(), BfvError> {
    if bootstrap_key.mode == BfvBootstrapKeyMode::FullBootstrapV1 {
        return Ok(());
    }
    validate_ciphertext_not_all_zero("bootstrap key zero_refresh", &bootstrap_key.zero_refresh)?;
    for (index, refresh) in bootstrap_key.round_refreshes.iter().enumerate() {
        validate_ciphertext_not_all_zero(
            &format!("bootstrap key round_refreshes[{index}]"),
            refresh,
        )?;
    }
    Ok(())
}
fn validate_bootstrap_key_metadata(key_id: &str, max_refresh_rounds: u16) -> Result<(), BfvError> {
    validate_bootstrap_key_id(key_id)?;
    validate_bootstrap_key_refresh_round_metadata(max_refresh_rounds)
}
fn validate_bootstrap_key_refresh_round_metadata(max_refresh_rounds: u16) -> Result<(), BfvError> {
    invalid_guards! {
        max_refresh_rounds == 0 => ("bootstrap key max_refresh_rounds must be greater than zero"),
        max_refresh_rounds > BFV_BOOTSTRAP_KEY_MAX_REFRESH_ROUNDS => (
            "bootstrap key max_refresh_rounds exceeds the supported limit {BFV_BOOTSTRAP_KEY_MAX_REFRESH_ROUNDS}"
        ),
    }
    Ok(())
}
fn validate_bootstrap_key_refresh_round_index_request(
    bootstrap_key: &BfvBootstrapKey,
    round_index: u16,
    context: &str,
) -> Result<(), BfvError> {
    validate_bootstrap_key_id(&bootstrap_key.key_id)?;
    validate_bootstrap_key_refresh_mode(bootstrap_key)?;
    validate_bootstrap_key_refresh_round_metadata(bootstrap_key.max_refresh_rounds)?;
    validate_bootstrap_refresh_round_index(bootstrap_key, round_index, context)
}
fn validate_bootstrap_key_refresh_round_count_request(
    bootstrap_key: &BfvBootstrapKey,
    refresh_rounds: u16,
    context: &str,
) -> Result<(), BfvError> {
    validate_bootstrap_key_id(&bootstrap_key.key_id)?;
    validate_bootstrap_key_refresh_mode(bootstrap_key)?;
    validate_bootstrap_key_refresh_round_metadata(bootstrap_key.max_refresh_rounds)?;
    validate_bootstrap_refresh_round_count(bootstrap_key, refresh_rounds, context)
}
fn validate_bootstrap_key_refresh_round_index_request_before_rns_corridor(
    bootstrap_key: &BfvBootstrapKey,
    round_index: u16,
    context: &str,
) -> Result<(), BfvError> {
    validate_bootstrap_key_refresh_mode(bootstrap_key)?;
    if !bootstrap_key_has_valid_refresh_round_metadata(bootstrap_key) {
        return Ok(());
    }
    validate_bootstrap_refresh_round_index(bootstrap_key, round_index, context)
}
fn validate_bootstrap_key_refresh_round_count_request_before_rns_corridor(
    bootstrap_key: &BfvBootstrapKey,
    refresh_rounds: u16,
    context: &str,
) -> Result<(), BfvError> {
    validate_bootstrap_key_refresh_mode(bootstrap_key)?;
    invalid_if!(refresh_rounds == 0, "{context} requires at least one round");
    if !bootstrap_key_has_valid_refresh_round_metadata(bootstrap_key) {
        return Ok(());
    }
    validate_bootstrap_refresh_round_count(bootstrap_key, refresh_rounds, context)
}
fn bootstrap_key_has_valid_refresh_round_metadata(bootstrap_key: &BfvBootstrapKey) -> bool {
    (1..=BFV_BOOTSTRAP_KEY_MAX_REFRESH_ROUNDS).contains(&bootstrap_key.max_refresh_rounds)
}
fn validate_bootstrap_key_id(key_id: &str) -> Result<(), BfvError> {
    invalid_if!(key_id.is_empty(), "bootstrap key id must not be empty");
    invalid_if!(
        key_id.len() > BFV_BOOTSTRAP_KEY_ID_MAX_BYTES,
        "bootstrap key id exceeds the maximum supported length {BFV_BOOTSTRAP_KEY_ID_MAX_BYTES}"
    );
    validate_bfv_full_bootstrap_bytes_not_placeholder_text_or_binary_decorated(
        "bootstrap key id",
        key_id.as_bytes(),
    )?;
    invalid_guards! {
        key_id.trim() != key_id
        => ("bootstrap key id must be canonical without surrounding whitespace"),
        !key_id.bytes().all(is_bootstrap_key_id_byte)
        => ("bootstrap key id must contain only ASCII alphanumeric, '.', '_', or '-' bytes"),
    }
    Ok(())
}
fn is_bootstrap_key_id_byte(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-')
}
fn bootstrap_refresh_round_seed(
    domain: &'static [u8],
    key_id: &str,
    max_refresh_rounds: u16,
    seed: &[u8],
    round_index: u16,
) -> [u8; Hash::LENGTH] {
    Hash::new_from_chunks(&[
        domain,
        key_id.as_bytes(),
        &max_refresh_rounds.to_le_bytes(),
        seed,
        &round_index.to_le_bytes(),
    ])
    .into()
}
fn bootstrap_round_refresh(
    bootstrap_key: &BfvBootstrapKey,
    round_index: u16,
) -> Result<&BfvCiphertext, BfvError> {
    bootstrap_key
        .round_refreshes
        .get(usize::from(round_index))
        .ok_or_else(|| {
            invalid!(
                "bootstrap refresh round {round_index} exceeds key max_refresh_rounds {}",
                bootstrap_key.max_refresh_rounds
            )
        })
}
fn validate_bootstrap_refresh_round_count(
    bootstrap_key: &BfvBootstrapKey,
    refresh_rounds: u16,
    context: &str,
) -> Result<(), BfvError> {
    invalid_if!(refresh_rounds == 0, "{context} requires at least one round");
    invalid_if!(
        refresh_rounds > bootstrap_key.max_refresh_rounds,
        "{context} rounds {refresh_rounds} exceeds bootstrap key max_refresh_rounds {}",
        bootstrap_key.max_refresh_rounds
    );
    Ok(())
}
fn validate_bootstrap_refresh_round_index(
    bootstrap_key: &BfvBootstrapKey,
    round_index: u16,
    context: &str,
) -> Result<(), BfvError> {
    invalid_if!(
        round_index >= bootstrap_key.max_refresh_rounds,
        "{context} round index {round_index} exceeds bootstrap key max_refresh_rounds {}",
        bootstrap_key.max_refresh_rounds
    );
    Ok(())
}
fn validate_bfv_rns_modulus_chain(
    chain: &BfvRnsModulusChain,
    params: &BfvParameters,
) -> Result<u128, BfvError> {
    validate_bfv_rns_modulus_chain_with_root_candidate_limit(
        chain,
        params,
        BFV_PRIMITIVE_ROOT_DISCOVERY_MAX_CANDIDATES,
    )
}
fn validate_bfv_rns_modulus_chain_with_root_candidate_limit(
    chain: &BfvRnsModulusChain,
    params: &BfvParameters,
    root_candidate_limit: u64,
) -> Result<u128, BfvError> {
    params.validate()?;
    let root_order = bfv_negacyclic_ntt_root_order(params)?;
    let product = fhe_rns::validate_ntt_modulus_chain(
        &chain.moduli,
        BFV_RNS_MODULUS_CHAIN_MAX_LIMBS,
        params.plaintext_modulus,
        root_order,
        |modulus, order| {
            negacyclic_ntt_root_for_order_with_candidate_limit(modulus, order, root_candidate_limit)
        },
    )
    .map_err(|error| match error {
        ModulusChainError::TooManyLimbs { max_limbs } => {
            invalid!("BFV RNS modulus chain supports at most {max_limbs} limbs")
        }
        ModulusChainError::LimbNotAboveBound { index, bound } => {
            invalid!("BFV RNS modulus limb {index} must exceed plaintext modulus {bound}")
        }
        ModulusChainError::EvenLimb { index } => {
            invalid!("BFV RNS modulus limb {index} must be odd")
        }
        ModulusChainError::NotStrictlyIncreasing { .. } => {
            invalid!("BFV RNS modulus limbs must be strictly increasing")
        }
        ModulusChainError::CompositeLimb { index } => {
            invalid!("BFV RNS modulus limb {index} must be prime")
        }
        ModulusChainError::LimbNotOneModOrder { index, root_order } => {
            invalid!("BFV RNS modulus limb {index} must be 1 mod {root_order}")
        }
        ModulusChainError::NoSupportedRoot { index, root_order } => invalid!(
            "BFV RNS modulus limb {index} has no supported primitive {root_order}-th negacyclic NTT root"
        ),
        ModulusChainError::NotPairwiseCoprime { .. } => {
            invalid!("BFV RNS modulus limbs must be pairwise coprime")
        }
        ModulusChainError::Empty => invalid!("BFV RNS modulus chain must not be empty"),
        ModulusChainError::ProductOverflow => {
            invalid!("BFV RNS modulus-chain product exceeds u128")
        }
    })?;
    invalid_if!(
        product < u128::from(params.ciphertext_modulus),
        "BFV RNS modulus-chain product {product} does not cover ciphertext modulus {}",
        params.ciphertext_modulus
    );
    Ok(product)
}
fn bfv_negacyclic_ntt_root_order(params: &BfvParameters) -> Result<u64, BfvError> {
    u64::from(params.polynomial_degree)
        .checked_mul(2)
        .ok_or_else(|| invalid!("BFV RNS root order exceeds deterministic validation bounds"))
}
fn validate_rns_exact_evaluator_chain(
    params: &BfvParameters,
    chain: &BfvRnsModulusChain,
) -> Result<(), BfvError> {
    let product = validate_bfv_rns_modulus_chain(chain, params)?;
    let addition_required = exact_ciphertext_modulus_addition_rns_bound(params)?;
    invalid_if!(
        product < addition_required,
        "BFV RNS modulus-chain product {product} does not cover exact ciphertext-modulus addition bound {addition_required}"
    );
    let product_required = exact_ciphertext_modulus_negacyclic_product_rns_bound(params)?;
    invalid_if!(
        product < product_required,
        "BFV RNS modulus-chain product {product} does not cover exact ciphertext-modulus negacyclic product bound {product_required}"
    );
    Ok(())
}
fn validate_registered_bfv_rns_negacyclic_roots(
    params: &BfvParameters,
    chain: &BfvRnsModulusChain,
) -> Result<(), BfvError> {
    let root_order = bfv_negacyclic_ntt_root_order(params)?;
    invalid_if!(
        chain.moduli.len() != RAM_LFE_BFV_RNS_NEGACYCLIC_ROOTS_V1.len(),
        "registered BFV RNS root table length does not match the modulus chain"
    );
    for (index, (&modulus, &root)) in chain
        .moduli
        .iter()
        .zip(RAM_LFE_BFV_RNS_NEGACYCLIC_ROOTS_V1.iter())
        .enumerate()
    {
        invalid_if!(
            !is_primitive_root_of_order(modulus, root, root_order),
            "registered BFV RNS root metadata for limb {index} is not a primitive {root_order}-th root"
        );
    }
    Ok(())
}
fn validate_rns_key_switch_decomposition_chain(
    params: &BfvParameters,
    chain: &BfvRnsModulusChain,
    label: &str,
) -> Result<(), BfvError> {
    let product = validate_bfv_rns_modulus_chain(chain, params)?;
    let decomposition_base = u128::from(params.decomposition_base());
    invalid_if!(
        product < decomposition_base,
        "{label} RNS chain product {product} does not cover BFV decomposition base {decomposition_base}"
    );
    Ok(())
}
fn validate_rns_key_switch_basis_extension_chains(
    params: &BfvParameters,
    decomposition_chain: &BfvRnsModulusChain,
    evaluator_chain: &BfvRnsModulusChain,
    label: &str,
) -> Result<(), BfvError> {
    validate_rns_exact_evaluator_chain(params, evaluator_chain)?;
    validate_rns_key_switch_decomposition_chain(params, decomposition_chain, label)?;
    invalid_if!(
        !evaluator_chain
            .moduli
            .as_slice()
            .starts_with(decomposition_chain.moduli.as_slice()),
        "{label} RNS decomposition chain must be a prefix of the evaluator chain"
    );
    Ok(())
}
fn validate_rns_centered_scale_round_source_chain(
    params: &BfvParameters,
    chain: &BfvRnsModulusChain,
    label: &str,
) -> Result<(), BfvError> {
    let product = validate_bfv_rns_modulus_chain(chain, params)?;
    let required = exact_ciphertext_modulus_negacyclic_product_sum_rns_bound(params, 2)?;
    invalid_if!(
        product < required,
        "{label} RNS chain product {product} does not cover centered scale-round product-sum bound {required}"
    );
    Ok(())
}
fn validate_rns_centered_scale_round_basis_extension_chains(
    params: &BfvParameters,
    source_chain: &BfvRnsModulusChain,
    evaluator_chain: &BfvRnsModulusChain,
    label: &str,
) -> Result<(), BfvError> {
    validate_rns_exact_evaluator_chain(params, evaluator_chain)?;
    validate_rns_centered_scale_round_source_chain(params, source_chain, label)?;
    invalid_if!(
        !evaluator_chain
            .moduli
            .as_slice()
            .starts_with(source_chain.moduli.as_slice()),
        "{label} RNS source chain must be a prefix of the evaluator chain"
    );
    Ok(())
}
fn registered_bfv_key_switch_decomposition_chain_for_evaluator(
    params: &BfvParameters,
    evaluator_chain: &BfvRnsModulusChain,
) -> Result<BfvRnsModulusChain, BfvError> {
    let registered_evaluator_chain = registered_bfv_rns_modulus_chain(params)?;
    invalid_if!(
        evaluator_chain.moduli != registered_evaluator_chain.moduli,
        "registered BFV evaluator RNS chain does not match the canonical production chain"
    );
    let required_product =
        u128::from(params.ciphertext_modulus).max(u128::from(params.decomposition_base()));
    let mut product = 1_u128;
    let mut prefix_len = 0_usize;
    for &modulus in &evaluator_chain.moduli {
        product = product
            .checked_mul(u128::from(modulus))
            .ok_or_else(|| invalid!("BFV key-switch decomposition-chain product exceeds u128"))?;
        prefix_len = prefix_len.checked_add(1).ok_or_else(|| {
            invalid!("BFV key-switch decomposition-chain length exceeds deterministic bounds")
        })?;
        if product >= required_product {
            break;
        }
    }
    invalid_if!(
        product < required_product,
        "BFV key-switch decomposition-chain product {product} does not cover required product {required_product}"
    );
    let chain = BfvRnsModulusChain {
        moduli: evaluator_chain.moduli[..prefix_len].to_vec(),
    };
    validate_rns_key_switch_decomposition_chain(
        params,
        &chain,
        "registered BFV key-switch decomposition",
    )?;
    Ok(chain)
}
fn registered_bfv_centered_scale_round_source_chain_for_evaluator(
    params: &BfvParameters,
    evaluator_chain: &BfvRnsModulusChain,
) -> Result<BfvRnsModulusChain, BfvError> {
    let registered_evaluator_chain = registered_bfv_rns_modulus_chain(params)?;
    invalid_if!(
        evaluator_chain.moduli != registered_evaluator_chain.moduli,
        "registered BFV evaluator RNS chain does not match the canonical production chain"
    );
    bfv_centered_scale_round_source_chain_for_evaluator(
        params,
        evaluator_chain,
        "registered BFV centered scale-round source",
    )
}
fn bfv_centered_scale_round_source_chain_for_evaluator(
    params: &BfvParameters,
    evaluator_chain: &BfvRnsModulusChain,
    label: &str,
) -> Result<BfvRnsModulusChain, BfvError> {
    validate_rns_exact_evaluator_chain(params, evaluator_chain)?;
    let required_product = exact_ciphertext_modulus_negacyclic_product_sum_rns_bound(params, 2)?;
    let mut product = 1_u128;
    let mut prefix_len = 0_usize;
    for &modulus in &evaluator_chain.moduli {
        product = product.checked_mul(u128::from(modulus)).ok_or_else(|| {
            invalid!("BFV centered scale-round source-chain product exceeds u128")
        })?;
        prefix_len = prefix_len.checked_add(1).ok_or_else(|| {
            invalid!("BFV centered scale-round source-chain length exceeds deterministic bounds")
        })?;
        if product >= required_product {
            break;
        }
    }
    invalid_if!(
        product < required_product,
        "{label} RNS chain product {product} does not cover required product {required_product}"
    );
    let chain = BfvRnsModulusChain {
        moduli: evaluator_chain.moduli[..prefix_len].to_vec(),
    };
    validate_rns_centered_scale_round_source_chain(params, &chain, label)?;
    Ok(chain)
}
fn checked_rns_modulus_product(moduli: &[u64]) -> Result<u128, BfvError> {
    fhe_rns::checked_modulus_product(moduli).map_err(bfv_rns_error)
}
/// Translate a shared RNS kernel failure into the BFV diagnostic for that condition.
fn bfv_rns_error(error: RnsError) -> BfvError {
    match error {
        RnsError::EmptyChain => invalid!("BFV RNS modulus chain must not be empty"),
        RnsError::ProductOverflow => invalid!("BFV RNS modulus-chain product exceeds u128"),
        RnsError::ZeroModulus => {
            invalid!("BFV RNS reconstructed coefficient reduction exceeds u64")
        }
        RnsError::ResidueCountMismatch { expected, found } => BfvError::ShapeMismatch(format!(
            "RNS coefficient expected {expected} residues, found {found}"
        )),
        RnsError::TooManyLimbs { max_limbs } => {
            invalid!("RNS coefficient exceeds supported limb count {max_limbs}")
        }
        RnsError::ShortLimb { limb_index } => BfvError::ShapeMismatch(format!(
            "RNS polynomial limb {limb_index} is shorter than polynomial_degree"
        )),
        RnsError::ReconstructionOverflow => {
            invalid!("RNS coefficient reconstruction exceeds u128")
        }
        RnsError::LimbNotInvertible { modulus } => {
            invalid!("BFV RNS basis-extension source limb {modulus} is not invertible")
        }
        RnsError::CrtTermOverflow => invalid!("BFV RNS basis-extension CRT term exceeds u128"),
        RnsError::QuotientOverflow => invalid!("BFV RNS basis-extension quotient exceeds u128"),
        RnsError::CenteredSourceExceedsProduct => {
            invalid!("BFV RNS centered source residue exceeds source-chain product")
        }
        RnsError::CenteredExceedsI128 => invalid!("BFV RNS centered reconstruction exceeds i128"),
        RnsError::CenteredExceedsProduct => {
            invalid!("BFV RNS centered reconstruction exceeds modulus-chain product")
        }
        RnsError::CenteredExceedsBound => {
            invalid!("BFV RNS centered reconstruction exceeds exact negacyclic product bound")
        }
    }
}
fn validate_rns_exact_lift_product_bound(
    params: &BfvParameters,
    product: u128,
) -> Result<(), BfvError> {
    let max_raw_coefficient = u128::from(params.polynomial_degree)
        .checked_mul(product)
        .and_then(|value| value.checked_mul(product))
        .ok_or_else(|| {
            invalid!("BFV RNS modulus-chain product exceeds exact-arithmetic overflow bounds")
        })?;
    let max_scaled_coefficient = max_raw_coefficient
        .checked_mul(u128::from(params.plaintext_modulus))
        .ok_or_else(|| {
            invalid!("BFV RNS modulus-chain product exceeds exact-arithmetic overflow bounds")
        })?;
    invalid_if!(
        max_scaled_coefficient > i128::MAX as u128,
        "BFV RNS modulus-chain product exceeds exact-arithmetic overflow bounds"
    );
    Ok(())
}
fn exact_ciphertext_modulus_addition_rns_bound(params: &BfvParameters) -> Result<u128, BfvError> {
    u128::from(params.ciphertext_modulus)
        .checked_mul(2)
        .and_then(|value| value.checked_sub(1))
        .ok_or_else(|| invalid!("BFV RNS exact ciphertext-modulus addition bound exceeds u128"))
}
fn exact_ciphertext_modulus_negacyclic_product_abs_bound(
    params: &BfvParameters,
) -> Result<u128, BfvError> {
    let q_minus_one = u128::from(params.ciphertext_modulus - 1);
    u128::from(params.polynomial_degree)
        .checked_mul(q_minus_one)
        .and_then(|value| value.checked_mul(q_minus_one))
        .ok_or_else(|| {
            invalid!("BFV RNS exact ciphertext-modulus negacyclic product bound exceeds u128")
        })
}
fn exact_centered_ciphertext_modulus_negacyclic_product_abs_bound(
    params: &BfvParameters,
) -> Result<u128, BfvError> {
    let centered_abs = u128::from(params.ciphertext_modulus / 2);
    u128::from(params.polynomial_degree)
        .checked_mul(centered_abs)
        .and_then(|value| value.checked_mul(centered_abs))
        .ok_or_else(|| {
            invalid!(
                "BFV RNS exact centered ciphertext-modulus negacyclic product bound exceeds u128"
            )
        })
}
fn exact_ciphertext_modulus_negacyclic_product_rns_bound(
    params: &BfvParameters,
) -> Result<u128, BfvError> {
    exact_ciphertext_modulus_negacyclic_product_abs_bound(params)?
        .checked_mul(2)
        .and_then(|value| value.checked_add(1))
        .ok_or_else(|| {
            invalid!("BFV RNS exact ciphertext-modulus negacyclic product bound exceeds u128")
        })
}
fn exact_ciphertext_modulus_negacyclic_product_sum_abs_bound(
    params: &BfvParameters,
    product_count: u16,
) -> Result<u128, BfvError> {
    invalid_if!(
        product_count == 0,
        "BFV RNS exact ciphertext-modulus negacyclic product-sum count must be greater than zero"
    );
    exact_centered_ciphertext_modulus_negacyclic_product_abs_bound(params)?
        .checked_mul(u128::from(product_count))
        .ok_or_else(|| {
            invalid!("BFV RNS exact ciphertext-modulus negacyclic product-sum bound exceeds u128")
        })
}
fn exact_ciphertext_modulus_negacyclic_product_sum_rns_bound(
    params: &BfvParameters,
    product_count: u16,
) -> Result<u128, BfvError> {
    exact_ciphertext_modulus_negacyclic_product_sum_abs_bound(params, product_count)?
        .checked_mul(2)
        .and_then(|value| value.checked_add(1))
        .ok_or_else(|| {
            invalid!(
                "BFV RNS exact ciphertext-modulus negacyclic product-sum RNS bound exceeds u128"
            )
        })
}
fn reduce_u128_to_u64_mod(value: u128, modulus: u64) -> Result<u64, BfvError> {
    fhe_modular::reduce_u128_to_u64_mod(value, modulus)
        .ok_or_else(|| invalid!("BFV RNS reconstructed coefficient reduction exceeds u64"))
}
fn reduce_centered_rns_value_to_u64_mod(
    value: u128,
    rns_product: u128,
    centered_abs_bound: u128,
    modulus: u64,
) -> Result<u64, BfvError> {
    fhe_rns::reduce_centered_value_to_u64_mod(value, rns_product, centered_abs_bound, modulus)
        .map_err(bfv_rns_error)
}
fn reduce_centered_rns_value_to_i128(
    value: u128,
    rns_product: u128,
    centered_abs_bound: u128,
) -> Result<i128, BfvError> {
    fhe_rns::reduce_centered_value_to_i128(value, rns_product, centered_abs_bound)
        .map_err(bfv_rns_error)
}
fn validate_rns_polynomial(
    params: &BfvParameters,
    chain: &BfvRnsModulusChain,
    polynomial: &BfvRnsPolynomial,
) -> Result<(), BfvError> {
    params.validate()?;
    if polynomial.residues_by_limb.len() != chain.moduli.len() {
        return Err(BfvError::ShapeMismatch(format!(
            "RNS polynomial expected {} limbs, found {}",
            chain.moduli.len(),
            polynomial.residues_by_limb.len()
        )));
    }
    for (limb_index, (residues, &modulus)) in polynomial
        .residues_by_limb
        .iter()
        .zip(&chain.moduli)
        .enumerate()
    {
        if residues.len() != params.degree() {
            return Err(BfvError::ShapeMismatch(format!(
                "RNS polynomial limb {limb_index} expected polynomial_degree {}, found {}",
                params.polynomial_degree,
                residues.len()
            )));
        }
        if residues.iter().any(|&residue| residue >= modulus) {
            return Err(BfvError::ShapeMismatch(format!(
                "RNS polynomial limb {limb_index} contains a residue outside modulus {modulus}"
            )));
        }
    }
    Ok(())
}
fn validate_rns_polynomial_pair(
    params: &BfvParameters,
    chain: &BfvRnsModulusChain,
    lhs: &BfvRnsPolynomial,
    rhs: &BfvRnsPolynomial,
) -> Result<(), BfvError> {
    chain.validate_for_parameters(params)?;
    validate_rns_polynomial(params, chain, lhs)?;
    validate_rns_polynomial(params, chain, rhs)
}
fn validate_rns_key_switch_digit_polynomials(
    params: &BfvParameters,
    chain: &BfvRnsModulusChain,
    digit_polynomials: &[BfvRnsPolynomial],
    label: &str,
) -> Result<(), BfvError> {
    chain.validate_for_parameters(params)?;
    let expected_digits = params.decomposition_digits()?;
    let base = u128::from(params.decomposition_base());
    let product = chain.product()?;
    invalid_if!(
        product < base,
        "{label} RNS chain product {product} does not cover decomposition base {base}"
    );
    if digit_polynomials.len() != expected_digits {
        return Err(BfvError::ShapeMismatch(format!(
            "{label} expected {expected_digits} decomposition digits, found {}",
            digit_polynomials.len()
        )));
    }
    for (digit_index, digit_polynomial) in digit_polynomials.iter().enumerate() {
        validate_rns_polynomial(params, chain, digit_polynomial)?;
        for (coefficient_index, coefficient) in chain
            .reconstruct_polynomial(params, digit_polynomial)?
            .into_iter()
            .enumerate()
        {
            if coefficient >= base {
                return Err(BfvError::ShapeMismatch(format!(
                    "{label} digit[{digit_index}] coefficient[{coefficient_index}] {coefficient} exceeds decomposition base {base}"
                )));
            }
        }
    }
    Ok(())
}
fn multiply_rns_limb_negacyclic(
    params: &BfvParameters,
    lhs: &[u64],
    rhs: &[u64],
    modulus: u64,
) -> Vec<u64> {
    try_multiply_rns_limb_negacyclic_ntt(params, lhs, rhs, modulus)
        .unwrap_or_else(|| multiply_rns_limb_negacyclic_scalar(params, lhs, rhs, modulus))
}
fn multiply_rns_limb_negacyclic_scalar(
    params: &BfvParameters,
    lhs: &[u64],
    rhs: &[u64],
    modulus: u64,
) -> Vec<u64> {
    fhe_polynomial::negacyclic_mul_mod_schoolbook(lhs, rhs, params.degree(), modulus)
}
fn try_multiply_rns_limb_negacyclic_ntt(
    params: &BfvParameters,
    lhs: &[u64],
    rhs: &[u64],
    modulus: u64,
) -> Option<Vec<u64>> {
    let degree = params.degree();
    if degree == 0 || lhs.len() != degree || rhs.len() != degree || !degree.is_power_of_two() {
        return None;
    }
    let root_order = u64::try_from(degree.checked_mul(2)?).ok()?;
    let psi = negacyclic_ntt_root_for_order(modulus, root_order)?;
    fhe_ntt::negacyclic_multiply_ntt(lhs, rhs, psi, modulus)
}
fn negacyclic_ntt_root_for_order(modulus: u64, order: u64) -> Option<u64> {
    negacyclic_ntt_root_for_order_with_candidate_limit(
        modulus,
        order,
        BFV_PRIMITIVE_ROOT_DISCOVERY_MAX_CANDIDATES,
    )
}
fn negacyclic_ntt_root_for_order_with_candidate_limit(
    modulus: u64,
    order: u64,
    max_candidate: u64,
) -> Option<u64> {
    if order <= 1 || !order.is_multiple_of(2) || modulus <= 2 {
        return None;
    }
    if !(modulus - 1).is_multiple_of(order) {
        return None;
    }
    if let Some(index) = registered_ram_lfe_negacyclic_ntt_root_index(modulus, order) {
        let root = RAM_LFE_BFV_RNS_NEGACYCLIC_ROOTS_V1[index];
        return is_primitive_root_of_order(modulus, root, order).then_some(root);
    }
    primitive_root_of_order_with_candidate_limit(modulus, order, max_candidate)
}
fn registered_ram_lfe_negacyclic_ntt_root_index(modulus: u64, order: u64) -> Option<usize> {
    let registered_order =
        u64::from(ram_lfe_bfv_parameters_v1().polynomial_degree).checked_mul(2)?;
    if order != registered_order {
        return None;
    }
    RAM_LFE_BFV_RNS_MODULI_V1
        .iter()
        .position(|&registered_modulus| registered_modulus == modulus)
}
fn primitive_root_of_order(modulus: u64, order: u64) -> Option<u64> {
    primitive_root_of_order_with_candidate_limit(
        modulus,
        order,
        BFV_PRIMITIVE_ROOT_DISCOVERY_MAX_CANDIDATES,
    )
}
fn reconstruct_rns_coefficient(residues: &[u64], moduli: &[u64]) -> Result<u128, BfvError> {
    fhe_rns::reconstruct_coefficient(residues, moduli).map_err(bfv_rns_error)
}
fn derive_rng(domain: &[u8], seed: &[u8]) -> ChaCha20Rng {
    let material = Zeroizing::new(<[u8; Hash::LENGTH]>::from(Hash::new_from_chunks(&[
        domain, seed,
    ])));
    // SeedableRng consumes an array by value. The retained source seed clears;
    // TODO: adopt a clearing RNG owner; rand_chacha exposes no zeroize support.
    ChaCha20Rng::from_seed(*material)
}
#[cfg(any(test, feature = "bfv-test-fixtures"))]
fn encode_identifier_slots(
    public_parameters: &BfvIdentifierPublicParameters,
    input: &[u8],
) -> Result<Vec<u64>, BfvError> {
    if input.len() > usize::from(public_parameters.max_input_bytes) {
        return Err(BfvError::InputTooLong {
            max_input_bytes: public_parameters.max_input_bytes,
        });
    }
    let mut slots = vec![0_u64; identifier_slot_count(public_parameters.max_input_bytes)?];
    slots[0] = u64::try_from(input.len()).map_err(|_| {
        BfvError::InvalidIdentifierEncoding(
            "identifier byte length does not fit into u64".to_owned(),
        )
    })?;
    for (index, byte) in input.iter().enumerate() {
        slots[index + 1] = u64::from(*byte);
    }
    Ok(slots)
}
fn decode_identifier_slots(
    public_parameters: &BfvIdentifierPublicParameters,
    slots: &[u64],
) -> Result<Vec<u8>, BfvError> {
    let expected_slots = identifier_slot_count(public_parameters.max_input_bytes)?;
    if slots.len() != expected_slots {
        return Err(BfvError::InvalidIdentifierEncoding(format!(
            "identifier slot count {} does not match expected {expected_slots}",
            slots.len()
        )));
    }
    let declared_len = usize::try_from(slots[0]).map_err(|_| {
        BfvError::InvalidIdentifierEncoding("identifier length does not fit into usize".to_owned())
    })?;
    if declared_len > usize::from(public_parameters.max_input_bytes) {
        return Err(BfvError::InvalidIdentifierEncoding(format!(
            "identifier length {declared_len} exceeds max_input_bytes {}",
            public_parameters.max_input_bytes
        )));
    }
    if slots[declared_len + 1..].iter().any(|&slot| slot != 0) {
        return Err(BfvError::InvalidIdentifierEncoding(
            "identifier ciphertext contains non-zero trailing slots".to_owned(),
        ));
    }
    let mut bytes = Zeroizing::new(Vec::with_capacity(declared_len));
    for &slot in &slots[1..=declared_len] {
        bytes.push(u8::try_from(slot).map_err(|_| {
            BfvError::InvalidIdentifierEncoding(format!(
                "identifier byte slot {slot} does not fit into u8"
            ))
        })?);
    }
    // The successfully decoded identifier is intentionally returned to its caller.
    Ok(std::mem::take(&mut *bytes))
}
fn identifier_slot_count(max_input_bytes: u16) -> Result<usize, BfvError> {
    usize::from(max_input_bytes).checked_add(1).ok_or_else(|| {
        BfvError::InvalidIdentifierEncoding(
            "identifier slot count exceeds deterministic bounds".to_owned(),
        )
    })
}
fn decrypt_identifier_slot(
    public_parameters: &BfvIdentifierPublicParameters,
    secret_key: &BfvSecretKey,
    slot: &BfvCiphertext,
) -> Result<u64, BfvError> {
    let plaintext = Zeroizing::new(decrypt(&public_parameters.parameters, secret_key, slot)?);
    if plaintext.first().copied().unwrap_or(0) >= public_parameters.parameters.plaintext_modulus {
        return Err(BfvError::InvalidIdentifierEncoding(
            "identifier slot does not fit into the plaintext modulus".to_owned(),
        ));
    }
    if plaintext
        .iter()
        .skip(1)
        .any(|&coefficient| coefficient != 0)
    {
        return Err(BfvError::InvalidIdentifierEncoding(
            "identifier slot contains non-zero trailing coefficients".to_owned(),
        ));
    }
    Ok(plaintext[0])
}
#[cfg(any(test, feature = "bfv-test-fixtures"))]
fn derive_identifier_slot_seed(seed: &[u8], index: usize) -> Result<[u8; Hash::LENGTH], BfvError> {
    let index = u64::try_from(index).map_err(|_| {
        BfvError::InvalidIdentifierEncoding(
            "identifier slot index does not fit into u64".to_owned(),
        )
    })?;
    Ok(Hash::new_from_chunks(&[IDENTIFIER_SLOT_ENCRYPT_DOMAIN, seed, &index.to_le_bytes()]).into())
}
fn zero_poly(params: &BfvParameters) -> Polynomial {
    fhe_polynomial::zero(params.degree())
}
fn zero_ciphertext(params: &BfvParameters) -> BfvCiphertext {
    BfvCiphertext {
        c0: zero_poly(params),
        c1: zero_poly(params),
    }
}
fn sample_small_poly(params: &BfvParameters, rng: &mut ChaCha20Rng) -> Polynomial {
    (0..params.degree())
        .map(|_| match rng.random_range(0..=2_u8) {
            0 => 0,
            1 => 1,
            _ => params.ciphertext_modulus - 1,
        })
        .collect()
}
fn sample_nonzero_small_poly(params: &BfvParameters, rng: &mut ChaCha20Rng) -> Polynomial {
    loop {
        let polynomial = sample_small_poly(params, rng);
        if polynomial.iter().any(|&coefficient| coefficient != 0) {
            return polynomial;
        }
    }
}
fn sample_nonzero_secret_poly(params: &BfvParameters, rng: &mut ChaCha20Rng) -> Polynomial {
    sample_nonzero_small_poly(params, rng)
}
fn sample_error_poly(params: &BfvParameters, rng: &mut ChaCha20Rng) -> Polynomial {
    (0..params.degree())
        .map(
            |_| match rng.random_range(0..=(BFV_ERROR_MULTIPLE_BOUND * 2)) {
                0 => 0,
                1 => params.plaintext_modulus,
                _ => params.ciphertext_modulus - params.plaintext_modulus,
            },
        )
        .collect()
}
fn sample_nonzero_error_poly(params: &BfvParameters, rng: &mut ChaCha20Rng) -> Polynomial {
    loop {
        let polynomial = sample_error_poly(params, rng);
        if polynomial.iter().any(|&coefficient| coefficient != 0) {
            return polynomial;
        }
    }
}
fn sample_bounded_noise_poly(params: &BfvParameters, rng: &mut ChaCha20Rng) -> Polynomial {
    (0..params.degree())
        .map(
            |_| match rng.random_range(0..=(BFV_BOUNDED_NOISE_COEFFICIENT_BOUND * 2)) {
                0 => 0,
                1 => u64::from(BFV_BOUNDED_NOISE_COEFFICIENT_BOUND),
                _ => params.ciphertext_modulus - u64::from(BFV_BOUNDED_NOISE_COEFFICIENT_BOUND),
            },
        )
        .collect()
}
fn sample_nonzero_bounded_noise_poly(params: &BfvParameters, rng: &mut ChaCha20Rng) -> Polynomial {
    loop {
        let polynomial = sample_bounded_noise_poly(params, rng);
        if polynomial.iter().any(|&coefficient| coefficient != 0) {
            return polynomial;
        }
    }
}
fn sample_uniform_poly(params: &BfvParameters, rng: &mut ChaCha20Rng) -> Polynomial {
    (0..params.degree())
        .map(|_| rng.random_range(0..params.ciphertext_modulus))
        .collect()
}
fn sample_nonzero_uniform_poly(params: &BfvParameters, rng: &mut ChaCha20Rng) -> Polynomial {
    loop {
        let polynomial = sample_uniform_poly(params, rng);
        if polynomial.iter().any(|&coefficient| coefficient != 0) {
            return polynomial;
        }
    }
}
fn encode_plaintext(params: &BfvParameters, plaintext: &[u64]) -> Polynomial {
    let mut encoded = zero_poly(params);
    for (slot, &coefficient) in plaintext.iter().enumerate() {
        encoded[slot] = coefficient % params.plaintext_modulus;
    }
    encoded
}
fn encode_rounded_plaintext(
    params: &BfvParameters,
    plaintext: &[u64],
) -> Result<Polynomial, BfvError> {
    validate_plaintext(params, plaintext)?;
    let scale = rounded_plaintext_scale(params)?;
    let mut encoded = zero_poly(params);
    for (slot, &coefficient) in plaintext.iter().enumerate() {
        encoded[slot] = mul_mod_u64(coefficient, scale, params.ciphertext_modulus);
    }
    Ok(encoded)
}
fn decode_plaintext(params: &BfvParameters, scaled: &[u64]) -> Vec<u64> {
    scaled
        .iter()
        .map(|&coefficient| {
            let centered = center_lift(coefficient, params.ciphertext_modulus);
            mod_t(centered, params.plaintext_modulus)
        })
        .collect()
}
fn decode_rounded_plaintext(params: &BfvParameters, scaled: &[u64]) -> Result<Vec<u64>, BfvError> {
    params.validate()?;
    let scale = i128::from(rounded_plaintext_scale(params)?);
    scaled
        .iter()
        .map(|&coefficient| {
            let centered = center_lift(coefficient, params.ciphertext_modulus);
            let rounded = div_round_nearest_i128(centered, scale)?;
            Ok(mod_t(rounded, params.plaintext_modulus))
        })
        .collect()
}
fn scale_round_raw_product_polynomial(
    params: &BfvParameters,
    raw: &[i128],
) -> Result<Polynomial, BfvError> {
    validate_raw_polynomial_len(params, raw, "raw BFV product polynomial")?;
    raw.iter()
        .map(|&coefficient| scale_round_raw_product_coefficient(params, coefficient))
        .collect()
}
fn scale_round_raw_product_coefficient(
    params: &BfvParameters,
    coefficient: i128,
) -> Result<u64, BfvError> {
    params.validate()?;
    let rounded = fhe_rounding::scale_round_centered(
        coefficient,
        params.plaintext_modulus,
        params.ciphertext_modulus,
    )
    .map_err(|error| match error {
        RoundingError::RoundedExceedsI128 => {
            invalid!("BFV bounded-noise scaled product coefficient exceeds i128")
        }
        _ => invalid!("BFV bounded-noise product scaling exceeds deterministic limits"),
    })?;
    Ok(mod_q(rounded, params.ciphertext_modulus))
}
fn validate_raw_polynomial_len(
    params: &BfvParameters,
    raw: &[i128],
    label: &str,
) -> Result<(), BfvError> {
    params.validate()?;
    let expected = params.degree();
    if raw.len() != expected {
        return Err(BfvError::ShapeMismatch(format!(
            "{label} length {} does not match polynomial_degree {expected}",
            raw.len()
        )));
    }
    Ok(())
}
fn poly_mul_centered_raw(
    params: &BfvParameters,
    lhs: &[u64],
    rhs: &[u64],
    label: &str,
) -> Result<Vec<i128>, BfvError> {
    validate_poly(params, lhs, &format!("{label} lhs"))?;
    validate_poly(params, rhs, &format!("{label} rhs"))?;
    fhe_polynomial::negacyclic_mul_centered_raw(
        lhs,
        rhs,
        params.degree(),
        params.ciphertext_modulus,
    )
    .map_err(|error| match error {
        PolynomialError::ProductOverflow => {
            invalid!("{label} raw product coefficient exceeds deterministic limits")
        }
        PolynomialError::ExponentOverflow => {
            invalid!("{label} raw product exponent exceeds deterministic limits")
        }
        PolynomialError::SubtractionOverflow => {
            invalid!("{label} raw negacyclic subtraction exceeds deterministic limits")
        }
        PolynomialError::AdditionOverflow | PolynomialError::LengthMismatch { .. } => {
            invalid!("{label} raw negacyclic addition exceeds deterministic limits")
        }
    })
}
fn poly_add_centered_raw(lhs: &[i128], rhs: &[i128], label: &str) -> Result<Vec<i128>, BfvError> {
    fhe_polynomial::add_centered_raw(lhs, rhs).map_err(|error| match error {
        PolynomialError::LengthMismatch { lhs, rhs } => BfvError::ShapeMismatch(format!(
            "{label} raw polynomial length mismatch: {lhs} != {rhs}"
        )),
        _ => invalid!("{label} raw polynomial addition exceeds deterministic limits"),
    })
}
fn relinearize(
    params: &BfvParameters,
    relinearization_key: &BfvRelinearizationKey,
    c0: &[u64],
    c1: &[u64],
    c2: &[u64],
) -> Result<BfvCiphertext, BfvError> {
    key_switch(params, &relinearization_key.entries, c0, c1, c2)
}
fn key_switch(
    params: &BfvParameters,
    entries: &[BfvRelinearizationKeyEntry],
    c0: &[u64],
    c1: &[u64],
    switching_component: &[u64],
) -> Result<BfvCiphertext, BfvError> {
    validate_key_switch_inputs(
        params,
        entries,
        c0,
        c1,
        switching_component,
        "key switch key",
    )?;
    let digits = decompose_poly(params, switching_component)?;
    let (out0, out1) = fhe_key_switch::digit_inner_product_pair(
        (c0.to_vec(), c1.to_vec()),
        &digits,
        entries
            .iter()
            .map(|entry| (entry.b.as_slice(), entry.a.as_slice())),
        |digit_poly, row| Ok::<_, BfvError>(poly_mul_mod(params, digit_poly, row)),
        |accumulator, contribution| Ok(poly_add_mod(params, accumulator, contribution)),
    )?;
    Ok(BfvCiphertext { c0: out0, c1: out1 })
}
fn key_switch_from_transformed_secret(
    params: &BfvParameters,
    entries: &[BfvRelinearizationKeyEntry],
    c0: &[u64],
    transformed_c1: &[u64],
) -> Result<BfvCiphertext, BfvError> {
    key_switch(params, entries, c0, &zero_poly(params), transformed_c1)
}
fn key_switch_entries_from_rng(
    params: &BfvParameters,
    source_secret: &[u64],
    target_secret: &[u64],
    rng: &mut ChaCha20Rng,
) -> Result<Vec<BfvRelinearizationKeyEntry>, BfvError> {
    let digits = params.decomposition_digits()?;
    let base = params.decomposition_base();
    let mut scale = 1_u64;
    let mut entries = Vec::with_capacity(digits);
    for _ in 0..digits {
        let entry = loop {
            let key_a = sample_nonzero_uniform_poly(params, rng);
            let key_e = Zeroizing::new(sample_nonzero_error_poly(params, rng));
            let scaled_target = Zeroizing::new(poly_scalar_mul_mod(params, target_secret, scale));
            let product = Zeroizing::new(poly_mul_mod(params, &key_a, source_secret));
            let negated = Zeroizing::new(poly_neg_mod(params, &product));
            let noisy = Zeroizing::new(poly_sub_mod(params, &negated, &key_e));
            let key_b = poly_add_mod(params, &noisy, &scaled_target);
            if key_b.iter().any(|&coefficient| coefficient != 0) {
                break BfvRelinearizationKeyEntry { b: key_b, a: key_a };
            }
        };
        entries.push(entry);
        scale = mul_mod_u64(scale, base, params.ciphertext_modulus);
    }
    Ok(entries)
}
